/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240826-8","meetingId":"r06-cm08","date":"2024年8月26日","dateIso":"2024-08-26","committee":"建設委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"ＪＲ大井町駅線路切換工事に伴う列車の運休","agenda":"ＪＲ大井町駅線路切換工事に伴う列車の運休","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ＪＲで警備員を配置して安全確保に努めていくということですけれども、ほかに何かさらに説明するような安全対策があれば、伺いたいと思います。ぜひ伝えてほしいと思うのですけれども、いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"線路自体は、それよりも北側部分も移設しますので、線路部分の最大の外側への移設幅は８０cmということで、数字を聞いているところです。現在、そちらの団体へ伝達したという事実関係については確認してございません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"視覚障害者の方々にはぜひ伝えていただくように改めて求めておきたいと思います。そうすると、線路を移設すると安全になるというところが分かりづらいのですが、そこを改めてご説明いただけたらと思います。","respondent":"高梨都市計画課長","answer":"分かりにくい説明であったとするならば、おわび申し上げますが、目的は、まず、安全な駅設備とするためにホームを拡幅する必要があると。そのために、当然線路も移設しなければいけないということですので、ホームの拡幅のために、それに伴って線路も移設されるです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"ホーム拡幅のためにということですね。今、７０cm広げると、それが解消されるということなのかというところを最後に伺いたいと思います。","respondent":"高梨都市計画課長","answer":"冒頭説明の中でも申し上げましたとおり、駅近くでＪＲの開発が進められているというところに伴って、ホームの拡幅をするというところで聞いているところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"区としてはどういう立場でいるのか、伺いたいと思いました。どんな立場でＪＲ東日本に、何か要望しているものはないのかということをお伺いしたいと思います。","respondent":"高梨都市計画課長","answer":"区の中心核の大井町駅で電車が止まるですので、それをしっかりとＪＲに対して周知を徹底していただきたいといったところは申し述べているところです。本日ご意見をいただきましたので、速やかにＪＲに申し伝えるとともに、周知についてお願いをしたいと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"４時半までということですけれども、駅利用者の利便性を、できる限りの不便さをなくすという言い方になるのでしょうか。徹底してほしいと求めましたけれども、改めていかがか尋ねました。","respondent":"高梨都市計画課長","answer":"最初の関係団体への周知につきましては、区内部、調整を取りまして、できる限り周知に努めてまいりたいと考えています。２つ目の工事のトラブルにつきましては、まさしく皆様予定を立てて、併せてＪＲ東日本に申し述べてまいりたいと考えています。","id":"exchange-005"}]},{"id":"topic-02","title":"戸越六丁目１８・２０番東地区防災街区整備事業","agenda":"戸越六丁目１８・２０番東地区防災街区整備事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"高さですとか階数、用途など、それを伺いたいと思います。地区の変更というのがありますけれども、この中身というのですか、どういう変更なのかというところを若干伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"まだ事業検討の段階ですが、北側の敷地に関しましては、１３階建ての建物を計画していると。こちらの地区の変更に関しましての内容としては、壁面の位置とか、そういったものをこの地区の中で定める都市計画です。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"建物が１３階ということで、近隣の住民の方の意見もぜひ取り入れて反映していってほしいと求めましたが、伺いたいと思います。こうした方々の中でどこまで合意が図られているのかというところも伺います。","respondent":"小川木密整備推進課長","answer":"はまちづくりの検討の中でのご意見、商店街のにぎわいの継続であったり活性化、そういったものもご意見として出ていたところです。１３名中の１２名の方は合意いただいておりまして、残り１名の方に関しましては、確認が取れていないといったところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"流れ上、３分の２以上の合意があれば進めていけるということになってしまいますので、そうした形で区としても進めてほしいと求めました。いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"委員おっしゃられるとおり、合意に関しましては、我々も同じように思っているところですので、組合には、引き続き全員合意をしっかりと目指すように、これからも協議はしていきたいと考えています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"補助額、現状では予定額だと思いますけれども、伺いたいと思います。それと、壁面後退により空地ができるということですけれども、この空地には何を造るのか、伺いたいと思います。","respondent":"小川木密整備推進課長","answer":"事業をまだ検討中の段階でして、事業費等も含めて、今のところまだ検討中といったところです。商店街のにぎわいであったり、また、防災性の向上につながるような空地の活用というのが見込まれるのではないかと考えています。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"検討中だということは今ご説明にあったのですが、ということは、区は把握していないということなのか伺います。建物の中で何か提供される部分があるのか分かりませんけれども、空地についても具体的に区は把握していないのか、伺います。","respondent":"小川木密整備推進課長","answer":"これから事業計画がしっかりと検討される中で、我々もしっかりと把握していきたいと考えています。なかなか空地の創出というのは難しいといったところでは、できる限り生まれてくる空地につきましては、しっかりと活用していきたいと考えています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"７日には、何ならイメージ図というのですか、カラー刷りで参加者には配られるのです。こういう姿勢を私は改めるべきだと思いますが、いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"都市計画の説明会の後に、準備組合から権利者の皆様に、事業の今のところの概要みたいなものがご報告されると聞いてあります。まずは我々も権利者様に対して、準備組合のほうから権利者様に現段階の事業のご説明をしていただくというような形になってあります。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"今日の報告は、この場所でこういう計画でこういう説明会があります、その報告なのに、準備組合を用意した資料をなぜ委員会に示すことができないのか。もっと言えば、権利者には示すけれども、議会には示せない理由は何か、伺います。","respondent":"小川木密整備推進課長","answer":"今後の検討の中で変更されてくることも出てくるといったところでは、やはり準備組合のほうで、我々も準備組合から伺っていたところです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"都市計画の手続に入ることが視野に入っているにもかかわらず概要を示せない、その理由を、変更があるからと今おっしゃいましたよね。今後変更があるものは議会には説明できないということか尋ねました。","respondent":"小川木密整備推進課長","answer":"変更という言葉でさせていただきましたが、あくまでもまだ事業計画が固まっていないので、変わるおそれがあるといったところで用いたものです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"では、固まったものしか議会には示せないということか尋ねました。","respondent":"小川木密整備推進課長","answer":"事業計画がまだしっかりと方向性が見いだせていない中で、まだ権利者様にもお伝えしていないといったところでは、まずは先に権利者の皆様にご説明をするといったところで、このような流れになっているのかといったところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"建物の所有者も含めて、なぜここだけキノコみたいな、軸の部分というのですか。そこをご説明いただきたいです。","respondent":"小川木密整備推進課長","answer":"南側の「補助第２９号線」という文字が書かれているところでよろしいでしょうか。単独で建て替えたいといったようなご意見をいただいておりまして、今回のこの防災街区整備地区の中には含むことができなかったといったような形です。","id":"exchange-015"},{"speaker":"中塚委員","kind":"確認","question":"そういう姿勢は改めるべきだと先ほど質問しましたので、この点をもう一度伺います。１人の方は合意しないけれども、３分の２以上で推し進めていってしまう、それぞれいかがか尋ねました。","respondent":"高梨都市計画課長、小川木密整備推進課長","answer":"議会にも説明会の開催の予定とともに、まだ地権者の方々中心で、ここの自分たちが住むこの地区をどうしたいのかという案を考えている段階。都市計画の手続も進めなければいけないということで… 接道ができていない建物が４棟ございまして、一定必要なエリアを設定した中で、現在の段階で１名の方の意思確認というものが取れていないといった状況です。","id":"exchange-016"}]},{"id":"topic-03","title":"グリーンスローモビリティの実証運行の実施","agenda":"グリーンスローモビリティの実証運行の実施","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"基本的にはやはり住民の地域の移動を保証するということで、地域の方の利便性がよくなるように進めてほしいと求めました。今、コミバスもやっておりますが、役割の違いを伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"やはり地域の交通移動の手段を確保するということで、公的助成を受けながらコミュニティで地域の利便性を図っていくです。都市部においては、観光または地域活性化の手段として活用されているところも多く、品川区においてもそのような形で活用していければと考えています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"北品川駅から旧東海道、天王洲アイルというような循環ルートになっていますが、ここのルートにした理由を伺いたいと思います。無料にした理由を伺いたいのと、今後、実施していく中でも無料にするのかどうかというところを伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"今回は北品川から旧東海道、そして天王洲というルートが、初回の実証運行についてはふさわしいという形で選定しています。２点目、またはグリーンスローモビリティのルート、在り方を考えていければと考えています。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"そこを最後に伺いたいのと、そうしたその後西大井の循環ルートでも利用していくということが考えられるのかと思ったのですけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"区としてどこまでどういう形でできるのかというのは、申し訳ございませんが、これから考えさせていただければと考えています。最高速度は２０km未満ということでございまして、平均して車は四、現実的に警察の許可を得るのは難しいのではないかと考えています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"警察の許可がないということは、協議はしてみたのかというところを伺いたいのです。ぜひ進めていただきたいという思いで質問いたしますけれども、その経過を説明するよう求めました。","respondent":"櫻木地域交通政策課長","answer":"もしくは地域活性化という観点から、基本的に西大井循環ルートというよりは、そのほかの観光資源があるようなところを中心に検討しています。４月から検討を進めてまいりまして、かなり警察と様々協議を積み重ねてまいりまして、ハードな道のりなのかと考えています。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"要するに、西大井循環ルートは、区としてはどうしたいのかというところの区のスタンスを改めて伺いたいと思います。何とかこの地域を通していただきたいと思うのですが、要するに、西大井地域をどうするのかということを伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"こちらについて、引き続き区として何らかの交通的な課題解決に向けて努力をしていきたいという思いは変わってございません。今回、その辺りを総合的に考えて、どういう形で解決していくかというのは今後も検討してまいりたいと考えています。","id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"１６日からは乗客の数も減る、検討とか議論の俎上の中にあったかどうか分からないけれども、馬車もグリーンスローモビリティですよね。これまでも出てきていると思うのだけれども、その辺の展開についてももしあれば、説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"人力車等もあった時代もあったかと思いますので、そういう形で歴史を活用していくような形で、何かしら観光と協力していければいいかと考えています。","id":"exchange-022"},{"speaker":"つる委員","kind":"意見","question":"どうしたらいいのだろうと。なので、そういった観点も含めて、これはここの実証実験を通しながら、そういった視野もぜひ入れながら、検討してもらえたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-04","title":"安全性確保対策を検討するバス停留所","agenda":"安全性確保対策を検討するバス停留所","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"バス停の前に点字ブロックをぜひつけていただきたいというお話を私も伺っていまして、あそこだといっても、バス停のここの位置が分からないのです。ぜひそういう視点も持っていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川崎土木管理課長","answer":"今回移設したバス停につきましては、確かに点字ブロックというものは整備されておりません。確かに障害のある方、また、高齢の方とか、様々な方がご利用されますので、今後も各関係者と連携しながら適切に対応はしていきたいと考えております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"壁際ではないだけに、手探りのようにバス停の位置を確認するという話を聞いて、ぜひやっていくべきだと思うのです。バス事業者がつけるべきなのか、わざわざ位置を変えて安全性を高めたいという視点でやっているわけですから、改めていかがか尋ねました。","respondent":"森道路課長","answer":"道路課長からお答えをしますけれども、物理的に可能であれば、設置をしていきたいと考えております。その辺も含めて、ご要望のあるところを順次お伺いをして、しっかりとつけていければと思っています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、１点気になるのが、要望のあったところをつけていただけるということで、本当にありがとうあります。最後、要望だけして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-05","title":"（仮称）勝島人道橋整備工事説明会","agenda":"（仮称）勝島人道橋整備工事説明会","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"先ほども少し説明がありましたけれども、周辺住民の方含めて、しっかり説明会があるということを周知してほしいと求めました。何かご答弁があれば、伺いたいと思います。","respondent":"森道路課長","answer":"これまで勝島人道橋の説明会については、周辺地域、広い範囲で８,０００戸でしたか、ビラをまいております。説明会に参加していただいた方、２回やっておりますけれども、しっかりと周知をしていきたいと考えています。","id":"exchange-027"},{"speaker":"中塚委員","kind":"確認","question":"いろいろあるでしょうから、そういう視点も必要かと思ったので、質問させていただきました。いかがか尋ねました。","respondent":"森道路課長","answer":"逆に、今度、出島の部分については、スロープを設けるための出島の部分というような形になってまいります。車椅子を自力で上っていくという方のことを考慮いたしますと、東京都の基準で示されております、そういった観点で設計をさせていただいたところです。","id":"exchange-028"}]},{"id":"topic-06","title":"子供の森公園改修工事説明会の開催","agenda":"子供の森公園改修工事説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところも含めて、今回の説明会も利用者の方にも周知をしていただきたいと思うのですけれども、いかがでしょうかというところ。いかがでしょうかというのと、先ほど駐輪場と幼児用の広場というのですか、を伺いたいと思います。","respondent":"大友公園課長","answer":"テーマとして、新たにかいじゅうのモチーフを考えた複合遊具であったり、これから行う実施設計の中で検討してまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり高齢者の方、グラウンドゴルフで健康な体を維持しているということもありますので、ぜひそこはお願いしたいと。改めて求めたいと思いますが、いかがか尋ねました。","respondent":"大友公園課長","answer":"代替地の確保につきましてなのですけれども、こちらは我々も検討したところではありますが、今、適地としてお示しできるところではございません。そのため、できるだけ短く工事を終わらせるというところの手段で対応していきたいと考えているところです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのですけれども、要するに、もともと何体あったのか。子どもたちの期待に応えていただきたいと思うのですけれども、その点、いかがか尋ねました。","respondent":"大友公園課長","answer":"まず、中に入れるようなかいじゅうを設置してもらいたいという要望があるので、そのようなかいじゅうは森ゾーンの中には設置したいと考えています。まだ固まっていないのですが、そちらも低学年用の遊具という形で、恐竜を用いたものを配置したいと考えているところです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"最近は平仮名併記にしたり、いろいろありますけれども、そこがどうなるのかというのを一つお聞かせください。違ったのだというところもあったので、もう少し委員会資料は充実していただきたいと思うのですけれども、最後にいかがか尋ねました。","respondent":"大友公園課長","answer":"ご説明すべきだったかと思うのですけれども、名称の呼び方はそのままなのですけれども、子供の「供」を平仮名に変更することで考えてあります。委員会資料につきまして、より丁寧に分かる資料という形で工夫していきたいと考えています。","id":"exchange-032"},{"speaker":"澤田委員","kind":"質問","question":"このかいじゅう公園について幾つかお聞きしたいのですけれども、今回整備されるということで、大変うれしいと考えています。それに面する大きな道路に白枠などができたりするとか、そういうことはあるのかというのを聞いてみたいのですが、いかがか尋ねました。","respondent":"大友公園課長","answer":"一番奥のというところでご説明をさせていただいたところなのですけれども、台数をそれほど確保できないのですけれども、同様の場所に駐車場も確保できればという形で検討を進めてまいりたいと考えております。","id":"exchange-033"},{"speaker":"澤田委員","kind":"意見","question":"置いている方も結構よく見かけていたので、そういうのがなくなるのかと思うと、とても安心です。野球場の周りの木があまりないので、その辺、日よけなどはどうお考えなのかというのをお聞かせほしいと求めました。","respondent":"大友公園課長","answer":"暑さ対策なのですけれども、日よけ等の設置というところの具体的な検討までは、ゾーニングの段階ですので、まだ落とせていないところではあるのですけれども、今いただいたご意見も踏まえ、適切な設計を進めてまいりたいと考えています。","id":"exchange-034"},{"speaker":"澤田委員","kind":"質問","question":"ぜひ暑さ対策をしっかりとしていただければと存じます。水遊びできるスペースがあったような気がするのですが、今後はどうなっていくのかというのを、もしお分かりでしたら教えてほしいと求めました。","respondent":"大友公園課長","answer":"今は、シャワー型というのですか、オーバーハングで出ているものの、ミストが出ているかと思います。水と親しめたり、また、涼めたりするような設備を整えたいと考えているところです。","id":"exchange-035"},{"speaker":"澤田委員","kind":"質問","question":"２点ほどあって、そういう施設、飲食店などもあまりないのです。今あるのはジュースの自販機のみということなのですけれども、今後、ジュースの自販機以外にも何か検討されていることとかはあるのか尋ねました。","respondent":"大友公園課長","answer":"販売の類いのところにつきましてなのですけれども、こちら、現状と変わらず、自販機のみの設置になるかと考えています。","id":"exchange-036"},{"speaker":"澤田委員","kind":"質問","question":"いろいろな形での自販機、人がいない状況でも使えるようなものというところで、何かいろいろ検討してほしいと求めました。人工芝になってしまうのか、それとも、今と同様に天然の芝でいかれるのかというところを教えていただけますか尋ねました。","respondent":"大友公園課長","answer":"現状の計画でお答えしますと、天然芝の方向で検討を進めているところです。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"工事のスケジュール等のところで確認という形になるのですけれども、平日と土曜日みたいなイメージでよろしいのでしょうか。安全に注意していただきたいと要望させていただきたいのですけれども、その辺りどのようにお考えか、説明を求めました。","respondent":"大友公園課長","answer":"令和７年度から８年度という２か年にわたっての工事となります。実施することもゼロではないのですが、周りに配慮して、できるだけ音等の振動等少ない工事を実施してまいりたいと考えているところです。","id":"exchange-038"}]},{"id":"topic-07","title":"立会川児童遊園（その３）・旗の台北公園改修工事","agenda":"立会川児童遊園（その３）・旗の台北公園改修工事","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"特にやはり児童遊園ですから、子どもたちにいろいろな体験ができる公園にしていただきたいと。ぜひ実のなる木を植えて、子どもたちに様々な体験をしていただきたいと切に願うのですけれども、いかがか尋ねました。","respondent":"大友公園課長","answer":"それを踏まえまして、既存の樹木、高木、ナンキンハゼを活かすことによる木陰の確保、また、季節ごとに花が咲く植栽を選定したです。春夏秋冬、それぞれに花が咲くというところで、樹種の選定をしたという形になってあります。","id":"exchange-039"},{"speaker":"中塚委員","kind":"提案","question":"季節感はもちろんです。私が提案したのは、そういう視点を持っていただきたいという思いで先ほど質問したのですけれども、その視点はいかがか尋ねました。","respondent":"大友公園課長","answer":"今回、実という形では、ないというところはあるのですけれども、花の充実に着眼させていただいて、樹木選定をしたです。別の公園等々での機会を捉えて、今いただいたご意見等々を反映させていきたいと考えています。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、葉っぱが洗濯物にくっついて、ちくちくするということで、今となっては、早く切ってくれという声を伺うこともあるのです。ぜひそういう視点を大事に設計を進めていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問","question":"木製遊具に変わると思うのですが、その遊具の内容を説明するよう求めました。","respondent":"大友公園課長","answer":"木製遊具、こちらにつきましてなのですけれども、こちらも複合遊具として考えてあります。どのような複合かというところにつきましては、クライミングウオールと、あと平均台、また、展望デッキなどを兼ね備えた遊具とする予定です。","id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"水飲み場の確認と、袋小路のところだと思うのですが、時計はつけないのですか。当然電車もあるので、そこまでの昔からのつくりだからというのはあると思うのだけれども、その辺りも含めてしつらえ、つくりを説明するよう求めました。","respondent":"大友公園課長","answer":"こちらのほう、新たにカエルのモチーフにしたもので改修をする予定です。時計につきましては、資料に記載のとおりなのですけれども、新たに両面から見える形で時計を整備する予定です。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"駐輪スペース、公園の中、どこでもとめていいような感じなのですか。ここはどういう感じになっているのか、説明を求めました。","respondent":"大友公園課長","answer":"ここの立会川児童遊園および旗の台北公園の改修工事におきましては、駐輪目的とした場所、駐輪専用の場所という形で設ける予定はございません。駅に近いというところもあり、駐輪対策も兼ね、駐輪場という形での整備はしないという方向で考えてあります。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/463917?Template=document&Id=6791#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":39467,"voices":138}},{"id":"r06-20240826-9","meetingId":"r06-cm08","date":"2024年8月26日","dateIso":"2024-08-26","committee":"文教委員会","time":"午後 １時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"令和７年度品川区立学校使用教科用図書の採択","agenda":"令和７年度品川区立学校使用教科用図書の採択","exchanges":[{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それに関連して、今の中学校の採択の審議の内容が全然分からないので、できるだけ早く載せていただきたいと。影響してくると思うので、すみません、その２点をお願いします。","respondent":"舩木庶務課長","answer":"これは鋭意、どうしても確認の部分ということもありますので、２か月から３か月要してしまっていることが現状です。なるべく早く議事の内容を公開できるように今後努めていきたいと、このように考えております。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もちろん正確性を求められますし、本当に１か月でも２か月でも早く公開できるようにしていただかないと、これはお願いしますということです。両方そういった記述があったのですけれども、お答えできる範囲で、どうして審議に参加することができないのかお聞きします。","respondent":"丸谷教育総合支援センター長","answer":"委員の１名に関しまして、他業務に関連して教科書採択に差し障りがある業務に従事している、ということで、採択事務には関わらないということで退席をしていただいております。","id":"exchange-002"},{"speaker":"高橋（し）委員","kind":"質問","question":"その関わる業務というものは、もう少し詳しく教えてはいただけないのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"委員それぞれのお立場に関わることですので、この場でのご回答を控えさせていただければと思います。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"この委員の方の見識やお考えというものは大変重要だと思っていて、しっかりした審議というか、そのようなところに影響すると思います。ですから、その方が参加できない状況で、このように教科書選定が進んでいくという動きに関して、どのようにお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"もともと教育関係者ということで、委員おっしゃるとおり、専門性の高いお立場であるということは認識しています。事前に教科書の検討委員会で作成した資料を読み込んでいただいて、そういったものは、ないように審議を進めてきたという認識です。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、このような場で力を発揮していただくことがとても大事だと私は思っています。私としては、何らかの形で審議に参加していただくことを望みたいと思うのですけれども、そこはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"他業務の関係で今回は事務に関わることができなかったわけですけれども、次回は令和９年度に小学校の教科用図書の採択事務を予定しております。その際に、その委員の先生の業務の関係もありますので、そのときそのときで判断をしていければと考えています。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"意見","question":"それが令和５年度の時点で、令和６年度はこうすると変わったのです。そして令和７年度もそれでいこうというような話だったのですけれども、もし分かれば、その辺の話をお尋ねしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"全ての会社の教科書を比較して検討した上で、今後４年間については現在使っている教科書で進めていくことが望ましいと、判断されたものです。そのことによって学力の低下を招くような考えでは、そうした、また学力の向上にもつなげていきたいと考えております。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"は使われている先生方の授業の展開に関してその教科書がどうかということは、またご意見を聞いていくことになると思うので、また別の機会にそういった情報も得ながら質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"令和７年度から新たな教科書がということで、同様の視点から今回はどうなのかということで確認をしようと思ったところ、載っておりませんでした。議事録に関しては２、３か月後ということでありましたけれども、まずお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ホームページへの掲載についてですけれども、今回の採択した教科書会社の一覧、それから採択理由につきまして、まとめているところです。９月に入った時点、９月の上旬から中旬までには、ホームページへの掲載を考えてあります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今の段階における評価をちょっとお伺いしたいのですが、私は社会の中の歴史的分野の教科書についてちょっと確認をさせていただきたいです。変わった理由を採択理由のところに当然書かれるのだろうと思いますが、そこをまずお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"４年に一度教科書採択を実施するわけですけれども、その検定教科書、検定を通った教科書を比較して。出版社を変えるということではなくて、今回検定を通った教科書を比較検討した際に、適切だろうという判断で採択をしております。","id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"そうすると今日の質疑はあまりできないということですね。９月にホームページに掲載されましたら、その他にするのかどうかは別として、ぜひお願いをしたいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"は選定理由を伺ってみないと、その後の深く掘れるのかどうなのかが判断できませんけれども、深掘りも含めて、次回か、今後の委員会に、まずは報告していただくということと、それに併せて今回の教科書採択についての質疑は改めて行っていただきたいということです。","respondent":"こんの委員長","answer":"お答えはできませんので、正副で検討する、あるいは理事者の方ともご検討するということでよろしいでしょうか。では、お預かりします。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"その上でというか、並行してなのですが、今の準備段階における状況は、それは正式に決まってからしか公表できないということなのですかね。他区の比較をする必要があるかどうかは別としても、特に２２区、その状況がもし分かれば教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"なお、他区との比較というところですけれども、例年東京都のほうで取りまとめて、資料を公表しております。令和５年１１月１６日付で、今年度につきましても大体同じぐらい、同様の時期に公表されるものという認識でおります。","id":"exchange-012"},{"speaker":"田中委員","kind":"意見","question":"採択理由、また地区についてはどのような状況だったのかということも含めて、ぜひ正副委員長のご協議の上で、しっかりと質疑をしていきたいという希望がありますので、お取り計らいをよろしくお願いして、今日のところは私の質疑は終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"確認したら、もう１人のほうのユーチューバーの方が不適切なＳＮＳの投稿をして、その方の写真が削除されたということもありました。８月８日に選定をしたというようなお話がありましたけれども、出版社から何らかの説明が教育委員会にあったのかどうか、確認したいと思います。","respondent":"丸谷教育総合支援センター長","answer":"その８月８日の時点で、文部科学省に削除依頼をしているということでの回答をいただきました。その旨を教育委員にも事前にお伝えをして、採択のほうさせていただいたという流れです。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"大丈夫なのかということで、内容についても写真があるだけで、その当該のユーチューバーについての記述はなかったというようなものになっています。教育委員会としては、それを除いて、ほかの内容については問題がない、もしくは適しているという判断をされたということでよろしかったか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"委員おっしゃるとおりで、その他の部分には問題ございませんので、そういった形での採択をしています。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"その掲載された方が不祥事を起こすかどうかということは、今回はアンテナ高く、その上での検討の結果だということを確認させていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問","question":"教育総合支援センターで７月２０日まで行われていた教科書展示に初めて伺いました。例えば近年や前回と比べてなど、どのくらいの方がいらっしゃっているかということがもしお分かりであれば、お聞きしてみたいです。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示会についてのご質問です。教育総合支援センターと品川図書館の２か所で実施をしているところですけれども、お名前を書いていただいた方が延べ９０名いらっしゃいました。","id":"exchange-017"},{"speaker":"せらく委員","kind":"質問","question":"私も初めて伺ってみて、初歩的な部分になるかもしれないのですが、どのように活用をしているのか教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示会の来場者数や、その意見をいただいておりますので、そちらも今取りまとめている最中でございまして、取りまとめが終わったところで、教育委員会会議でも報告を差し上げているところです。","id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"そうしましたら、その教科書採択の会議では、まだ皆様のお声が届かない状態で採択をする会議というようになっているということか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示会のほうの期間と、教科書採択で５回に分けて仮採択と本採択と行っているのですけれども、並行して行っておりますので、当日お越しいただいた方のご意見というものは、教育委員には共有されていない中での仮採択、本採択という形になってあります。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"そうしましたら、いただいたアンケートのお声などは、今後の教科書採択に反映していくというような形で、教育委員会での共有がされるというように認識させていただいてよろしいか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"広く都民、次年度から使用する教科書、ご意見をいただいてそれを教育委員会に反映させるという趣旨で行っているものではございません。","id":"exchange-020"}]},{"id":"topic-02","title":"育児休業にかかる保育認定期間の見直し","agenda":"育児休業にかかる保育認定期間の見直し","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"２点お伺いさせていただきたいと思うのですけれども、いろいろと区民の方から声があって、その辺りの状況をお聞かせいただきたいです。この等のところの部分についてお聞かせほしいと求めました。","respondent":"芝野保育入園調整課長","answer":"品川区でも検討しまして、品川区も負担軽減という考え方の下、今回見直しをすることになりました。２つ目の等ですが、こちらも対象に含めてという形でありますので、等という表現をしています。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"このような規制緩和、喜ばれる施策だと思います。１０月以降、ご理解いただけるような表現での周知をぜひお願いしたいと思いますが、そこだけ確認をさせてほしいと求めました。","respondent":"芝野保育入園調整課長","answer":"実際に周知するときの表現ですが、これから規則改正もするところではありますけれども、規則改正の文言とはまたちょっと変えて、利用者の方に分かりやすい表現で周知、案内をしていきたいと思いますので、ちょっとこれから検討させていただきたいと思います。","id":"exchange-022"}]},{"id":"topic-03","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"そういったときに、たしかご説明の中では、そこについての対応というものはどういった対応をお考えになっていらっしゃるのか。子どもを守るということが、当然第一だと思うのですけれども、そこの考え方を教えてほしいということが２つ目です。","respondent":"長谷川児童相談課長","answer":"それから３点目の、夜間休日の対応についてコールセンター方式を取らせていただきますけれども、委託業者のほうに共有します。最後に、ＡＩ電話応対支援システムについての説明になりますけれども、現在先行区ですと、江戸川区が導入をしております。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１回確認なのですけれども、判断シートをこれから作成されていくということ、他の自治体の事例も見ながらということでした。ここについて、もし予算がついてくるのであれば、議会は喜んで賛成をすると思いますので、それについては要望として伝えします。","respondent":"長谷川児童相談課長","answer":"夜間休日のコールセンター方式による受電の際に、疑わしい通報があった場合、どうするかという趣旨の質問だったかと思います。委員ご指摘のとおり、疑わしい場合は全て区の児童相談所のスーパーバイザーのほうに連絡が来るようになっております。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"ほかにもそのような、何というのでしょうか、都のほうに派遣をされている方がいらっしゃるのかどうか。この１４４名体制で、２４時間対応、まずお伺いしたいと思います。","respondent":"長谷川児童相談課長","answer":"ただ、今後に関しては、当面は区のプロパー職員での運営を行っていくことを基本に考えておりますので、受入れを行う予定は現時点ではありません。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"品川区以外のところから伺ってはいるのですけれども、児童福祉司の方が５人と児童心理司の方が２人ということですが、この数はどうなのでしょうか。もう少し必要なのか、十分なのかということについて、いかがか尋ねました。","respondent":"長谷川児童相談課長","answer":"あるいは育成に関しましては、開設して終わりではなくて、引き続き継続的に努めていく必要があると認識しております。これも非常に重要かつかなり困難な部分であると認識しておりまして、児童福祉司として５年以上、現状ちょっと困難であると考えております。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"しっかりとその人員体制、引き続き整えていただけるように、ご尽力をお願いしたいと思います。今後、今後の児童相談所の中に組み込む中で対応することのほうがより対応できるようになってくるのか、その辺の今お考えはいかがか尋ねました。","respondent":"長谷川児童相談課長","answer":"委員おっしゃるとおり、子ども家庭支援センターと区立児童相談所の役割に関しては、違いはあるものの、児童虐待の対応という部分では同じです。","id":"exchange-027"},{"speaker":"田中委員","kind":"意見","question":"そのようなことではなくて、それこそ子どもの立場に寄り添った組織づくりを、対応をお願いしたいと思います。特に品川独自のものについてとの意見を述べました。","respondent":"長谷川児童相談課長","answer":"一時保護所のレイアウトに関しては公表しておりません。品川区としては、子どもたち一人ひとりの権利に寄り添った支援ができるように、とにかく個別対応ができるような設計を心がけております。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"児童相談業務を区に移管すべきという１つのいいお手本というか、事例として、私は積極的にＰＲすべきだなと。そのことによってこれだけよくなったということが、何でしょうか、じんわりと公表されるというか、伝わるようなことを願いながら、質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西村委員","kind":"質問・要望","question":"定員について伺いたいなと。品川区で１４名と伺っておりまして、この１４名というところを超える可能性はあるのか、伺えればと思います。","respondent":"長谷川児童相談課長","answer":"定員は１４名なのですけれども、また、必要な保護はちゅうちょなく実施する必要があるという考え方もありますので。しかしながら、線引きしているところはありますけれども、大枠の部分では共通認識が持てるようにということで意識をした設計になっております。","id":"exchange-030"},{"speaker":"西村委員","kind":"質問","question":"システムのほうはよく分かりました。新しくできる、品川区以外のお子さんを受け入れるようなことというのは可能性としてあるのかということだけ、最後に尋ねました。","respondent":"長谷川児童相談課長","answer":"品川区の施設になりますけれども、保護するお子さんに関しては、品川区民以外の場合もあり得ると考えております。これは様々なケースが考えられますけれども、他区の児童相談所、またその逆もしかりということで理解していただければと存じます。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問","question":"私からは２点お伺いしたいと考えています。まず第１の窓口というものは、今後、１０月以降は児童相談所になるということなのか尋ねました。","respondent":"長谷川児童相談課長","answer":"しっかり丁寧に説明していきたいと思いますし、区内の掲示板を含めて、様々な媒体を活用して周知徹底を図っていきたいと考えています。新聞報道等でもあるリスク判定、いわゆるリスク判定に関しましては、現状品川区としては導入の予定は、現時点ではありません。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これに関して今区の所管で検討していることは、条例改正、あるいは規則や要綱の変更や、加筆というのですか、そのようなものがあるのでしょうか。した経験があるというか、そのような方がいないと大変な事務ではないかと聞いているのですが、その辺の対応はいかがか尋ねました。","respondent":"染谷子ども家庭支援センター長、長谷川児童相談課長","answer":"それぞれの役割の中で対応が漏れるようなことがないよう対応できるということは、児童相談所、それから子ども家庭支援センター。そういった人材配置の部分でも、非常に大きなメリットがあると考えております。区のほうで一義的に判定業務を行いますが、最終的なジャッジメントは東京都の心身障害者福祉センターのほうで行いますので、入り口の部分になります。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話にあったようにプラスの面、よりよくなると伺ったので、ぜひ緊密に区立児童相談所と連携して進めていってほしいと求めました。非常に、経験をされた方もいらっしゃるということですので、円滑に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"山本副委員長","kind":"質問","question":"私からは１点、相談受付後の対応についてご質問をいたします。ですから、一時保護を施設ではなくて、中には短期預かり里親に預けるというほうがその子のためによいという場合も、考えもあると思います。","respondent":"長谷川児童相談課長","answer":"しかしながら、国の方針にもありますとおり、家庭養育ということをまず優先に考えていきたいと考えております。それから入所予定先の状況、個別に進めていきたいと、このように考えております。","id":"exchange-035"},{"speaker":"山本副委員長","kind":"意見","question":"実際進めていくにはいろいろと詰めるべきところもあると思うのですけれども、先ほど言っていただいたようなケースワークの中でのお子さんに寄り添って、そのお子さんに合った対応をできるだけ進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-04","title":"の５のその他","agenda":"の５のその他","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"きちんとご主人に確認をして、その仕事が終わってから確認をして、多分子どもが行かれていたらちょっと悲しい思いをしたのではないかと思います。１点だけ、要望というか、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"多少行き渡っていないというところがあったのかなと思いますので、そちらについては今後も第２弾もありますので、しっかり周知して遺漏のないようにしていきたいと考えています。","id":"exchange-037"},{"speaker":"山本副委員長","kind":"意見","question":"私からも１点だけ。それが現状、児童センターに取りに来た子どもたちとのコミュニケーションなどが取れているのかどうかということをお聞かせほしいと求めました。","respondent":"藤村子ども育成課長","answer":"児童センターのほうにお子さんが取りに来た際には、毎日ご飯食べているかなど、そういった簡単な声かけをしております。そういった形で何かアウトリーチ支援というところでつながるようにやっているところです。","id":"exchange-038"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。続けてほしいと求めましたし、そういった場合にはつなげていただけるように進めてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"児童センターの職員のほうは日頃からそういったところを気配りしてやっておるところですので、さらに周知して、徹底するように伝えてまいりたいと思います。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/435368?Template=document&Id=6789#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":28911,"voices":119}},{"id":"r06-20240826-5","meetingId":"r06-cm08","date":"2024年8月26日","dateIso":"2024-08-26","committee":"総務委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"令和６年度都区財政調整交付金当初算定結果","agenda":"令和６年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"松本委員","kind":"質問","question":"この間やられていたということでいいのか、そうした調整の結果、どうなっているのかというところをお知らせほしいと求めました。お願いします。","respondent":"加島財政課長","answer":"２,５００万円を起債しますとなった場合なのですけれども、起債相当分につきましては、財政調整制度の特別交付金で現在申請を行っているところです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"それと、トイレトレーラーの話もありましたけれども、普通交付金になるのですか。その決め方というのが何かお分かりになったら説明を求めました。","respondent":"加島財政課長","answer":"一致していない部分につきましては、児童相談所の設置が都区の役割の大幅な変更に当たるかどうかというところです。今現在、別の場でそのような議論を進めることができないかというのを模索しているところ、調整を行っているところです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"これからの流れ、これからの進み具合などを少し教えてほしいと思います。ぜひしっかりしてほしいと求めましたが、そのお考えも、お願いします。","respondent":"加島財政課長","answer":"何か新しく取り組む動きなどがあったときには、今どのようなお考えかということもそれぞれ共有し合って、共有し合って取り組んでいるところです。必要があるといった場合には、財政調整算定の結果いかんにかかわらず、区として取り組んでいくこともあると考えております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"支援をするということも考えるべきではないのかと私は思うのですが、こうやって増えています、報告は受けました。自治体としたらいいことですけれども、これは議論するつもりはないのですが、その辺のご見解だけお聞かせくださいますかとの意見を述べました。","respondent":"加島財政課長","answer":"当初の算定式によって多少の凸凹はありますけれども、区として重要な資源、収入の一つとして思ったところです。令和６年度の歳入として様々、学用品の無償化や給食費の無償化などにも取り組んでいるところですので、企画課ともに考えていきたいと考えております。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり品川区としても、そういう層に目を向けて、もっと支援をするように何か対応していただきたいと私は思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"立会川児童遊園（その３）・旗の台北公園改修工事請負契約","agenda":"立会川児童遊園（その３）・旗の台北公園改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"それで、この改修工事というのは、もう定期的に、十何年したら一律に、仮にあまり傷んでいなくても改修するのだという方向性にあるのか。その辺について少し説明を求めました。","respondent":"佐藤経理課長","answer":"旗の台北公園も昭和６０年ということなので、開園から３５年以上経過しているという状況です。その辺については個別に必要性について再度、企画経営部で査定をしているという状況かと思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"ブロックをどんどん差し込んでいるだけですから、やはりインターロッキングブロック舗装というのをこれからどんどん採用していくのでしょうか。その辺について、値段のところもあるのですが、メンテナンスのことを含めてどうなのか、ご見解を説明するよう求めました。","respondent":"佐藤経理課長","answer":"後段のところですけれども、公園のしつらえのところかと思いますが、それは所管の公園課で考えるところかと考えます。利用者の方、周辺の方からご意見を聞きながら、工事の内容について決めていると所管から聞いております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"日頃、皆さんが生活道路としても使われているところなので、メンテナンスもあまり時間がかからないような舗装にしたほうがいいのではないかと思いますが、その辺、歩きにくいというような方向性に行かないようになることを望みますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"今回、立会川児童遊園と旗の台北公園というのが隣接しているから、この２か所の入札という形との理解でいいでしょうか。場所が似たようなところだから一緒に予算を立てたというか、今回、入札に至ったということでよろしいか尋ねました。","respondent":"佐藤経理課長","answer":"所管で予算要求して出しているところですけれども、おっしゃるとおり、こちらは立会川緑道の公園ということで連続して整備されているというところですので、一定の部分に沿って、年々工事していると把握しております。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"当然ながら、たくさんあれば、老朽化というのは当然あるわけで、そうすると、区内に３００か所近くあったのではないですか。その準備を進められているという認識でよろしいか尋ねました。","respondent":"佐藤経理課長","answer":"所管で進めるところかとは思いますけれども、公園がある中で、老朽度合いを比較してといいますか、並べて、必要性の高いところから順々に計画的に進めていると聞いております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"そこは長寿命化というのができているわけだから、当然ながら、それは所管と経理課で話し合いながら進められているという認識でよろしいでしょうか。それをお聞きしたのですけれども。","respondent":"佐藤経理課長","answer":"予算編成の中で、企画経営部で査定ということになりますので、全体を見ながらということで予算化されていると認識しております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"所管との関係というのは、結構いろいろなところで、所管の要望がどれだけ吸い上げられているのかというのを時々疑問に思うときがあるのです。要望もあれば、「計画の中では、それがきちんとされていますよね」という確認だけだったのですけれども。","respondent":"佐藤経理課長","answer":"その範囲ということになってしまいますけれども、予算編成の中では、そういった委員ご指摘のところも踏まえて予算化されていると考えております。その予算を踏まえて経理課に契約締結請求をして、適正な手続をもって今回、契約いたしましたということでご報告している案件です。","id":"exchange-012"}]},{"id":"topic-03","title":"契約事務の変更","agenda":"契約事務の変更","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"１の電子契約の導入のところで、これは数はどのくらいあるのですかというところと、ボリューム感かを教えてほしいと求めました。具体的なところを教えていただきたいのと、区の業務負担のところで、どういったところが軽減していくのかというところを説明するよう求めました。","respondent":"佐藤経理課長","answer":"続いて印紙税の負担が減るというところでご説明したところですけれども、あとは１億円だと３万円、１０億円だと１６万円という規定になっております。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"件数で言うと２２５件というところで、そうすると４,０００件ぐらいある中の１,０００万円以上を超えるのが５％ぐらい。１,０００万円未満の方たちにかかるというところでは、今後、今後の考え方がもしあれば教えてほしいと求めました。","respondent":"佐藤経理課長","answer":"令和６年度にも、品川区を含めて８区、予定があると聞いております。今後につきましては、電子契約の仕組みを始めまして、事業者からの意見も聞きながら順次拡大するということで予定しております。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"２番の公共工事の前払金の限度額拡大ですが、ないような企業と、品川区が契約しているのですかと思ってしまうのです。どうも公共工事というのは違うようなので不思議だと思うのですが、その辺について、どうなのか尋ねました。","respondent":"佐藤経理課長","answer":"前払金の制度自体は法律で規定されているところなので、全国的に、国も含めて、公共工事については制度設計されるというところです。一定程度の規模以上の会社、工事の内容に見合う会社ということで入札をかけておりますので、そういった点では問題ないかと考えております。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"収賄等の問題がありましたけれども、こういうことが品川区で起きないような外部調査機関や、品川区の庁舎の中で調査する部署というのはあるのですか。それともそういうものは、品川区においては何もないのか尋ねました。","respondent":"佐藤経理課長","answer":"千代田区の事例をお聞きになられましたので、いわゆる官製談合のことかと思います。例えば何かあれば総務課でコンプライアンス推進担当が設置されておりますが、そういった事例を引きながら対応していくことになろうかと思います。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり同じような２３区の自治体で官製談合があったということは、対話して結ぶものですから、どうしても間違う方向に進むこともあると思います。やはりそういうことがないように、しっかり何か取組なり、そのような仕組みをつくるなりしていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"ご説明ありがとうございました。私から電子契約の件をお伺いしたいのですけれども、費用面のところをお願いいたします。","respondent":"佐藤経理課長","answer":"ただ、このうち８０万円余は初期導入経費ということで、年々の経費でいきますと３０万円弱というような形になっております。紙の契約書を作らなくてよくなるというところもありますので、些少ですけれども、そういった経費については減るということになろうかと思います。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"それに加えて、１件当たり幾らみたいな感じで費用がかかってくるのか。その辺りはいかがか尋ねました。","respondent":"佐藤経理課長","answer":"初期予算８０万円余のところは、あるいは研修ですか、事務のほうでの研修の経費というところです。そのサービスの利用料というところで３０万円弱となっておりまして、１件幾らということにはなっておりませんので、そこについてはかからないです。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"１割ということで、５０億円の１割が５億円ということだと思うのですけれども、改めて理由を教えてほしいと求めました。どういうヒアリングをかけて、どういう話合いが向こうから出てきているなど、そういう状況を教えていただけるとありがたいです。","respondent":"佐藤経理課長","answer":"毎年１件、学校の改築に係る建設工事が５０億円を超えるというところで、令和３年度以降を見ますと毎年１件ずつというような状況です。","id":"exchange-020"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。工事の立ち上がりに、やはり結構な費用がかかるところの部分は、少し、区でもという、早めにというところでは理解しましたので、分かりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"私は、１割でなくても、もっとあってもいいのかと。もっとあってもいい現状ではなかろうかと思うのですが、今回、１割と決めた理由というのは何かありますか尋ねました。","respondent":"佐藤経理課長","answer":"１割というところは東京都を参考に設定したというところであります。１割というところは出しませんけれども、お話しする中では、これで一定程度のところは大丈夫かとは考えております。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"現場が、働いている方々も含めて、こうであったらという要望があると思うのです。工事事業者の方と話を進めて、変えられるところは変えてほしいと求めましたので、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"昨年は視察先で夕食はばらばらだったのですが、今回は、またばらばらか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"契約案件がどうなっているかだけ、さらっとでいいので教えてください。細かくなくていいです。","respondent":"勝亦総務課長","answer":"今、国際友好協会で貸主の方と協議を詰めている状況でございまして、今後、契約をするという、今、契約の協議をしているという状況です。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"今、契約をする段取りをつけている段階だということなのですが、その内容については、この委員会で報告していただくことは可能でしょうか。どういう方向でやっているのかということも、この委員会に報告していただきますようお願いさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837879?Template=document&Id=6797#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":19628,"voices":69}},{"id":"r06-20240827-14","meetingId":"r06-cm08","date":"2024年8月27日","dateIso":"2024-08-27","committee":"行財政改革特別委員会","time":"午前１１時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ確認します。いつぐらいの時期なのか、またこれは全て掲載をいただけるのかというところだけ確認をさせてほしいと求めました。","respondent":"小林新庁舎建設担当課長","answer":"質疑とその回答についてのホームページの掲載ですが、東京都と調整を図っているところですので、近々のうちに報告できるような形で掲載する予定です。","id":"exchange-001"},{"speaker":"新妻委員","kind":"質問","question":"主な質疑、この４点ということなのですが、ここに集約されているということでの４点なのでしょうか。もうちょっと質疑があったのであれば、そこも載せていただけるといいかなとは思うんですけれども、いかがか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"主な質疑というふうに書かせていただきましたのは、質問としての内容はしっかりとこの４つの中で集約されているですので、それを分かりやすく、見た方にも理解しやすいようにまとめさせていただいたところで、この４点ということで考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のホームページの公開の点は主な質疑ということでしたが、もしほかに質問があったのならば、それも全て載せるようにしてほしいと求めました。広報しながわ、この周辺の住民へのポスティングというのをぜひやっていただきたいんですが、予定しているのかどうかも含めて伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"区として行う周知ですので、また、これとは別に東京都も周知を行うと聞いているところです。建物から２ヘクタールの範囲でのポスティングについて、検討を進めていると聞いてありますので、引き続きそういった検討を進めていただいて。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"都で検討されているということですので、ぜひ、それを実施してほしいと求めましたし、区のほうからも求めてほしいと求めました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118715?Template=document&Id=6799#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":3449,"voices":23}},{"id":"r06-20240828-19","meetingId":"r06-cm08","date":"2024年8月28日","dateIso":"2024-08-28","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時３８分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"訓練の中身も含めてどういうふうに作られているのかなというところでは、何というのですか、言っていただきたいと思うのです。１つお願いします。","respondent":"伊藤災害対策担当課長","answer":"高齢化、今回５会場で多くの地域の方々が参加できるようなプログラムを考えまして、地域の方々と協力しながらやっていくことを考えてあります。訓練を実施し、地域との関係を深めつつ訓練を実施してまいりたいと考えています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"何というのですか、災害に対して十分な準備を講じることができることとなるよう、住民の防災に関する意識の高揚と知識の向上を図る機会とする。そうしたところをもうちょっと工夫することを、各地区に広めていく必要があるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"親子世代を中心とした親子防災訓練などもありますので、年齢層、またレベルに応じた訓練も実施できているのではないかと考えております。様々な場面を通じて地域の皆様、また訓練を通じて、認識をさせていただけるような機会を設けてまいりたいと考えています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３０代、４０代が６０％の声を寄せていただいたということで、人数の声が返ってきたのか伺いたい。この総合防災訓練大綱には書かれているのですけれども、そこら辺はどのように考えられているのか、検討されているのか伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"それと、防災フェアでのアンケートの人数ですが、３６５人の方からアンケートを受け付けてあります。いろいろな取組があろうかと思いますけれども、万全とは行かないまでも対応できるような態勢を取りまして、訓練に臨んでまいっている所存です。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"各団体からの要望等も聞いている中で、やっぱり防災の要望というのはすごく不安を抱えていらっしゃるので多いのですよね。ぜひ障害者を入れた形でやってもらいたいという要望も多数寄せられているので、どこが負うものになっているのか、ちょっとそこだけ最後に伺いたい。","respondent":"伊藤災害対策担当課長","answer":"私は訓練担当のほうから申し上げすることしかできないのですけれども、訓練に関しましては、当然防災課が責任を持って安全管理にしっかり配慮します。もちろん通常の訓練の安全管理を行いますけれども、要配慮者の方、事故のないように訓練を進めてまいりたいと考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"何というか、たらい回しにならないように、防災訓練や避難についてはここというふうに明確になるといいなという思いから質問させていただきました。本当に積み重ねる訓練というのは大事なものになりますので、その中身の充実というのは、引き続き一緒に考えていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"確認","question":"この地区はどうするのかなという確認が１点と、荏原第５、新しい訓練と書いてあります。新しいのはどこの地区で何をやるというのが決まっているのか、決まっていないのか、そこだけまず確認したいと求めました。","respondent":"伊藤災害対策担当課長","answer":"各町会長、何かもう少しやり方ができるのではないかと考えておりますので、訓練を実施していただけるように進めてまいりたいと考えています。こちらの新たな訓練の実施地区、防災関係のゲームが１つ、また災害食体験などということで記載しております。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"確認","question":"例えば品川区の行政の中でしっかりとある程度認識があって確認できるのであれば、ここにどう、何というのですか。例えば消防団の助けも１つの考えだと思いますので、区としてどう解決に結びつけていくのか、この方向性をちょっと説明するよう求めました。","respondent":"平原防災課長","answer":"新たに考えていかなければならないところについては、今後の共助の中核です防災区民組織をしっかりとご支援してまいりたいと思ってあります。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"どういう方がいらっしゃってという情報が全く皆無で、何と言えばいいのですか、本音なのですよね。だから、要配慮者支援を町会でうまく運営していくためには、どうしていくのが正しいことなのかというのをちょっと教えていただきたい。","respondent":"平原防災課長","answer":"地域の方々に要配慮者支援を考えていただくワークショップを実施しておりました。様々そういったところを今後もご支援させていただければと考えています。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今のまつざわ委員からの質問で、総合防災訓練のことで、またちょっとすみません、お尋ねをします。防災訓練については、この先、来年以降、第４地区に関しての総合訓練に関しては、どのように取り組んでいくのかを聞かせてほしいと求めました。","respondent":"伊藤災害対策担当課長","answer":"源氏前小学校で訓練がこれからできなくなってしまうというようなご質問でした。こちらのほうでも今の状況を把握しつつ、地区担当また町会の方々とご相談をさせていただきながら、今後の方針について決めていければと考えています。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、来年以降について、まだ地域の方と検討はされていないという考え方でいいのか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"申し訳ありません、今ちょっと私のほうで把握していなかったので、そこは確認させていただければと存じます。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"確認","question":"分かりました。どのぐらい人数がいるというのを、いらっしゃらなければいないでいいのですけれども、把握されているのかどうかを確認したいと思います。","respondent":"伊藤災害対策担当課長","answer":"その後、上級救命講習というものを受講しますので、一定の救命応急手当については能力がある職員だと認識しています。ただ一方で、日赤の資格を持っている職員というのは、私のほうでは現在認識をしてございません。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"災害時に一般の職員よりはもう少し災害に携わる重みというのですか、これからもしそういう職員の方がいらっしゃったら、あるということでよろしいか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"現時点ではそういった認識はございませんが、応急救護研修であるとか、一定の応急手当の資格を持っている人間が配属されてあります。彼らは避難所開設のために行ったりだとか、実際的な活動を行いますので、そういった形で能力は発揮できるのではないかと考えています。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"まず５地区、私も地元が荏原第１なので楽しみにしていたので、どういう経緯でこの５地区に決まったのか。ウェブページにそういった動画があって、みたいなことなのか、ちょっとその辺を詳しく教えてほしいと求めました。","respondent":"伊藤災害対策担当課長","answer":"全て１３地区で実施をする、やっていない３地区を含めましても、やっていきたいと考えています。こちらも今検討しているような状況です。","id":"exchange-013"},{"speaker":"えのした委員","kind":"質問","question":"新しいことですから、品川区のオリジナルで、他区にも誇れるような内容になることを期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今の質問に関連して確認をさせてほしいと求めました。５地区で新しい訓練をやってみるというところで、そこはどういうふうに評価をするのかなというところで、この２点を教えてほしいと求めました。","respondent":"伊藤災害対策担当課長","answer":"５地区でそれぞれ地域特性に合わせて行うのかどうかというご質問でありましたが、それぞれ同じものを５地区で行う予定です。アンケートをこの５地区については取る予定ですが、その他の地区についても同様にアンケートをやる方向で考えてあります。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"もう今年はいいかなと思っているのだとか、そういうお話を聞いていくと、新しい取組をされるということはいいことなのかなと思います。ご家族家庭、プラス障害の方に対するこういう新しいプログラムというところも研究していただきたいなと思いますが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"いわゆる子どもたちが楽しんで踊れるようなものと、例えば座ったままで上半身だけ動かせるものだとか、あまり激しいものではないと聞いてあります。","id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"私も新たな訓練というところで、ぜひ伺いたいと思います。図上訓練ですから、何かそういうご提案とか、面白がってくれるような訓練がありますというご案内があれば伺いたいと思いますとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"先ほども委員のほうにご回答した内容ですが、今回の訓練がよかったかどうかというのは、そこでも検証していきたいなと考えています。現行の訓練内容になっているのかなと考えていますので、またこちらから提案できるものがありましたら、薦めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"確認","question":"今のところ区の方向性としては、町会とかでこういうゲームをやりたいという企画があれば派遣してくださるという理解でよかったでしょうか。しながわ防災体験館のところで開かれる講座に参加してくださいというルールだと思ったのですけれども、それでいいか確認したいと求めました。","respondent":"伊藤災害対策担当課長","answer":"例えばしながわ防災体験館でもそういった講義をやっているときもありますし、また、ご要望に応じて町会等の訓練に出向することも可能だと思います。ただ一方で、事前のスケジュール調整等があると思いますので、ちょっとその辺は個別にご連絡をいただければと考えています。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"そのかまどベンチもやっぱり町会単位ではないと使えないのでしょうか。きちんと手続は必要だと思うのですけれども、だから品川区も頼んでみたらと言われたのですけれども、品川区の現状のルールを説明するよう求めました。","respondent":"溝口防災まちづくり部長","answer":"公園の利用ということなので、私のほうから。そこは防災課のほうとも連携しながら、ちょっと申し訳ないですけれども、その都度ご判断させていただければなと思っているところです。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"勝手に使うという意味ではなくて、ここでもこういうふうに話し合われているわけですから、それは参加しやすいように進めていただきたいなと思います。みんなすごく興味を持ってくれるのに、誰も知らなかったという現状がありますので、その辺についても説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"ただ一方で、全区民に配れるかどうかというのはまだ分かりませんが、皆さんの目に触れられるような形で準備できればと考えています。お待ちください。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"確認","question":"それからそのために地域をどう作っていくのか、そういうところにつなげていくというのが、その点を伺いたいと思います。それを訓練によってまた確認検証するとか、そういうところに、その点をまず伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"先ほども委員から説明がございました、例えばしながわ防災訓練ガイドだとか、もう少し地域住民寄りの形で書かせていただいた資料になってあります。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"提案","question":"では自助の意識の向上というのは何なのですかということを、ちょっと伺いたいなと思うのですけれども、守ることにはならないと思うのですよ。","respondent":"平原防災課長、伊藤災害対策担当課長","answer":"そういった位置づけの中で訓練を実施していますので、様々なものが出てまいりますので、そこで様々な訓練参加者からお声をいただいております。ちょっとその前段ところがうまく連接していないように見えてしまって申し訳ございませんが… コロナのときの振り返りのようなものですが、訓練を行った後にはまた会議を行っておりまして、その振り返りを行うようにしています。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、障害者の人が誰でも行ける福祉避難所という位置づけではなくなったのかなと思うのですけれども、ちょっとその点を改めて伺いたい。福祉避難所で実際にやっていただきたいという要望も受けているのですけれども、そこら辺のところの見通しというのはどうなのかも伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、実際に訓練をして、その訓練を通してさらに何が足りないのかを浮き彫りにしていきたいというご要望もいただいていますので。そういうものも含めて、区のほうで取り組んでいただけたらありがたいなと思うのですけれども、その点を伺いたいと思います。","respondent":"平原防災課長","answer":"例えば家具の転倒防止、感震ブレーカー、委員にぜひ今度見ていただければと思いますが、行っております。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"今回、令和６年度地区総合防災訓練の未実施地区がこうやって増えていたり、参加者が減っているということは本当に残念です。防災意識が高まっているのかなと思うのですが、その辺ちょっと区の見解を、どう思われるか説明を求めました。","respondent":"平原防災課長","answer":"特に今年に入りましてから１月１日の能登半島地震、今委員がご指摘されました８月の南海トラフの臨時情報です。ですので、今は関心が高まっていると考えられるのですけれども、しっかりとそこはつながるような行動に取り組んでまいりたいと考えています。","id":"exchange-025"},{"speaker":"須貝委員","kind":"意見","question":"経験するということは大事だと思うのですが、それがいいのかどうか、ちょっと見解だけお聞かせください。お願いいたしますとの意見を述べました。","respondent":"伊藤災害対策担当課長、平原防災課長","answer":"参加者の増加を見込んだポスティングというような内容のご質問でございました。幼稚園、保育園を通じて各児童に到達するような形で各地区、該当する地区の訓練のチラシをまかせていただく予定をしております。 昨年行いました私どもの地域防災計画の修正の中でも、芸術、そういったところでの防災に関する学習機会の提供を１つの柱にいたしております。今後も幅広くそういった機会に連携しながら進めてまいりたいと考えています。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"様々なことをこうやって施策として進めているのですから、ぜひ多くの方が来られるように、今後も努力してほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"防災区民組織のことで伺いたいのですけれども、区民組織の求めに応じてというか、一方でなかなか人が。やってもらいたいことというところでは、どういうことを１つの目標なり政策的な視点として持っているのかを最初に伺いたいと思います。","respondent":"平原防災課長","answer":"地域をよく知る２００の防災区民組織が我々と仲立して、そういったところにつないでいただく、そこの核になるものと考えています。１月１日の能登半島地震でも、そういったところの視点で活動が支援できるよう、我々もしっかりと取り組んでまいりたいと考えています。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここに火がついたら本当に広がってしまうよという危険度の高いところに対して消火活動をどうやってやるのかとかということを実施するということがよ…大事な視点かなと思うのですけれども、その点に関して支援ができるのであればしていただきたいと思うのですけれども、いかがでしょう。","respondent":"伊藤災害対策担当課長","answer":"おおむね１か月ぐらい前から消防署への届出だとか、道路を使うようであれば警察だとか、いろいろそういった手続が発生してしまいます。スタンドパイプを使った訓練も可能ですので、そういったところも活用していただきつつ、能力の向上を図っていただければと思います。","id":"exchange-029"},{"speaker":"塚本委員","kind":"意見","question":"なかなか一足飛びに、そういったハードルを取り払うということは難しいのでしょうけれども、そういった訓練、より具体的な初期消火訓練ということが地域で行えるように、ぜひ支援をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"私のほうからは、訓練の周知というところでお伺いしたいと思います。このウェブページ、もう少し具体的に、このウェブページを開設して周知を図るというのはどういうふうにするのか教えてほしいと求めました。","respondent":"伊藤災害対策担当課長","answer":"ホームページの中にも訓練のものを作るようにいたします。今年度実施する訓練の、どういった訓練をやるのかと、日程だとか場所だとかが分かるようになっているような内容です。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる専用のウェブページですから、これは今回新たな訓練を委託されている事業者などがこういうのを作るのですか。このウェブ周知、せっかくそういったところにお金をかけてやるのですから、その辺をもう少し教えていただけますか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"例えば動画とか、そういったものまでには至らないと思うのですが、もう少し具体的な訓練内容が分かるような内容にしていければと考えています。あまりご期待されているほどのレベルではないようなイメージは持っているのですが、近づけるように頑張ってまいります。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"ほとんどの会場は１０月、１１月にされるということですが、新しいもので訓練を行うという理解でよろしいのでしょうか。その辺を伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"その上で必要な更新を、足りないものがあるのかどうか、また検討するというような内容となっております。区内一斉防災訓練については、本年ですと１２月８日に行う予定をしていますので、そちらで検証を行う予定をしています。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"生活しているとどういうことが起きてくるのかが想像できるような何か動画なり、何でしょうね、最初は紙ベースなのでしょうかね。避難所訓練の意味というのがもっと具体化していかないといけないのかなと思うのですが、その辺はいかがお考えか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"で、とてもやはり地震があって不安に感じていたので、そういった方々もいらっしゃるというのは少しずつ増えているのかなと私も認識をしています。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問・要望","question":"３から４までとか、こうした訓練のバージョンアップは必要ではないですかというところを区がもっと意識を持って働きかけていかないと。いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"今委員のほうからご指摘いただいたフェーズごとの訓練を運営側のほうも体験する必要があるというのは、非常に納得いく内容です。やるほうの対応というのもちょっとありますので、改めて情報提供させていただいて、やり方については改めてまた検討させていただければと存じます。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"最後のページの物的被害のほうで、道路の冠水がありますけれども、深さは何cmぐらいになったのか教えてください。そして、東品川海上公園エレベーターの故障とありますが、これはどのような故障だったのか、それだけ、もし分かれば説明を求めました。","respondent":"平原防災課長","answer":"何cmということではございませんけれども、道路の交通規制を行う必要が生じたというものです。エレベーターの構造上、かごの部分が着水してしまいまして動かなくなったといったところで、そんなに時間はかからずに復旧できたというものです。","id":"exchange-036"},{"speaker":"まつざわ委員","kind":"意見","question":"何かそういうような、たしか渋谷区か新宿区で水がガーッとなったというのが、すみません。要はどうしても、やっぱり水があふれたときに、今のマンホールというのはどんな感じになっているのかだけ聞かせてくださいとの意見を述べました。","respondent":"溝口防災まちづくり部長","answer":"そういった管を使って、そもそもそういった空気が抜けるような設備を作ったりというのは、これまでも様々な対策をしてきているところです。","id":"exchange-037"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"最後の８月２１日の大雨についてなのですけれども、品川区全域で６０mm、品川地区とか大崎地区では９０mmを超える雨量があったと伺っています。相当な大雨で、その理由はなぜなのかということを分析しているのか、もし分かれば教えていただきたいというのが１点。","respondent":"平原防災課長","answer":"１つは東京湾の潮位がそんなに高い状態ではなかったということで、雨が港区から品川区、上流側からの流入もないことが１つの原因かなと。そこは考えるところでございまして、しっかりとした分析というのは今後また行っていくことが必要かなと思ってあります。","id":"exchange-038"},{"speaker":"ゆきた副委員長","kind":"質問","question":"都のことであったりとか、国のことであったとしても、情報共有をお願いできればと思います。この辺について、ぜひ何かあれば、お聞きできればと思います。","respondent":"平原防災課長","answer":"私どもは、そこは品川区の管理ではありませんと、そういうような対応は行いません。それを対応すべき道路管理者のところにご連絡させていただいて、しかるべき対応をするように連携して進めております。","id":"exchange-039"},{"speaker":"ゆきた副委員長","kind":"質問","question":"５０mmを超えると、下水道も５０mmを超えると、排水が追いつかず対応できないという状況になります。ここについての認識があれば、どういう認識を持っているか、お聞きできればと思います。","respondent":"平原防災課長","answer":"あるいは委員が先ほどご指摘の１９時０１分の洪水警報、このぐらいの雨が降るから、直ちに専門の職員が現地の巡回を開始させていただいたところです。","id":"exchange-040"},{"speaker":"ゆきた副委員長","kind":"意見","question":"区として区内６か所に定点観測地を設けて、この定点観測地、こういったところで前向きに進めてほしいと求めました。最後に何かあれば、との意見を述べました。","respondent":"平原防災課長","answer":"区の地理的な特性でありますとか、様々な状況に応じて対策を進めていると思いますが、品川区の場合３か所に降雨量を測るものを設置しています。","id":"exchange-041"},{"speaker":"こんの委員","kind":"質問","question":"参考までに伺いたいのですが、いわゆる１回やったら終わりなのか、その辺の巡回の様子を伺いたいと思います。","respondent":"溝口防災まちづくり部長","answer":"立会川という２つの河川を品川区は抱えておりますので、そこはしっかり見られるようということで２班体制で、車の台数でいくと２台で回る。風が強ければ街路樹が植わっているところ、そういったものを見るような形を取ってあります。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆる河川が一番気になるところですから見ていただくといったところで、あと、それは今大体網羅されているようなお答えをしていただきました。何かございましたら、お願いいたします。","respondent":"溝口防災まちづくり部長","answer":"委員ご指摘のように、職員をその場で待機させたという経験がありますので、やっぱり職員の安全というのはしっかり確保しながら巡回はさせていきたい。","id":"exchange-043"},{"speaker":"こんの委員","kind":"意見","question":"区民の方への周知というところも大事かもしれないですが、職員の方が見回るというか、巡回するときの資料にも多分なると思うのですよね。場合によってはそうしたものを効率的に把握していくためにはというのも１つ大事な視点かなと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問","question":"たまたま５０mm以上の雨が降ったときに、定点カメラも必要なのですけれども、当然目視もあるではないですか。事前に満潮で上げ潮がいっぱいだというのは、職員の方も分かるわけではないか尋ねました。","respondent":"溝口防災まちづくり部長","answer":"その後引いた後に、洗浄とか、そういったものは今までの経験を踏まえながら対応していくような形にはなってくると思います。そういったものに即対応できるような形での巡回というのが必要になってくると思いますので、そういった対応をしていきたいと考えているところです。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問","question":"８月１５日の台風７号の対応のところで、福祉避難所開設１か所、福祉避難所が開設されたことというのは今まであったのでしょうか。どういうときに福祉避難所が開設されるのか、開いた理由を伺いたいと思います。","respondent":"平原防災課長","answer":"それが１点でございまして、本来の福祉避難所と異なりまして、特別養護老人ホームの職員の方にご対応いただいたところです。１名の方が上大崎特別養護老人ホームということになりますので、２名がいわゆる通常の避難場所、１名が上大崎特別養護老人ホームという形になります。","id":"exchange-046"},{"speaker":"せお委員","kind":"質問・要望","question":"ちょっと報告なので聞いていいのかよく分からないのですけれども、明日以降来ると言われている台風１０号に向けては、大型と言われているので、何か８月２１日までの対応とは違ったところとかがあれば教えていただきたいと思っています。","respondent":"平原防災課長","answer":"さらに品川区のような２３区沿岸部というようなところで狭めていきまして、その影響度、職員の体制を決めていくというような形になってあります。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"風水害対応についてのＩの３番の(3)に「コールセンターによる区民等からの問合せ対応」とあります。あったとしたらどのような問合せで、どういう対応をされたのか伺いたいと思います。","respondent":"平原防災課長","answer":"今回件数、特にすみません、書いてございませんけれども、内容によっては、区民からの問合せが全くないというような対応もあります。そういったところにつないで、具体的な対応をしていただくという態勢を取っております。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"これが２２日でしょう、うちのほうに来たのですけれども、そういうような報告はほかからはなかったでしょうか。何とも言えないので、ちょっとそのお問合せを放置しているというか、あれなのですけれども、何かあったら説明を求めました。","respondent":"溝口防災まちづくり部長","answer":"今回２１日の大雨の際に、ちょっと場所は後で教えていただいて、その後どういう形なのかというのは確認させていただければと思います。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはいつもの私の質問になってしまって申し訳ないのですが、やっぱり合流改善というのも、今後も防災とともに努めてほしいと求めました。これは、要望でとどめております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/949666?Template=document&Id=6801#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":52105,"voices":119}},{"id":"r06-20240829-10","meetingId":"r06-cm08","date":"2024年8月29日","dateIso":"2024-08-29","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"令和７年度予算（議会費）","agenda":"令和７年度予算（議会費）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"お伺いしたいのは、ここについては改善の必要性を感じていないということなのでしょうか、お伺いしたいと思います。もし、しかるべき会議体で検討すべきことだというお考えなのであれば、どういった会議体でこれが検討されることになるのか、伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"予算の関係がありますので、今のところは現状で、早くお渡しできるように努力をしています。行政視察の報告書については、皆様の中でホームページにアップということに決まれば、それに沿って事務局では手配をするという立場です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"局長のお考えはよく分かったのですが、今ご発言の中にもありましたけれども、私たちは、お金をかけてでも必要な改善なのではないかというふうに提案しているのですけれども、取りまとめいただいた議長とか、あるいは委員長とかのお考えなども、もしあればお聞かせほしいと求めました。","respondent":"渡辺議長","answer":"ご指摘の共産党要望の１番、文字起こし、まず、基本的には局長の説明のとおりです。今回はそこではなく、先ほどもご説明のあった主に３点を、重要視したということになります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"言い続けたいと思います。必要な予算もつけていただいて、早期に改善していただくよう、議会全体の皆さんにも要望としてお伝えしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"令和６年第３回定例会","agenda":"令和６年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"７月９日の議運で２定の一般質問について伺ったときに、まず、質問辞退の理由というのを聴取していただければということを要望させていただきました。その後の経過について、もし何かあれば伺いたいと思います。","respondent":"渡辺議長","answer":"その中での対応としましたら、理由に対しての聴取ということは、この案件に対してはふさわしくないと考えています。総意であればまた対応するとは思いますが、私の考え方では、あえて聴取のような形は避けたいと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"議長のお考えは示されましたけれども、できればこの場で議論をしていただいた上で、私は聴取していただく。議運の場でも協議していただければと思うのですが、委員長、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"安藤委員からこういうご質問がありましたが、私は、議員としてやはりしっかり説明をするべきだと思います。済む話ではないかなと思いますので、何かいい方法があったら、私は議運の委員長にも少し検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-03","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"せお委員","kind":"意見","question":"こちらに関しては、第３回定例会からポスターを掲示していきます。ＰＤＦのデータも皆様にお送りすることができますので、それぞれ議員の皆様、ご周知をお願いしたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"せお委員","kind":"意見","question":"どうやってやったらいいのかというところがあると親切だよねというところだったり、そういったところを入れたり、こういった文言に決定しています。１回の定例会で１００枚ということで、次回からもその課題を解消すべく、議論していきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"安藤委員","kind":"意見","question":"大したことではないですが、チラシの中に小学生の感想が掲載されているというのはとてもいいと思ったので、すごい親しみが出るといいますか、なので、できれば、スペースの限りもあるでしょうが、今後も継続していただけるといいかなという感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"私から、議会の運営、在り方に関する意見があります。意見を述べさせていただきたいのですが、よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"こしば委員","kind":"質問・要望","question":"その上で、口頭ですとお伝えしづらいところもあると思いますので、メモベースの書面をお配りさせていただきたいと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"こしば委員","kind":"提案","question":"３つ目が、討論についての制約の提案をさせてほしいと求めました。ただし、肩書のみは表記を認める方向で扱っていただきたいということを、自民党・無所属の会派からは提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"提案","question":"この提案自体は、提案者の方から聞きたいのと、委員会の審査を踏まえて本会議で議決になるわけですから。何か、質問なのか主張なのか分からなくなってしまいますが、質問の部分でもし何かお答えできるところがあれば、伺えればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"こしば委員","kind":"提案","question":"逆に無駄を、そういった本来の討論の趣旨に即したことにつながると思いまして、このような時間制限というのを提案させていただきました。議員も含めて全ての安全を図る、守るという意味合いで、書かせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"提案","question":"こしば委員のご提案ですが、ほかの議員とか会派とか政党に対する批判というのは、あまり出なかったのではないかなと記憶しているのです。それぞれ職務に対して、皆さん発言しているわけですから、少し違うのかなと思いますとの意見を述べました。","respondent":"大澤区議会事務局長","answer":"今、須貝委員からご質問のあった討論の件ですけれども、今、事務局で状況を把握しておりますので、ご報告いたします。令和５年第２回定例会から令和６年第２回定例会までの討論ですけれども、５分未満が４件、５分から１０分が３０件、１０分以上が４件でございました。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"長く見ても５分から１０分の半分ということで、７分ぐらいが妥当なのかなというふうに、これはあくまで……。〔「平均値ではなくて、ゼロもあるのだから」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"ただ、先ほど申し上げましたが、やはり自己主張があるのに、再質問の時間だと少し短いのかなと思うので、やはりある程度自分の意見の主張はしたいと思うので、そこは品川区議会としても考えられたほうがいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"結局これは、私たちは内容としては、何ら承服できない提案ではありますが、どういう進め方で、これの扱いをどうするのか、それだけ聞かせていただきたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"私たちもすごくたくさん提案をしてきたにもかかわらず、これは要望ですけれども、ぜひそういった公平な取扱いを心がけていただきたいという意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6803#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":13655,"voices":62}},{"id":"r06-20240918-10","meetingId":"r06-cm09","date":"2024年9月18日","dateIso":"2024-09-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"いかがでしょうかということで、何人の方が傍聴をしに見えているかというのが分かれば、事務局からも教えていただきたいのですが。","respondent":"大澤区議会事務局長","answer":"すみません、今、確認できていないので、お待ちになっている方の人数は把握してございません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"会議室も移動してくださいということも要望しておりましたが、時間のロスといいましても、私は議員としてやるべきことなのではないかと思うのです。いかがか尋ねました。","respondent":"まつざわ委員長","answer":"委員会の傍聴規則でも、人数は１０名の制限というのがあります。例えばこれの人数の変更であったり、現在の委員会傍聴規則では人数は１０名とする、引き続き今回もその姿勢は崩さずにやっていきたいと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして、それは委員長独断の判断なのでしょうか。それらについてお願いしたいと思います。","respondent":"まつざわ委員長","answer":"私からお答えしますと、委員長の権限というよりも、規則であり、ルールで決まっていることでありますので、その規則、ルールにのっとってやっていくというのがお答えです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"それと、局長のほうは、これは重大な問題なので、先ほど４３人という声が飛びましたけれども、教えてもらえないでしょうか。待機しているのかというのは、少なくとも名簿上では分かるわけですから、聞いてくださいということでお願いしたいと思います。","respondent":"大澤区議会事務局長","answer":"午前１０時半の時点では、こちらにいる職員もみんな委員会室に上がってきていて、受付人数は分かりませんので、委員長から指示があれば、今、職員に聞きに行かせますけれども、特になければ、把握はできていないというのが現状です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、別に長くやるつもりはないのですけれども、今、委員長への投げかけもありましたので、ぜひ委員長から指示を出してほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"撮影についてはもちろん許可していただきたいし、前に来るとかというのは難しいですが、自席であればもちろんオーケーだと思います。いつでも撮影は許可して構わないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"令和６年第３回定例会","agenda":"令和６年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"陳情第４８号の付託先ですけれども、影響について調査を求めるものだと思うのですけれども、区民委員会に付託すべきだと思うのです。そういった提案をしたいのですけれども、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"どうしても審査をするときに、地域産業振興課、民生費〔同日後刻に「区民委員会」と発言訂正あり〕のほうで議論するべきではないかと思います。変えられるなら変えてほしいのですが、駄目ならば次回から、その辺は転換をしてほしいと求めました。","respondent":"大澤区議会事務局長","answer":"これまでの経緯から、インボイス制度は国の制度で、区に所管がないので、所管がない場合は総務委員会で引き取るというのがこれまでの例ですので、一応、参考までにご説明を申し上げました。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、皆さんいかがでしょうかというのと、どうお考えですか。特に総務委員長のこしば委員もいらっしゃいますので、ぜひその辺は考慮していただきたいと思っているのですけれども、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回はぜひ充実した議論ができるようにしていただきたいと、この場をお借りして、総務委員長であるこしば委員にもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"課題があるということは今までもご説明があったと思うのですが、ここは今回難しくても、ぜひ何とか改善していただきたい。意見にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-04","title":"決算特別委員会の運営","agenda":"決算特別委員会の運営","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"理事候補者会という中で、私は提案すること自体をやめてほしいと言ったのですが、今こうして議題になってしまっているということだと思います。全議員に諮る場というのは少なくともつくらないと、これは改定できないのではないですかと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"松永委員","kind":"提案","question":"（６）のところについてですが、質問のない委員からのみ関連質疑が行われるということが、現在の状況であると考えております。６番と１１番については、すみません、削除ではなく、全部提案に賛成ということで、以上になりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"再度お聞きして恐縮なのですが、特に大幅な変更とか、ここが変わってしまったということがあるのですか。従来どおりやってきたものを、より皆さんに分かりやすいように、また誤解のないように明文化したという解釈でよろしいのか尋ねました。","respondent":"大澤区議会事務局長","answer":"実態として、変更点はございません。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"須貝委員は質問しただけです。全議員に諮る場をつくるべきではないですかということに対しては、皆さんどう思っているのか、どう思っているのか聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"こしば委員","kind":"提案","question":"共産党から提案のあった全議員への説明の場をつくるべきではないかというのは、その趣旨に沿ったものであるべきと思いますので、反対いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"この改正内容でよろしいのではないかということで、賛成ということです。こういう実態に合わせて、これまでも議会運営委員会でやってきたところがあると思うので、議会運営委員会の決定でよろしいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"山本委員","kind":"意見","question":"理由や検討経緯は、先ほど松永委員が説明したとおりです。全議員で議論するかどうかについては、先ほどこしば委員、塚本委員から説明がありましたことと同じ考えですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"提案","question":"私も先ほど委員長にお聞きしましたが、今まで我々が長年やってきたことを踏襲して、文言整理という意味合いではないかと自分は捉えています。全議員への提案ということですが、より分かりやすい運営方法を提示しているわけですから、それに対して反対するものはありませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"議員で入っていくならば、議員は手当をもらわないという仕組みづくりも、私は大切なことではないかと思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"こしば委員","kind":"提案","question":"先般の８月２９日に私どもが提案をいたしました議会改革に関する提案の件で、私から提案の修正をさせてほしいと求めました。私どもが先般提案をしました時間の制限のところですが、それがあたかも提案そのものと誤解をされてしまい、独り歩きをしてしまっておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"前回も伺わせていただいたのですが、自民党が提案した、そちらも２点目としてお伺いしたいと思います。問題と感じているのか、具体的にもう少し問題意識を伺わせていただかないと、協議しようがないなというのがありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"こしば委員","kind":"提案","question":"前回２９日に提案をさせていただいた時間制限のところで、例えばのところに２分という表現も入っているかと思います。ご意見をこれから伺わなければならないのではないかという話も会派でもありましたので、ここでするのは難しいものですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"こしば委員","kind":"意見","question":"そこではこれらの意見も出てくると思います。そういった中での説明をしていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"その上で改めて提案していただくというのが、提案したのは自民党で、はっきり分からないのです。一旦取り下げていただくほうがよろしいのではないかと私は思いますが、どうか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"西村委員","kind":"質問・要望","question":"これからルールをどうしていくのかということを、次の議会運営委員会に向けて皆さんと会話をさせていただきたい、説明をさせていただきたいと申し上げております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"提案","question":"そうすると、今ここで提案の説明はできないということですか。なぜなのですかという説明をいただきたいと思っているのですけれども、今日、この場では説明できないということでいいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問・要望","question":"今おっしゃった誹謗中傷というところも、修正をさせていただいています。各個人、会派の方々にご説明に上がらせていただきたいと考えていますので、そのようにご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"提案","question":"前回、議会運営委員会でそういう話合いがあったので、我が品川改革連合でも、この提案に対して会派で話合いをさせていただきました。せっかくそういうご意見が出たのですから、慎重に皆さんの意見を聴いて進めるべきではないかというのが我々の会派の意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"西村委員","kind":"提案","question":"ですので、改めてそういった討論、再質問に関しても、皆さんと議論をさせていただける機会にできないのだろうかというご提案です。皆さんの意見をお伺いしたいですし、聞かないということも、皆さんに案の説明をする機会をつくらせていただきたいということを申し上げておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"山本委員","kind":"提案","question":"討論というものはどういうものかということについて、皆様ご存じであると思いますが、改めてこの場にて確認をしたいので、説明をします。自民党・無所属の会の皆様が当初ご提案されていた１と２の部分、今後、改めてそれに沿って協議をしてまいりたいと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"安藤委員","kind":"提案","question":"なので、進め方については、そういったことをしたらいかがでしょうかということを提案したいし、皆さんの意見はどうなのかと思います。もしよければ、公明党に、協議の状況など、もしあれば伺いたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"塚本委員","kind":"提案","question":"前回、自民党からのご提案もあって、会派での協議ということですけれども、今回、今の議会運営委員会の中で、改めて文言修正等があり、また、持ち帰って協議をしましょうという委員長のご発言もあったので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"安藤委員","kind":"提案","question":"進め方については、私も意見を言わせていただきました。文書を提案されましたけれども、その修正を提案する文書を改めてこちらに配付されるということで、そこを確認させてもらいたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"こしば委員","kind":"意見","question":"しっかり会派のほうでもさらに議論を深めていって、形にもして、今はまだ口頭ですので、形に起こして、お出しできればと思います。今の段階ではまだ、あくまでも口頭ベースでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"西村委員","kind":"質問","question":"持ち帰って協議をというお話がありました。質問に対してはお受けして、委員長がおっしゃったように協議は次回でということでいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"発言ということであるので、伺ってもいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"西村委員","kind":"質問・要望","question":"そういう意味で申し上げたのではないのですが、先ほどのどのような形でというのは、今、この場では申し上げられませんがとお伝えしたのですけれども、ここに参加ができない議員の方もいらっしゃるのは理解しておりますので、皆様にご説明をさせていただきたいとお伝えさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6813#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":23266,"voices":128}},{"id":"r06-20240920-4","meetingId":"r06-c-settlement","date":"2024年9月20日","dateIso":"2024-09-20","committee":"決算特別委員会","time":"午後 ２時５５分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松永副委員長","kind":"意見","question":"委員長を支え、今回２回目となるタイムキーパーですので、ミスのないよう、しっかりと頑張ってまいりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/285407?Template=document&Id=6847#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2161,"voices":17}},{"id":"r06-20240924-6","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"区民委員会","time":"午後 １時００分～午後 ０時３０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨年の同事業の実績について伺いたいのですが、昨年度に組んだ予算総額と、大体どのぐらい使われたのかお伺いしたいと思います。主にどのような設備に使われることが多かったのかなども、分かる範囲でお願いしたいと思います。","respondent":"小林地域産業振興課長","answer":"この後ご説明しますけれども、追加で１００件という形で予算を組みまして、こちらが約８,０００万円の追加ということでございました。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"大分使われたということですね。これに当たる設備というのは、何かほかに具体的な、こういうものがありますよというのがあれば教えてほしいと求めました。","respondent":"小林地域産業振興課長","answer":"新札対応券売機以外のところで業務改善に資するという部分で、１０年前と比べますと、そういうものも幅広く認めるような対象として考えているところです。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"昨年度は３４９件の申請があったということで、今年度、今回は１５０件ですので、またこの後、追加などの想定もされていらっしゃるのか。以上２点、お願いします。","respondent":"小林地域産業振興課長","answer":"ですので、今１５０件と予想はしているのですが、場合によっては１５０件を超えるような実績も出てくるのかなと考えています。２点目のご質問は、１５０件の今後の見込みとかということですか。 今後の補正予算の見込みにつきましては、昨年度の実績を見込んで、その分は対応できるかなと。その状況ですとか、物価、景気動向も踏まえて判断したいと考えております。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区民の方の要望などを見て、柔軟に対応していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"新札対応券売機については、現在、納品までに３か月ぐらいかかる場合もあると言われています。３月に入り込んでしまうと、改善策等についてはどう考えられているのか、お聞きできればと思います。","respondent":"小林地域産業振興課長","answer":"ご質問のとおり、今、新札対応の券売機については、やや納品が遅れているような状況があります。当然ながらスピードを持って対応したいと考えていますし、あと、こういうものをできるだけ幅広く拾っていきたいと考えております。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"事業を開始して速やかにということの答弁をいただきまして、確認させていただきました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"２点確認ですけれども、１点は、それは郵送でやるのですか。区は、区内中小企業という意味では把握しているかもしれないけれども、個人事業主まで全て把握しているのか尋ねました。","respondent":"小林地域産業振興課長","answer":"去年と違う申請であれば、これを認めるというか、申請を受け付けるような対応にしたいと考えています。我々として今回考えていますのは、この説明資料に書きましたとおり、周知をしていきたいと考えています。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"２点お伺いします。要は２か月の期間で１５０件の申請業務に対して７００万円というのが、例えばほかの事業とかと比べて妥当なのかどうか、その辺を説明するよう求めました。","respondent":"小林地域産業振興課長","answer":"それに対してちょうど５分の４で８０万円ということで、それは認められることになってあります。２月、３月の内容のチェックというのですか、業務の効率化という点で算出しているものです。","id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"事業に対する省エネとか業務の効率を上げるとかということなのでこの所管なのでしょうかというのを１個聞きたくて、例えば個人事業主というと。個人に対するところでいうと、この所管でなく別の建設委員会とか、そういうところになるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"ここの５つはあくまで主な対象経費の説明ということになりますが、個人用にでも使えるようなもの、そういうものは対象外にしております。あくまで申請が上がってくるときの説明としまして、さすがに相談があった時点で、前年度の実績なども踏まえてご説明したいと思います。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"確認","question":"個人に対するのはどうなのだろうねという議論になりまして、建設委員会の方になると思うのですが、そのことを確認させていただきました。この補正については大歓迎なのですが、少しその視点について議論になったので、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"先ほど答弁で他自治体の事業も参考にというご答弁があったので、参考までに、同様のこういった助成事業をやっている自治体というのは結構ほかにあるのか、そこだけお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"金額が大きい分、そういうチェック、手続の仕方も違うというのがあります。スピード感が大事だと考えていますので、そういうところで東京都とかと基礎自治体というところでは、きちんと違いをつけて対応しています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"例えば２３区とかで同様の事業をやっているところがあれば、最後に教えてください。何区ぐらいあるか、分かれば説明を求めました。","respondent":"小林地域産業振興課長","answer":"省エネのほうは、我々も、これは去年の例ということになりますので、恐らく３区ぐらいではないかなと思っているのと、あと、今回、自動券売機の対応ですけれども、こちらについては、墨田区と北区が直近で対応を進めていると我々は認識しています。","id":"exchange-012"},{"speaker":"せお委員","kind":"意見","question":"交付を決定する方たちとか、そういうスタッフというか職員の方は、どういった知識とか資格とかがあるとできるのかなと思って。東京都のように厳しくとはもちろん思わないのですが、スタッフというか職員が大変だなと思って、そこだけお聞かせいただけますかとの意見を述べました。","respondent":"小林地域産業振興課長","answer":"恐らく中小企業診断士とか、金額がきちんとそれに見合うものが入っているかどうかという確認も含めてですけれども、そういうもののチェックです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"提案","question":"共産党としても、昨年度末で切れるこの事業の継続をと質問していましたし、予算修正提案を行うことも求めてきました。賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-02","title":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"指定管理料の決定の仕方についてどうなっているのかということを伺いたいのが１点と、共同事業体ということなので、伺いたいと思います。２番目に「産業振興に係る事業の企画、品川区の担当課自体がどういった方向で事業を進めるか、伺いたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"利用者は原則無料ですので、こちらは収益というよりも、基本的には管理運営費のほうが多くなると認識しています。〔「区の方針をどうやって反映させるのかというのは」と呼ぶ者あり〕 指定管理者のプロポーザルを５年に１回やっておるのですけれども、そういうところで区の方針というのを要求仕様で提示したり、その段階で区の要望は年度協定書に落とし込んでいるところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"こちら、差引収支の金額の行方というのですか、どこに行くのでしょうかということを伺いたいと思います。コロナ以前から比べると回転率が１０％台ということで、何かもっと違う原因があるのではないかと思うのですが、それについてはいかがか尋ねました。","respondent":"大森文化観光戦略課長","answer":"こちらは、もともと４階にあるというところでの回転率の低さということでお話しいたしました。２０人程度の会議室というのが５個ほどあるのですけれども、そういうものがまず施設にあるというところからＰＲしていこうかなと考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"管理運営委託料の決め方についても、こちら２つの施設について、共通だと思うのですけれども、伺えればと思います。収支がゼロになるのはどういうふうに捉えたらいいのかというのは、基本的な話ばかりで申し訳ないですが、説明を求めました。","respondent":"大森文化観光戦略課長、三井スポーツ推進課長","answer":"２つの施設の委託料の決め方ですけれども、それで予算要求をいたしまして、そこから査定されていって予算が決まるという形になります。 基本的には事業費と維持管理費で支出の合計が決まりまして、そこから利用料金収入を引いた分が指定管理料となっております。利用料金によって指定管理料に増減があるというような形で、最後、決算でこちらはゼロ円となっております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"物価高騰ですとか、そういったところの影響もあろうかと思いますので、そこについては実態に応じて柔軟に対応していただければなと思います。意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"これはどういうふうに私は理解すればいいのでしょうか。確認です。","respondent":"栗原創業・スタートアップ支援担当課長、大森文化観光戦略課長、三井スポーツ推進課長","answer":"理事長選任の段階で理事長に当たられて、今、ビジネスクラブの理事長に就かれているところです。年に１回、そういった使途不明金などがないかということも… 使途不明金についてはないものと認識しております。そちらの認識ですけれども、それから、公益財団法人として職員を雇用しているものということで認識して… 品川区のＯＢについては、スポーツ協会が独自で採用の決定をしております。使途不明金については、特にこちらでは把握はしておりません。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この辺をどのように考えているのか教えていただきたいのが１点。この理由が何なのかというのを説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長、大森文化観光戦略課長、三井スポーツ推進課長","answer":"そういう１人で経営をしていくには不安な方のためにサービスが必要ということで各種支援をしていますので、区としては考えているところです。… 令和３年度が高い部分につきましてですけれども、こちらは、令和２年度がコロナの影響が一番大きかった年になります。令和３年度は金額が、令和４年… 利用人数は少なくても、実際に事業自体は実施するものになっておりましたので、そこまで大きな事業費の変化はなかったというようになります。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"提案","question":"今回ここに入ってきていなかったのであえて提案をしますが、要は１人で行く人もいれば、友達とかと一緒に行く可能性があるわけですね。改善できるところを改善していただきたいなと思うので、これは要望で終わりますが、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"労務に関する問題を見るという視点を入れていただきたいということを、私はずっと要望しておりまして、何かのタイミングではあるのですよね。そういう意味では、ぜひ労務に関するモニタリングという視点を入れるべきだと思うのですが、その点についてのご見解を伺いたいと思います。","respondent":"大森文化観光戦略課長","answer":"こちらに関しては民間のノウハウでの調査の実施ということになりますので、通常どおりの独自アンケート調査をやるということで予定しております。","id":"exchange-022"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これは当然だと思いながらあえての確認ですが、それを基に評価をしているという理解をしてよろしいですね。当然だと思うのですが、一応確認です。","respondent":"大森文化観光戦略課長","answer":"はい、こちらだけではなく資料がございまして、そういった形でご報告させていただいておるところです。","id":"exchange-023"},{"speaker":"吉田副委員長","kind":"確認","question":"ほかの施設についても同様と考えてよろしいですよね。すみません、一応確認です。","respondent":"三井スポーツ推進課長、栗原創業・スタートアップ支援担当課長","answer":"指定管理については、全部同様に区政運営会議にかけている状況になります。 前お二人の答弁にもあったように、こちらについても同様に、区政運営会議にかけているところです。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問","question":"３年目に外部のモニタリング調査を入れるというのは決まっているということで、私たちは見ることができるのでしょうか。どこかホームページなどに載っていたりするのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"公表されているかというところは、担当部署に確認して、後日ご報告でもよろしいでしょうか。","id":"exchange-025"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"少し説明にもあったかもしれないですが、区としてはどういった規模の事業者というのをメインの対象にしているのかというのを伺いたいと思います。生態系という話もありましたが、こういう考え方で事業をしているところというのはほかにも結構あるものなのか、伺いたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"地域課題、社会課題を解決するという起業家もありますので、そういう方々も併せて支援することを考えているところです。３点目の、品川区としても様々な皆様を支援していきますけれども、この３分野を選定させていただいたところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"どうもありがとうあります。軌道に乗るまで低廉に貸し出してもらえないかという要望を結構いただくのですが、どういうものがあるのか伺いたいのと、いかがか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区としましても、そういう講座に通っていただいた方に対しては融資の利率を３年間無償にするサービスというか、施策を実施しています。東京都中小企業振興公社が、いろいろな、区の施策だけではなく国ですとか都の各種支援策も一緒に併せて提供しています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し広く広報を強めていただきたいというのと、品川区としても実態に応じて、もう少し独自に支援策を強めていっていただきたいなと。結構周りの方でそういう方もいらっしゃいますので、それはお願いしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問","question":"一般的な品川区民の内外、両方に向けて、やはりそういう明確なアナウンスというのが必要なのではないのかなと考えています。通常業務でも、その辺をもう少しうまくアナウンスしていただけるといいなと思いますが、いかがか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今後進めていきたいと考えておりまして、いろいろな方を参加対象にして、みんなで相互のことを知ろうという催しを考えているところです。今後についても、民間のコワーキングスペースなどとも連携して、区民の方々に対しての周知はより一層実施してまいりたいと考えております。","id":"exchange-029"},{"speaker":"おぎの委員","kind":"質問・要望","question":"せっかくいいことをやっていても、知っていただかないともったいないなと思いますので、今、情報発信ツール、ＳＮＳとかユーチューブとか、そんなにお金がかからなくて発信できるものもいろいろありますので、ぜひ強気に発信を続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問","question":"１日１コースで、計５コースが行われると認識していますが、本当にすばらしい事業だと感じています。ぜひ今後の展開、何年までに、将来的にはこういう展望だとか、そういうものがもしあれば、お聞きできればと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今後、もう少し拡充などを図っていくことも視野に入れてやってまいりたいと考えておるところです。着実に受講生が増えていって、何かやってみようかなという、そういう風土をまずは区内から醸成していくことが大事かなとは考えているところです。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"意見","question":"応募総数が７０名以上ということもあるので、さらに需要を増やしていけるような取組を進めてほしいと求めました。その辺で何かあれば、もう少しお願いしますとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ここの中の創業支援施設のＳＨＩＰ、そういうところとの連携とかというのは、今後は発生してくるというふうには考えているところです。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１１月に五反田地域の大交流会と、その溝を埋めていっていただきたいなと思うのですが、その辺をどのように考えているかが１点。どうしても距離感を感じてしまっているので、そこはぜひやっていただきたいなと思うのですが、そういった面を含めて何かあれば説明を求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それ以外の支援ももちろん実施しているところではありますけれども、そして、引き続きやっていきたいとは考えているところです。今年度は構築ということをメインで実施しているところでありますけれども、今、展開していきたいとは考えているところです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"社会課題として、こういう分野にＩＴというのですか、そういう意味で介護に関してやっていっていただきたいという思いがすごく私はあったのです。でも、その夢とかアイデアを実現させてあげるというのがスタートアップだと思っているので、その辺についてはいかがか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"何かやはり特徴づけを行うということを考えて、テーマを設定させていただいたところです。先ほど項目３番のスタートアップ支援で五反田バレーアクセラレーションプログラムというのをやっているとご説明させていただきましたけれども、ただ。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"私もここに福祉が入っていてほしいなと思ったので、少し分かりやすくしてほしいなという部分が今までありまして、そこは本当に分かりやすくする。そういったところも何か分かりやすくしてほしいというところが１点と、私、どういう取組を考えているのかなというところを説明するよう求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"このソーシャルビジネスを支援していますよという周知が、もっと分かっていただけるような情報発信は、より強固にやってまいりたいと思います。","id":"exchange-035"},{"speaker":"吉田副委員長","kind":"質問","question":"そう理解していいですよねということが１点と、法人格をどうするかというのを皆さん、考えられるかなと思うのです。デメリットはこうです、そういうアドバスもしていただけると考えてよろしいでしょうか、その点について伺いたいです。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"大きい組織拡大を図るのかというのは別ですけれども、そういう共通項がある方については皆様、ご支援するところです。これにつきましては、各創業支援施設のインキュベーションマネジャーが適宜ご相談を承っておりますので、そういった支援を継続してやってまいります。","id":"exchange-036"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"個別に伺っているので、ぜひそういう法人格を取るときに、そういうところも視野に入れていただきたいなという要望です。要望ですが、もし何か少しでもコメントしていただけるようなことがあったら、伺いたいです。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区としては、皆様のご質問にもあった、ソーシャルビジネスに該当するところかなとは思いますので、そういった方々もご支援はしてまいりたいと思います。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=6821#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":45658,"voices":116}},{"id":"r06-20240924-7","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件整理しています。","topics":[{"id":"topic-01","title":"令和６年陳情第３９号、全庁的に区有地の活用を検討する、障害者施設整備計画を策定し、計画的に整備を進めるよう、区に求める陳情","agenda":"令和６年陳情第３９号、全庁的に区有地の活用を検討する、障害者施設整備計画を策定し、計画的に整備を進めるよう、区に求める陳情","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"ご説明ありがとうございました。具体的に何ページに書いてあるのか分かれば教えていただきたいと思うことが１点と、今事例で出ている大田区、世田谷区は。","respondent":"佐藤障害者施策推進課長","answer":"サービスの必要量や見込み量を算出しまして、補助制度や人材確保といったソフト面を含めた支援の進め方を示していたりするもので。施設整備の予定されるものにつきましては、それもまとめて施設整備計画ということで、個別に表しているものではないというような状況です。","id":"exchange-001"},{"speaker":"ひがし委員","kind":"確認","question":"大田区、世田谷区の情報が載っていたので確認をさせていただいたのですけれども、この施設整備計画なのかなと他区の情報から思いました。品川区のところの１０７ページを見てみると、その点、区としてはどのように認識されているのか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"個別の施設につきましての具体的な計画等は、個別に、こちらの計画ではなくお示ししているものがあります。それから住民説明会等も通じまして、こちらには載せてございませんが、施設の個別の計画としましては定めているというような状況です。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"ここに書いてあるものはあくまで概要で、それは一般的に公表されて、何か基本計画のような感じで出されているものなのでしょうか。もし分かれば、名称も教えていただければ後ほど見てみたいと思うのですが、教えていただけますと助かります。","respondent":"佐藤障害者施策推進課長","answer":"例えば大原児童発達支援センターにおきましては、そちらの整備の予定ということでお示ししていますので、そちらについてのまとめた。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問","question":"そこの前も踏まえて、いつどのぐらいの時期に工事をするから、多分おっしゃってくれているところとは少し違うのかなという印象を受けました。現状福祉部、少し人が足りないのではないかというようなことを一般質問等でも言われていましたが、もし分かれば教えてほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"現時点で整備予定が決まっているものを明らかにしておりますが、現時点のところでは、新規施設の整備をする予定についてはないです。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことなので、何というのですか、では品川区でその要望にどう応えていくのかという計画というものが出されていないということなのです。そして、それをどのような形でいつまでにつくっていくのかという計画をつくることが必要なのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"検討してまいるというようなところで申し上げました種別と、介護支援型や日中サービス支援型、現状を踏まえて進めているところです。それから、計画で令和３年度から令和８年度に向けて１００名の定員確保というようなところがありますので、現在取り組んでいるところです。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうでないと、やはり障害者の皆さんの要望に応えることができないと思うので、実現の方向を出してほしいと求めました。先ほどの１０７ページの、何というのですか、その点についてもお聞かせいただけたらと思います。","respondent":"佐藤障害者施策推進課長","answer":"品川区におきましては、心身障害者福祉会館については改築等を視野に検討を行いますということで、本年４月に出させていただいているところです。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前回も、令和６年度から令和８年度の３年間で検討を進めたいということだったのですが、ちょっとそこの点を確認させてほしいと求めました。品川区の公共施設総合計画でも２０２４年から２０３３年の建て替えということでなっているのですが、その点教えていただけたらと思います。","respondent":"佐藤障害者施策推進課長、吉岡政策推進担当課長","answer":"整備方針のところで、先ほどの繰り返しになりますが、障害福祉計画の中でも改築の検討を行いますというようなところです。この計画、３年の期間をもって計画として策定させていただいているものになりますので… こちらも公共施設等総合計画におきましては、次の２０２４年から２０３３年のところで改築というようなところで記載されているところです。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１０年近くかかるので、いつ頃までにその計画というものは示されるようになるものなのか、ちょっとそれは伺いたいと思います。ここでは障害者施設については検討の余地もなかったのでしょうかということで陳情の中に述べられているのですが、その点も伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"民有地の検討というところになりますけれども、庁内で連携をさせていただいて、活用の方法があれば使わせていただくというところになります。中長期的な財政バランス、こういったものを意識しながら、しっかりと庁内全体で検討しているというところが現状です。","id":"exchange-008"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だから、役所もやりたいと思ってもなかなかできないかもしれないけれども、それはでも相当考えていただきたいとは思いますが、現実できない。なかなかこのようなものをやっても、本当に架空的なものになってしまうので不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"何というのでしょうか、その計画や見せ方については、今の考え方を確認させていただきました。ということで、陳情の内容については不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問","question":"ただ、まとめられているものになっているので、それだけを見ると確かに足りないなと区民の方が感じるのはごもっともではないかなと思います。その点については、そのようなものをまとめたり等工夫をしながら、具体性のある計画というところも作成していってもいいのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"意見","question":"所要量、区としてどれだけ必要なのかということを明確に示して、それをどう実現させていくかという計画というものは本当に大事なことだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"計画については、区としても第７期障害者福祉計画で明示をしている。具体的な見せ方というか、そうした取組、説明をもっとしていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"最終的に石田秀男委員としては、やはり難しい中でもこれは私は前に進めていただきたいなというような願いがあります。この陳情を読んでいても、私としては前に進めていっていただきたいという意味で、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"第７７号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第７７号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"医療の現場ではすごい問題になっていますので、ちょっとその辺のところはここの中でも改めて確認しておくことが必要なのではないかなと思うのです。７ページのところを見ると、４月の段階で９.１０％ということなのですが、新たな数字があったら教えてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"マイナ保険証の利用率については、こちら７ページの資料が国民健康保険のほうでは最新のものとなっているところです。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"それから、マイナ保険証を持っていない人は、資格確認書が送られてくるので心配ないですということは周知されていないと思うのです。これは周知することが必要なのではないかなと思うのですけれども、その点についても伺います。","respondent":"池田国保医療年金課長","answer":"いろいろな通知ということで、広報等を１２月から、保険証が廃止になるということでのＰＲのほうはする予定になっております。ということで、保険証がなくなるということでのＰＲについては、１１月以降順次する予定になっているところです。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"確認","question":"国保であれば９月３０日まで使えます、それからその後も、資格確認書が自動で送られますという広報というものはされるのでしょうか。１０月から、その周知もどのように考えられているのか、その２点の周知について伺います。","respondent":"池田国保医療年金課長","answer":"医療機関にかかる、特例なものとして資格確認書が発行されるですので、特段資格確認書を発行しますというところはＰＲする予定はございません。マイナ保険証の使用率が１０％以下ですけれども、国のやることですので、その辺は国のやることで注目をしていきたいと考えています。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"９月３０日までは使えます、資格確認書は自動的に送られてきます、ぜひ区としても周知をしていただきたい。ちょっとそこのところは伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"国保としてどうなのかというところでは、前の保険証がまず１２月２日から発行ができないということでの周知をということにする予定になっております。片方だけでの受診はできませんということでご理解いただければと思います。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"すごいトラブルの事例、具体的なところで書かれているのですが、このようなものはご覧になられていますでしょうか。踏まえた上で、様々な対応というものが必要なのではないかと思うのですけれども、その点も伺えたらと思います。","respondent":"池田国保医療年金課長","answer":"よく読んではおりませんけれども、ただ、国からそういった事故のものが多少あるということは聞いているところです。こちらのほうは国のやっているところについて見守っていくというところ、注視するというところでいきたいと考えているところです。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"マイナ保険証というものは、これだけ皆さんから求められていないということなのです、結局。今でも資格確認書、保険証の代わりになるものが送らざるを得ないという状況になったわけですから、これは保険証と変わりないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"確認","question":"頂いた資料の３ページ、令和７年９月３０日に資格情報のお知らせ、または未保有者には資格確認書を交付というようになっていると思います。何か新しくまた配るということで費用等もかさんでしまうのではないかなと思っているので、１点確認したいと求めました。","respondent":"池田国保医療年金課長","answer":"こちらについても２年に一度、これまでの国保加入世帯のところで送るところですので、予算的にはそれほど変わらない。事務的には国保の事務ということで、これまでどおりの国から指定された料金ということになっているところです。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"意見","question":"具体的な数字は出てこなかったですけれども、基本的には２年に一度もともと配っているから、そこから業務としては変わっていないというところで把握をいたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"確認","question":"７割の医療機関でトラブルが起きているということで、当然今後利用率が上がれば、そこでマイナンバーカード自体は任意であると承知しております。今後資格確認書を使うということは例外、資格確認書が使えますと、もう一度その辺詳しくご答弁いただけないか尋ねました。","respondent":"池田国保医療年金課長","answer":"保険証というものが１２月２日から廃止ということになりましたので、資格確認書というものを送付するということが後ほど決まったわけです。それから資格確認書というものが同じような使い方を１２月以降するかとは思いますけれども、このような発言をさせていただきました。","id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"確認","question":"そうですね。１２月２日以降も保険証は使えるということや、資格確認書の情報というか、その点についてはいかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"私どもとしては、１２月２日以降保険証は廃止になったということで周知をさせていただきまして、廃止以降の部分についての異動等があった場合には、資格確認書、もしくは資格情報のお知らせを発行するというようなことでは周知という形になるかと思います。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"形式的なものではなくて、やはりしっかりと分かりやすく周知をしていただきたい。私が高齢者の方とお話ししていると、やはりもう１２月２日以降は保険証が使えなくなるのだ、その点は強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"意見","question":"マイナンバーカードと保険証をひもづけている国は、Ｇ７でもどこでもありません。よって、この条例改正にも反対と意見は表明したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"意見","question":"反対です。選べるという、国民が選べるという選択肢を設けるべきだと思いますので、反対しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"ひがし委員","kind":"質問","question":"引継ぎ等どのようにされるのかなというところが分かれば１点お尋ねしたいということと、今回新しくなったときにそのようなスタッフがいるのかというところ、この２点教えてほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"それから、今回指定管理者の候補者としております事業者の提案としてプラスされているものを実施するというような提案をいただいております。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは全て実績というのですか、児童館の運営というものは、まず全て実績があるという感じなのか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"児童発達支援事業所の実績を有する法人ということで、児童発達支援センターになってしまいますと、児童発達支援の運営について実績を有する法人ということでいただいているところです。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、医療的ケア児支援の実績というものはいかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"インクルーシブひろばベルの実施を継続のところで公募をしておりますので、先ほど申し上げた形で、医療的ケア児コーディネーターの配置について提案をいただいているところになります。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"医療的ケア児支援の実績はあるのかという質問でした。学研ココファン・ナーサリー。","respondent":"佐藤障害者施策推進課長","answer":"医療的ケア児の支援の実績に関しては、こちらのほうでは確認はしておりません。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問","question":"１事業者が欠格事由に該当、今回は５事業者の応募があるまで、何事業者にどのような形で働きかけたのかを伺います。それから、１事業者の辞退の理由も、どのような理由なのかも伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"今回の公募の周知ですが、約４５０の事業者にファクスで、公募を行う旨についてお知らせをしているところがございました。応募はしたけれども、区が実施する事業の内容について最終的に実施できる状況にないと、事業者のほうで判断されたというように伺っております。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"医療的ケア児支援の実績は確認できていないということなのですが、そのことも教えてほしいと求めました。その児童発達支援が３か所区内でやっているということは分かったのですが、それ以外の実績というものはあるのか、その点についても伺います。","respondent":"佐藤障害者施策推進課長","answer":"事業者の指定管理の状況ですが、指定管理でもって事業を運営されているというところは、こちらとしては伺っていない状況です。児童発達支援の部分につきましての運営実績というところで、児童発達支援の事業所の運営ということで、こちらのほうで確認しています。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"確認","question":"それからあと、インクルーシブの視点で医療的ケア児を受け入れているということは実績としてあるのか、そのところも伺いたいと思います。この指定管理の業務の１つとしてあると思うのですけれども、その辺のところも、どのような考え方なのかも伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"事業者と調整の上進めてまいりますので、現時点で職員がそのまま引き継がれるか等につきましては、確定しているものではございません。その辺りを含めて、繰り返しになりますが、今後事業者と調整していく状況です。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"提案","question":"この中で、両センターにおいて実施する事業の提案、これは実際どのような提案があったのかも伺いたいと思います。提案書類の中に書かれているのですけれども、また資格の方が、どれぐらいの配置ということになっていくのかも伺えたらと思いますとの意見を述べました。","respondent":"佐藤障害者施策推進課長","answer":"これにつきまして事業者側の説明としましては、それから、一過性のものであると考えているというような状況でございました。特別高い率というところではなく、一過性であるということも踏まえれば、特段の懸念はないという認識でございました。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、その辺のところの指定管理料の、その指定管理料というものはどれくらいになるのかということを伺いたいと思います。今回３事業者の応募があったということなのですけれども、非営利の事業者はなかったのか、そのことも説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"割合にしますと、他区の児童発達支援センター等で決算状況等が出ているものにつきまして、特段それについて懸念があるものではないと考えております。〔「社会福祉法人」と呼ぶ者あり〕 社会福祉法人につきましては、応募したほかの事業者につきましては、社会福祉法人はございました。です。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ちょっと確認させていただきたいことが、１８歳まではいつ相談に行ってもきちんと対応してくれるのかということは伺いたいと思います。児童学園と同程度の検査というものができることになっていくのか、そこのところはどのような状況になるのかを伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"保護者の対応ですけれども、それから通常対応が予定されている発達支援、保護者対応等を続けてしてまいりますので。検査の部分につきましては、これからの協議、打合せ等で対応してまいりたいと考えております。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"検査の点については、ぜひ児童学園と同程度の検査はできるようにしてほしいと求めました。取りあえず結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"若林委員","kind":"確認","question":"候補者選定委員会等２つの委員会が開かれて、区の審査の過程が、意見も出ていますので、その確認だけ。それからもう一つ、区との連携を重視している点があると見られるということですが、ここについてもご説明を伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"こちら区の児童発達支援センターということで、それぞれの障害への対応がきちんとバランスよく提示されているというような内容の意見のまとめです。〔「区との連携を重視している」と呼ぶ者あり〕 基本的に提案した内容で固めているということではなく、区の想定でもって柔軟に対応していくというところを今後の協議等で設定して進めていくというようなところで、区と連携を重視されているというように判断したところですです。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"例えばぐるっぽ、今回２つ目の、区の発達支援センターとしては２か所目になります。期待するところ、お願いしたいところがあれば、お聞きしておきたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"対応プログラム等を実施したりするようなところや、発達支援の中でも、そのお子さまの障害の状況に合った対応をしていくというようなところが。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問","question":"職員数、先ほど一部分で伺ったのですけれども、この施設全体で職員数が何人になるのか、ちょっと職種別に分かったら、それも教えていただけたらありがたいです。","respondent":"佐藤障害者施策推進課長","answer":"それから児童発達支援センターで、これ常勤換算で２７.９、全体としましては３５.６というようなところで提案をいただいているところになります。保育所等訪問支援につきまして、それから相談支援事業所におきまして、それから相談支援専門員が２名。","id":"exchange-041"}]},{"id":"topic-03","title":"令和６年請願第１２号、「長寿お祝い事業」の予算削減を前提とした見直し、及びその削減予算分の減税に関する請願","agenda":"令和６年請願第１２号、「長寿お祝い事業」の予算削減を前提とした見直し、及びその削減予算分の減税に関する請願","exchanges":[{"speaker":"筒井委員","kind":"質問・要望","question":"事務事業評価で、これＣ評価になっているのですけれども、それでも引き続き、この長寿お祝い事業をやる、その理由というものをもう一度教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"その事業の効果をもう少し見直した形で、区としての効果がどのような形であるべきかというところにつなげていく、そういったことも見直しの１つです。","id":"exchange-042"},{"speaker":"筒井委員","kind":"確認","question":"安否確認ということが主体に置かれているように思われておりまして、敬老の意を表したり、それは主の目的ではないような気がするのですけれども。商品券を渡しに行くことが、それほど見守りということになるのかなと思うのですけれども、その辺りいかがかお考えか尋ねました。","respondent":"東野福祉計画課長","answer":"民生委員がこの長寿の方に接する機会の１つとして行っていたという側面もありますので、見守り事業という中に位置づけてきたものです。近年、コロナなどの状況によりまして、郵送方式によることも行っておりますけれども、見守り自体は有効な、効果的な事業だと考えています。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"例えば８９歳の人はどうするのだとか、白寿と卒寿の間の９９歳から９０歳の間の人はどうするのですかとか、見守りという点ではどうなのか。その点お聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"こちらは、日本古来より節目節目というところの概念から出てきているものですから、それぞれに白寿や傘寿など、名前がついているものです。企業による見守りネットワーク、こういったものを活用しているものでございまして、何もしていないというわけではございません。","id":"exchange-044"},{"speaker":"筒井委員","kind":"質問","question":"９９歳から９０歳の間の人、８９歳の人はこの商品をもらえないということになってしまい、その辺りいかがお考えか尋ねました。","respondent":"東野福祉計画課長","answer":"お祝い品をもらえる、来年は私がもらえる年だねなどというようなことも、高齢者間の中でお話が出てくるということも聞いたことがあります。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、まず１つの例としても、しっかりと無駄なく税金を使っていくということで提出されたという考えだと考えています。では１００歳以上に限るなど、人生１００年時代と言われている状況ですから、その辺りいかがなのか尋ねました。","respondent":"東野福祉計画課長","answer":"他区の事情につきましては、他区のそれぞれの考え方があると思われます。見直しするべきところは見直すというところで、長寿命化のところの範囲を超えてくれば、それは見直しの対象と考えているところです。","id":"exchange-046"},{"speaker":"筒井委員","kind":"質問・要望","question":"８０歳廃止をしたということ、２０２５年問題などもありますし、縮小の方向へぜひ見直しを行っていっていただきたいと考えております。逆にこちらのほうにもう任せてしまうなど、そういった考えもあると思うのですが、その辺りいかがお考えか尋ねました。","respondent":"東野福祉計画課長","answer":"品川区の社会福祉協議会は品川区社会福祉協議会、区とは独立した団体というところで、高齢者に対するサービスというところで行っているものです。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"ひいてはそうしたことが少子化対策にもつながっていきますし、無駄な事業はどんどん減らしていって、効果的に税配分を行っていく。ぜひ品川区としては考えていっていただきたいのですけれども、その辺り、このような状況を見てどのようにお考えになるのか尋ねました。","respondent":"東野福祉計画課長","answer":"区民に対しての還元を行っていくというところから考えると、または少子化対策、そういったところは区としての命題だというように捉えております。私ども福祉部門といたしましては、高齢者の福祉につきまして、区民が望んでいるような福祉政策を最大限行っていく考えです。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、私は当然そのようなものというのは必要なのではないかなと思いますし、そのような温かい社会であってほしいなと思うのです。そうあっていただきたいし、続けていただきたいなと思うのですけれども、筒井委員はどう思われるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはそれほど莫大ですかという、何というのですか、お祝いしてもらったのだ」という温かい気持ちになるではないですか。本当にこれから介護も、しっかりと必要な介護を受けられるかと、そのような状況にあるではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問","question":"どうあるべきなのかという、そのようなことは。いいではないですか、このようなものは本当に必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"ですから、たまっていた不満が一気に、それによってより噴出してきたのかなとは考えております。ですから、分断を招かず、ある意味たたき台になったのかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"意見","question":"もう全体の高齢者の４人に１人は働いていますし、７０代以下の６９歳までの人だと、２人に１人は働いているのです。全員が全員高齢者を支えているという、そのようなところも、実際問題違うのではないかなというようなことはちょっと申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回、８０歳のお祝いがなくなってしまったことが、ちょっと切り捨てられたような感じがして寂しかったというようなお話もいただいています。お祝いをした方々のお声というものが、どのようなものがあるのかなということは改めて聞かせてほしいと求めました。","respondent":"東野福祉計画課長","answer":"私も、やはりそれを見たときに、ああ、この事業というものはすばらしい事業なのだなというように、改めて認識をしたところです。では見守り、近いから来ていただければと思いますということで、見守りにつながった事例もあります。","id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区の制度を使ってそういうのを導入をしたということで、すごいお礼を言っていましたということを連絡いただきました。この事業についても必要性というところをしっかりと区民の方々、若い世代にもお伝えできればいいかなと思いますので、こちらは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"筒井委員","kind":"確認","question":"で先ほどの高齢者の長寿を祝福して敬老の意を表するということも目的になっているということで、どちらが……。ちょっと高齢者安否確認ではないのではないかという疑問がこの請願者もあったのかなと思うので、はっきりさせたほうがいいのかなと思います。","respondent":"東野福祉計画課長","answer":"先ほど鈴木委員のほうからもご紹介があったように、要綱自体は、あくまでもお祝い事業としての位置づけとなっております。委員がおっしゃったようなところを踏まえて、実際の事業の体系的なところの見直しはしてもいいのかなと考えています。","id":"exchange-056"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"理由は、これまでの国を支えてくれてきた高齢者の方々に感謝の気持ちを表す御礼の意味もある事業であると思っているので、必要だと考えています。したがって、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"若林委員","kind":"意見","question":"減税のための何か１つの事業をこうやって、言葉が適切かどうか分かりませんけれども、委員会の中ではあまり適切ではないかなと。もう少しというか、広い視野で、様々また議論が必要なのかなとは思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"ひがし委員","kind":"確認","question":"請願者のおっしゃるとおり、限られた予算の中で無駄を省くということは必要であると考えます。ご答弁でも確認できたように、誰も取り残さない社会を実現するためにも必要な事業であると考えますので、今回の請願には沿いがたいと結論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に高齢者の長寿を祝い、敬老の意を表するということはすごく大事なことで、なくすということは絶対するべきではないと思います。そのようなやり方というものは違うと思いますし、もっと税の在り方など、大本のところにこそ目を向けていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"筒井委員","kind":"確認","question":"本日結論を出すで、採択でお願いします。今のこの現状の高齢者安否確認事業として長寿お祝い事業を入れていくということは、先ほど来述べましたとおり、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"高齢者の方にお話を伺ったところ、お礼をいただくということで、そういったことが職員にとっても非常にいいことだと考えています。やはり安否確認という名称の、安否確認とは少し違うのかなというところはあるので、ぜひそれは進めていっていただきたいとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-04","title":"第７５号議案、令和６年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","agenda":"第７５号議案、令和６年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"災害時の自動安否確認システムなのですけれども、ちょっとその辺想定されている人数があったら教えていただきたいということと、伺いたいと思います。時間もかかるし、すごく大変だというお話を伺っていましたので、ケアマネジャーは多分５年ごとに更新ということがあると思うのです。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"システムの開発ですが、こちらはＮＴＴがこのシステムを持っておりますので、ＮＴＴのほうと連携しながらやっていきたいと思っているところです。金額のほうはまだ出ておりません。通常５年ごとの更新なので更新研修と、あと主任ケアマネジャーを更新するときの５年ごとの研修のほか、そちらの中に一応見込んで含んでおります。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"確認","question":"結構効果が確認されて、何というのですか、ちょっとそこの見通しもお聞かせいただけたらと思います。それからあと、３５台でこの金額ということなのですけれども、１台当たりは幾らになるのかも教えていただけたらと思います。","respondent":"菅野高齢者福祉課長、樫村高齢者地域支援課長","answer":"主任ケアマネジャーの人数ということで、こちら今回の補正予算を立てるに際しての想定人数としましては、８５名程度ということで試算しています。この３５台、アンケートを利用していただいた方にも実施しながらやっていきまして、今後の展開というものを考えていきたいと思っているところです。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"意見","question":"本当に便利な、このようなものでコミュニケーションがスムーズに取れるということであれば、アンケートもしていただくということですので、今後拡大というようなところでしていっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"第２回定例会で会派から要望させていただいて、城南信用金庫に続いて区でも独自に購入されるということで、大変に評価をしております。もう１回確認をさせていただいて、そのような配置にしたのかの、そこだけ確認したいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"荏原第一、荏原第四、大井第一、大崎第一、品川第一、八潮地域センター内にあります支え愛・ほっとステーションの６か所を予定しています。この考え方ですが、まずは高齢者の方が多く訪れる支え愛・ほっとステーションということで、こちらの６か所に配備を予定しています。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"資格を持たれている方はどうなるかということをお聞きしたいということと、次は自動安否確認システムの件ですけれども、現状は。何ですか、ですから初めて使うというか、もし集約できていれば説明を求めました。","respondent":"菅野高齢者福祉課長、東野福祉計画課長、樫村高齢者地域支援課長","answer":"ケアマネジャーの法定研修の対象についてです。今回のこの事業の目的が、ケアマネジャーの人材確保、定着を促進することを目的としているため… 例えばレベル３の高齢者避難の情報が出た場合につきましては、ＬＩＮＥなどによって届けたり、防災ラジオに届けたりなどという運用をしております。… １の方が１名といったような内訳です。","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"イヤホンの件、そして安否確認の件は承知しました。ちょっと要望のような形になってしまいますが、定着を狙っているというところで、そのような方の掘り起こしというものも大事になってくると思います。","respondent":"菅野高齢者福祉課長","answer":"ケアプランつくる上では必要となる人材ですので、確保するためにということで、今回このような補正を組ませていただきました。今回は準拠をさせていただきまして、そこに４分の１を上乗せする形で補助を始めさせていただきましたが、事業の在り方は検証していきたいと思います。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"確認","question":"１点、加齢性難聴のサポート用イヤホンについて、ちょっと確認させてください。いろいろと機械が開発されている中で、今回この軟骨伝導タイプを使用するという結論に至った経緯というところを聞かせてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"この導入の経緯ですけれども、まずはやはり窓口のほうで、何かそういった改善につながるものがないかということで検討したところです。他区等で導入しているとか、城南信用金庫で導入しているという事例を聞きまして、検討を始めたといったところです。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問","question":"今の質問、もう１個別のパターンなのですけれども、骨伝導などほかのタイプを選ばなかった理由というところが聞けるといいなと思います。","respondent":"樫村高齢者地域支援課長","answer":"こちらの軟骨伝導を取り入れた理由ですけれども、軟骨伝導のほうが比較的小さいというところと、あと貼り付けるだけでいい。衛生的だというように、これ一般的に言われているところで、軟骨伝導のほうを選択したといった経緯です。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ検証していただいて、いろいろと開発されていく中でどのものがいいのか、費用対効果も考えながら進めていただければなと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ケアマネジャーが不足していたとしても、やることの内容によっては、非常にこれならいいよという人も復活してくれるかもしれないではないですか。認定をどうするかなど、ケアマネジャー全体をよくしていこうというような感じの部分で、ぜひ考えていただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814344?Template=document&Id=6819#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":58356,"voices":217}},{"id":"r06-20240924-8","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"建設委員会","time":"午前１０時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を93件整理しています。","topics":[{"id":"topic-01","title":"第７８号議案品川区空き家等の適正管理等に関する条例の一部を改正する条例","agenda":"第７８号議案品川区空き家等の適正管理等に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認をさせていただきたいと思うのですけれども、この準用というのはどういうことなのか、伺いたいと思います。その人の財産をある意味処分をするということにもなってきますので、明確な基準がなければいけないと思いますので、そのところを伺いたいと思います。","respondent":"川原住宅課長","answer":"３点ご質問をいただきましたので、順にご説明をいたします。その前に空き家等適正管理審議会というものを有識者の方などを招きした審議会があるのですけれども、その審議会でも１１月の中旬に諮る予定です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"これが、もし具体的な事例などありましたら伺いたいのと、最小限の措置というものがどの程度のことなのかというところで伺いたいと思います。そして、今回この人数を増やす理由を伺いたいと思います。","respondent":"川原住宅課長","answer":"現在委員を１２人以内ということで条例上規定をしていたところを、新たに１６人以内というふうに変更した事例です。やはり人も支援も大きく関わるところですので、区内のいろいろな様々な手続、確認を経て取るべきものというふうに考えてあります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"すみません、もう一度、もし分かりやすく説明できたら伺えたらと思います。取りあえず、その前のところを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"品川区内でどういう状況になっているのかというところをお聞きしたいのですけれども、これはまだ指定はないと思うので、今後の見込みですか。そこのところを伺いたいと思います。","respondent":"川原住宅課長","answer":"ごみ屋敷などの管理がよろしくない状態にある不適正管理状態にある非空き家に関しては、８月末現在で５９戸というふうに把握をしています。こちらの空き家条例に関しては、このご報告および調査をしているのは、戸建てのみに関してになります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"今の数字でいきますと、不適正に管理されている１３３戸が特定空家等ということでよろしいですか。そういったことは調査されていないといいますか、把握されてないということなのか、伺いたいと思います。","respondent":"川原住宅課長","answer":"のだて委員にご質問がありました管理不全空家等が１３３戸かというところではなく、区が認定をするという形で考えてあります。もともと計画自体は平成３１年という形で少し古いものとなっていますので、きちんと今、検討を図っているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、特定空家等の件数が答弁なかったので、もし後で答弁できたら、分かれば伺いたいと思います。ですけれども、そうした所有者への働きかけもしっかりやりながら、慎重に判断をしていっていただきたいというふうに要望しておきたいと思います。","respondent":"川原住宅課長","answer":"残りの３件については、２件は現在命令の実施中です。もう一つは、命令の前の特定空家等の状態で、今は改善に向けた措置をこちらの区の職員および関係者間でやり取りをしています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"改正後、いろいろ太文字で用語ありますけれども、住んでいる人と住んでない人と両方とそれぞれあるのですか。そこをもう一度整理してご説明いただけたらと思います。","respondent":"川原住宅課長","answer":"こちらも積極的に実施をしていきたいというふうに考えてあります。地域の事情、その方の所有者の事情、いろいろなケースがありますので、一つ一つ時間はかかりますが、区の職員が行って対応しています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"相続の問題でどうアプローチできるのかとおっしゃる方がいるかもしれませんけれども、福祉的なアプローチ、区の見解も伺いたいと思います。それだけに丁寧でかつ専門的なアプローチが必要だなというのが私の実感なのですけれども、品川区としては、いかがか尋ねました。","respondent":"川原住宅課長","answer":"人の支援というところが大きくございまして、あとは在宅介護支援センターの職員、支援も含めたアプローチというのを現在も行っているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"この空き家条例の中に、そういうその支援の仕組みというのが位置づいているのか、伺いたいと思うのです。いずれにしてもこの分野をしっかり強化していくことが必要だと思うのですが、最後にいかがか尋ねました。","respondent":"川原住宅課長","answer":"委員のご指摘のとおり、条例上にはそういった関係部署の支援というところまでは、細かく記載がないところではあります。１軒１軒、特に空き家ではない居住家屋についての支援というところでは、重層的支援会議等でも。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。私からは１点確認なのですけれども、第１２条の２のところなのですが、所有者以外にどういった方を想定されているのか説明を求めました。","respondent":"川原住宅課長","answer":"所有者においては、個人の所有者でなく、ケースは少ないのですけれども、法人の所有というところも考えられます。法人であったりとか、管理会社であったりとかというところも含めまして、条例に「等」というふうに記載をしています。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"だからこの辺りはどういうところで判断なのかなというのは、まさに同時につくっているところの部分なのでしょう。先ほどのフローとしては、どこでどう判断してというところもあるのですけれども、ここのところを説明するよう求めました。","respondent":"川原住宅課長","answer":"詳しいところはご説明があれなのですけれども、ここは民法の改定というところでは、隣家のほうもそこの枝に関しては関与することができる。もしくは電話、あと手紙等での所有者への関与というところでは、積極的に引き続き図っていきたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"その辺のどうしてもこういう相談が、今のまさにこの４月に変わってというものは、それというのは迷惑をかけている側に請求できるのか。所有者に区が求めるわけだから、この辺は何に基づいてやるのかというところが気になりましたので、その辺の整理を教えてほしいと求めました。","respondent":"川原住宅課長","answer":"他区の状況であるとか、都や国の判断基準に応じて、区のほうも検討していきたいというふうに考えてあります。そういった侵害を与えるというところでは、緊急的な要素が非常に大きいのかなというふうに捉えているところです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"その上で例えば空き家とかについての部分というのは専門性が非常に高く求められるのかなというのはあるのですが、今大きい課題としては、未来志向で。単純に若い世代だから、せっかく１６人以内ということで拡大をしたわけですから、そういった部分での検討もぜひお願いしたいなと思います。","respondent":"川原住宅課長","answer":"先ほど、のだて委員から質問をいただきまして、答弁ができなかった部分を改めてご説明をさせていただきたいと思います。空家法についても何も述べられていないため、ここは同じように条例でも、行政手続法の規定を適用しないというふうに条例上明記する必要があったです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"なかなか解決できないというお話をたまに伺いますので、そういうマンションとかアパートについては、区はどんなふうに現状考えていらっしゃるのか。そこだけ一言お伺いしたいです。","respondent":"川原住宅課長","answer":"そこの部分できちんと管理されているものではないものについては、住宅課でも分譲マンションに関しては把握ができるものというふうに考えてあります。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"未然に防ぐ対応を強化していくということで、賛成したいと思います。ただ、ぜひ条例上根拠を持ったほうが問題の解決がさらに進んでいくのではないかなと思いますので、そこは意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"第７５号議案令和６年度品川区一般会計補正予算（歳出等 建設委員会所管分）","agenda":"第７５号議案令和６年度品川区一般会計補正予算（歳出等 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"インフレスライドで今回６００万円増えるということで、どのくらい上がってきているのかというところを伺いたいのと、この変更が生じた理由。工事の変更なども先ほど少しご説明があったと思うのですが、変更する理由を伺いたいと思います。","respondent":"森道路課長、大友公園課長、北原河川下水道課長","answer":"来年度早々に行う予定ですので、旧水路からの浸水は、なくなるだろうと。南大井でもマンホール蓋の取替えされていますけれども… 水道管について水道管理者との施工協議を実施した結果なのですが、舗装復旧の範囲を変更したこと。建築課等との協議を踏まえた結果… 目黒川へ吐口を設置する工事について、管理者である東京都建設局と協議を行いまして、仮設が変更となりました。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際足りるのかどうかというところも分からないのですけれども、区のお考えを伺いたいと思います。このローリングストック、今回の備蓄でもできるのか分かりませんけれども、そこのお考えを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"恐らく１０年ほどで使えなくなることも考えられますので、５年ぐらいを一つのめどとして、今検討しています。必要な被災地の支援とか、そういった必要なときに、その有効活用分を支援に回せるような形で体制を取っていこうというふうに考えてあります。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の備蓄物資購入というところではこの避難所の環境改善につながるものだと思います。やはり女性の専用スペースですとか、間仕切りなどの配置ができるようにしてほしいと求めましたが、最後に伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そういった運用も含めて検討しています。そういったところを含めて、女性の方が安全に安心して避難生活が送れるような体制を整えていきたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中で、南大井旧水路安全対策と、今議論のあった防災対策について、少し伺いたいと思います。令和５年６月２日に浸水被害が発生したとご説明がありましたが、改めてどういう被害が発生したのか、概要を伺いたいと思います。","respondent":"森道路課長","answer":"ですので、令和８年度以降、順次水路内に発泡モルタルで充填を行って、そういった崩壊がないようにしていきたいと考えているところです。昨今増えておりますゲリラ豪雨にもどういうふうに対応していくかということも含めて、協議を進めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"改めて当時の浸水被害を伺いましたけれども、課長からも答弁あったとおり、浸水被害とかゲリラ豪雨対応、ますます強めていかなきゃいけないな。そうした基本的な対応をまずしっかりしていくことが必要かなと思うのですけれども、いかがか尋ねました。","respondent":"森道路課長","answer":"そういった部分を踏まえて、道路課といいますか、防災まちづくり部と下水道局のほうで情報を密にしながらやっていければなと考えているところです。これからも引き続き進めていきたいと思います。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのですけれども、そもそものあるものについても、自主避難施設も含めてしっかりとその施設に準備されているのか。どういう内容で現状あるのか、そこをご説明ほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"ですので、自主避難施設や避難場所開設と同時にすぐ間仕切りが設置できるような体制を取っているところです。各避難所の倉庫に一定数を備蓄しておいて、職員が対応する際にもすぐ用意できるような体制を取っていきたいと考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"コミュニケーションというのですか。などなど、今後のマニュアルの見直しについて、どういうスケジュール感や問題意識を持っているのかを改めて伺いたいと思います。","respondent":"平原防災課長","answer":"避難所運営マニュアルは、現在区における見直し作業を進めておりまして、一旦今月中に地域に提示させていただきたいと考えています。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそのスケジュールで進めていただいて、また上がってきた意見も反映してほしいと求めました。それが１つのお手本になるような形になると、住民の皆さんも非常に力になるかと思うのですけれども、最後に一言お願いしたいと思います。","respondent":"平原防災課長","answer":"皆様で共同しながら運営していただくということを考えてありますので、そういった中で地域の方々のご協力も得ながら避難所、避難施設の開設に進めさせていただければと考えています。","id":"exchange-023"},{"speaker":"横山委員","kind":"確認","question":"こちら先ほど女性用下着のお話ありましたが、こちらはどういった材質ですとか、検討されているのでしょうか。５年くらいがめどということでお話ありましたが、ローリングストックの考え方の中で、どのように行っていくのかというのを確認したいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"まだ購入する商品が確定している段階ではございませんが、見積り段階で検討しているものは、不織布のようなものになります。生理用品につきましても、つけて使えるようなもので検討はしております。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ女性職員の方々のご意見を引き続き聞きながら、具体的な部分も進めてほしいと求めましたので、要望します。手法に変えていくということになったという話なのですが、こちらの都の建設局との協議の時期について確認させてほしいと求めました。","respondent":"大友公園課長、北原河川下水道課長","answer":"インフラスライドにつきましては請求時点という形で、第１回の変更後に請求がありましたので、こちら４月の時点で判明したものです。階段部の手すりの延伸につきましては、こちらの時期は夏前ぐらいという形になっているところです。 そこに吐口を設置するという協議を行っておりまして、どうやって施工していくかという協議を順次進めてきているところでして、この３月という形になってあります。","id":"exchange-025"},{"speaker":"横山委員","kind":"確認","question":"確認なのですが、令和５年６月２日の時点では管理されていない旧水路があったということが、この後に調査の結果分かったということなのでしょうか。この潮通し管については、管理されている部分ということなのか尋ねました。","respondent":"森道路課長","answer":"昭和５０年代になりまして、潮通し管を区民公園の下に設置して、そのために運用していた。今回潮通し管が満水になっただろうというふうに考えられて、この旧水路の存在が今回分かったというところです。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"現在は安全が確認されていて、その辺り確認させていただきたいというところと、現状で分かる部分を確認させていただけたらと思います。現時点で安全性がどのぐらい確認できているのかというのを説明するよう求めました。","respondent":"森道路課長","answer":"ですので、国土交通省とも実際に話をしていく中でどういった対応をしていくかということをそれぞれ考えていきましょうということはしています。対応は順次していくというところはこちらとしても認識しているのですけれども、順次情報を共有しながら進めていければと思っています。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"現状のほう、説明をいただきまして、ありがとうございました。そして安心に、なるべく迅速に進めていただきたいというふうに思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"私からは、子どもや女性視点による避難所の生活環境改善について、少し質問させていただければと考えています。年齢なのですけれども、若い方の意見が今回は多いと思うのですが、どのような感じになっているのかなというのをまず教えていただけますか尋ねました。","respondent":"平原防災課長","answer":"防災課の女性職員のプロジェクトチームですが、こちら令和４年度からですけれども、係長１名の以外は全て係員ですので、比較的若い年齢層によって構成されております。","id":"exchange-029"},{"speaker":"澤田委員","kind":"質問","question":"例えば尿漏れパッドというのが結構中高年の女性で必要だというお話をよく伺っていて、その辺も検討してほしいと求めました。いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"ただいま委員からご提案いただきました尿漏れパッドなども含めて、様々な年代層の方のご意見を参考にしながら、引き続き備蓄物資の充実に努めてまいりたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"澤田委員","kind":"質問","question":"ぜひよろしくお願いいたします。不織布のようなものを、今のところはまだ決定ではないが検討しているということでお伺いしたと思うのですが、その辺の考え方はいかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"先ほど横山委員からもあったとおり、様々なサイズに対応できるようなものを検討しています。今後、そういったものは、順次情報をキャッチしながら対策を進めてまいりたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"澤田委員","kind":"質問・要望","question":"女性の防災リーダーみたいなものの育成にもぜひ力を入れていただきたいなと思うことと、あとは、そのようなことはお考えなのでしょうか。説明を求めました。","respondent":"平原防災課長","answer":"女性の防災リーダーにつきましては、例えば避難所運営で女性が中枢的な位置に入っていただくとかそういったところの手法を考えているところです。そういったところも活用しながら、より安心できる避難所生活を送ることができるような環境を整えてまいりたいと考えています。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"今回はそれぞれ大きくは５項目をまとめて契約していくという形だと思うのですが、今後はどういう形でやっていくのでしょうか。その辺り説明を求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"女性用の下着につきましては、１０年の有効期限ということですので、９年間をかけてローリングストックをしていくという形を考えております。防犯ブザーにつきましては、特に期限は設定がありませんので、必要な段階で入替えを図っていきたいというふうに考えてあります。","id":"exchange-033"},{"speaker":"つる委員","kind":"確認","question":"質問させていただいた趣旨と答弁が全然違ったので、後でまた個別に伺います。先ほど横山委員が質疑されて非常に大事かなと思ったのと、過去のいろいろな質疑を確認する中では、品川区として把握しているこの旧水路。","respondent":"森道路課長","answer":"下水道局のほうでいろいろ管を見て、その結果、対応が必要だというものについては対策を進めていくということになっています。これからも引き続き、空洞調査は順次行っていきながら、対策が必要なところはすぐに対策を打っていきたいと思っているところです。","id":"exchange-034"},{"speaker":"つる委員","kind":"確認","question":"今で言えば東京都の下水道局が本来は調査とか確認とかやっていくべきものなのかとか、区がやるのかとか、その責任の所在というものはどうなのかなと。","respondent":"森道路課長","answer":"戦災復興のときに水路が造られたというのではなくて、その前からあっただろうという認識です。しっかりと管理をしていければと思いますし、その戦災復興の中で造られたというよりも、その前からあったものについて今回発見できたです。","id":"exchange-035"},{"speaker":"つる委員","kind":"確認","question":"そういうものは造ったのがそもそも所在を確認していくという作業の立ち上がりも、そこのお金のかけ方とか、まず調査しようよ。お願いします。","respondent":"森道路課長、高梨都市計画課長","answer":"ただ、国ともいろいろ話をしていく中で、どういった管理形態がよいのかという話は、例えば水路１本として、区のほうで管理するのか。あるいはそれぞれ分断して、それぞれの管理者が管理していくのかという話は… 戦災復興の土地区画整理事業のお話がありましたので、正しい数字を答弁します。全４か所でございまして、それと大井地区、それと五反田駅の周辺の４か所で実施されていたというものです。","id":"exchange-036"}]},{"id":"topic-03","title":"令和６年陳情第３７号南品川５丁目のマンション建設に関する陳情","agenda":"令和６年陳情第３７号南品川５丁目のマンション建設に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"それと、今のご説明の中でも建築確認済証が既に８月２８日に出ているということで、これはどういった変更なのかというところを伺いたいと思います。確認申請とかがあると思うので、いつ作られたのかというのが分かれば、伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"戸数については、計画上、分譲予定のマンションで５４戸、共同住宅という形になっております。こちらに条例上届けがございました標識変更届によりますと、内容としましては、くいの位置の変更というふうに伺っているところです。 既存の擁壁がいつ頃造られたかというところです。かなり古い擁壁ですので、建築課には資料がない状態です。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"合計１５１名の方が署名をされているということで、１５１名というと、周辺の方の多くの方が署名をされているのかなというふうに思うのです。実際行ったかどうかということも含めて、その結果がどうだったのか、そこを伺いたいと思います。","respondent":"森建築課長","answer":"区で実施した調査についてですけれども、調査箇所数は約２,２００か所、区内全域の崖・擁壁を調査しております。危険性を３段階に分けて、平成２９年度に補助金等の助成が始まるのですけれども、その案内を含めてご案内したというところになってあります。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方もそうしたことを事業者のほうに求めているということですけれども、どういった対応をされてきたのか、伺いたいと思います。擁壁部分、約１１ｍ撤去するということで、なぜ撤去しなければならないのかという理由を伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"令和６年２月に、説明会開催などの要望を受け、それらの要望は全て区より建築主等に伝えてあります。８月に２回、その都度ご説明をさせていただきながら、陳情者の皆様からの声というのは速やかに建築主等に伝えているという状況です。詳しい資料がないので分からないのですけれども、確認済証が交付されますと、建築計画概要書というものがこちらに送られてきます。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"すべきではないというふうに思うのですけれども、区としてはどのように考えているのか伺いたいと思います。実際そこのところは、区としてはどのように認識されているのか伺いたいと思います。","respondent":"森建築課長","answer":"避難等の緊急事態については話が別になってまいりまして、避難で使えないということはないだろうというふうには考えてあります。資料が詳しくないので分からないのですけれども、計画上ですと、そういうものもなくなってくるような状況になろうかと存じます。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"それはどういうことなのか、区としては使えないこともあるというふうに考えている部分もあるのか、伺いたいと思います。実際擁壁を壊していくとなると、私道を使わずに工事をするということが可能なのかどうかも伺いたいと思います。","respondent":"森建築課長","answer":"日常的に使えるかどうかは、私道をお持ちの方々の皆様の同意等によるだろうというところで、このような答弁をしています。どうやら予定では敷地の内側、いろいろ金額をはじき出したり、上からできるというようなことを業者が言っているというふうには聞いてあります。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"こうした良好な関係をつくっていくということをこの業者が怠っているというふうにも考えられるわけですけれども、区の認識を伺いたいと思います。区としてはどういった指導、助言などをしてきて、認識を持っているのかというところを伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"区民の説明、私どもに設計者のほうから報告をいただいている説明会の報告書というところで、令和６年３月２４日の第３回の説明におきまして。… 計画上１,５００m2を切っておりますので、駐車場附置義務の平米数に達していないというところで、附置義務まで発生していないところです。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"区でもそうした対応を、しっかりと指導、助言などしていただきたいというふうに思います。区としても支援をしてほしいと求めましたし、助言していっていただきたいというふうに思いますけれども、いかがか尋ねました。","respondent":"川原住宅課長","answer":"今回の陳情の内容につきましては、近隣の皆様が安心をするような説明を再度行っていただくように、区からは話をしています。次回６回目以降の説明会があるかどうかというところでは、区民の皆様に説明できる資料ができた折には、きちんと説明をするようにというところは。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"大丈夫だというのであれば、その根拠はどう述べているのか、区はどう把握されているのか伺いたいと思います。３点目、良好な近隣関係をつくることに努めなさいと建築主に求めているこの条例の趣旨には反する状態が生まれている、区の認識を伺います。","respondent":"森建築課長、川原住宅課長","answer":"私から最初の２点についてお答えいたします。資料がないので、詳しくは分かりかねますが、審査は行われたということになってあります。陳情者の皆様への説明というところでは、先ほど区条例第５条の説明にもありましたように、あと当事者の責務として第２項のところでは。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"民間の確認審査機関は審査の上、さっき伺ったのは、何を根拠に確認審査では安全だと主張しているのか。先ほど伺ったのは、少なくとも現状はこの趣旨に反しているのではないかと私は思いますけれども、改めて区の認識を伺いたいと思います。","respondent":"森建築課長、川原住宅課長","answer":"擁壁の安全性の根拠等について、区で把握しているかですけれども、確認済証が民間検査機関から交付されたときに、区の建築課に送られてくるのが概要書というものですので、詳しい内容までは把握していない状況です。 建築の紛争予防条例に基づいて区ができる対応というところでは、あと調停の手続というものも踏まえる必要もあるのかもしれないというところは、区としても認識をしています。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"６回やったというけれども、論理的な説明を住民が求めていて、その点を伺いたいと思います。その根拠、データを住民の皆さんにしっかり示しなさいと品川区が業者に働きかけていただきたいと思うのですが、いかがか尋ねました。","respondent":"川原住宅課長","answer":"区民の皆様の声を形として、安全性の部分であるとか不安をしっかり払拭するような回答をするようにしっかりとした説明をというところでは。","id":"exchange-046"},{"speaker":"中塚委員","kind":"確認","question":"品川区も、業者から建築確認審査が取れましたと連絡が来ているから、業者の皆さんが安全だという根拠を区も知らないわけですよね。改めて伺いますが、具体的には科学的、論理的な根拠を住民に示して説明すべきだとなぜ業者に迫ることができないのか伺います。","respondent":"川原住宅課長","answer":"第４回の説明会の際にも、建物の耐火、荷重についてのご質問があったというふうに伺ってあります。そういったことも、区民の皆様に分かりやすい説明というところは引き続き対応するようにしっかりと申し上げていきたいと思います。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"正副委員長にお願いしたいのは、あしたにでも現地を確認して、その上で結論を出すなどの手続に進んでいったらいかがかなと。我々も委員会として現地を確認すべきではないかと思うのですけれども、委員長、いかがなものか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"確認","question":"いろいろ細かいところはほかの委員の質疑で確認させていただきました。陳情のことに限らず、現状でそれはできるのでしょうか、できないか尋ねました。","respondent":"川原住宅課長","answer":"こちらの陳情の項目に記載しています指導と援助です。引き続き区民の皆様、陳情者の皆様の声を適切に届けて、その対応をしっかりとしていただくというところのお願いにとどまるところです。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"どの辺のことまでが、言われた側、指導された側というのはどういう対応が必要になってくるのか。これは一般論ですけれども、業者だったりというのはあったりすると思うのですが、その上で指導と伝えるという意味の違いというのを説明するよう求めました。","respondent":"川原住宅課長","answer":"伝えた結果、その後どのような行動を示しているかというところまで、区は引き続きしっかり関与していきたいというふうに考えてあります。説明に関しても、個別での説明が必要なものは個別の協議をする場合も中にはあるそうなのですけれども、全体での説明を希望している際には。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"品川区内も調査すべきだということでやったことだと思うのですが、今回みたいな場合は、民・民のところですよね。責任的なことというのは何か発生するのかあるのか、対応が必要なのかどうか、これを説明するよう求めました。","respondent":"森建築課長","answer":"２項道路、そちらは区の助成等、アドバイザー派遣であったりすることが可能です。民・民のところについては、万が一崩壊した場合はどうなるかというところですけれども、所有者の方が責任を取るような形になっています。","id":"exchange-051"},{"speaker":"澤田委員","kind":"意見","question":"説明会は５回ほど行われており、その中でも区条例に従い、区としても様々働きかけていることなどです。ご心配をお持ちでいらっしゃいますので、併せて安心、安全のための対策をしっかり行っていただけるよう働きかけてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"それから、先ほど質問させていただいた中で、当該物件が適法であるという前提の中での品川区としての対応というところではあると思います。先ほど５回の説明の中の３回目にされたということがあるわけですけれども、それはなかなか分からないということがあるわけですから、ここについては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。区としても業者に対して助言、指導すべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"確認","question":"先ほども建設委員会として現地を確認すべきだ、視察をすべきだという意見を述べさせていただきました。区はぜひ自らの条例にのっとって、根拠を示して説明するよう、業者に働きかけるべきだと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"私は安全に工事を進めていただくことが大事だというふうに思っています。建築主への対応を求めるお声が届いている旨を迅速に建築主などに情報提供を行うなど、区として現状の把握をしながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"住民が知らないうちに進められているということで、突然説明会などあって、自分の生活が壊されるということを知ることになるという状況があります。住民が知らないうちに、地権者も知らないうちに再開発が進められていくということについて、区はどのように考えているのか伺います。","respondent":"中道都市開発課長","answer":"区としましては、地区内で考えている区域内の権利者の方々には周知するよう、勉強会や準備組合の方々には伝えているところです。都市計画の段階等に入る前には、合意状況等についても、区としては確認をしています。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そうした状況があるからこそ、再開発をやめてほしいという陳情が品川区にも区議会にも数々挙がってくるということだというふうに思います。そこを改善していくということが１つ必要だと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"そういった中で区がしっかりつかんでいくということが必要なのではないかと思います。９割が賛同だという中で、そこは区としてもしっかりつかんでいくことが必要ではないかと思うのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"まちづくりを検討する段階においても、またお時間の調整ができれば、戸別訪問という形で取り組んでいるです。その段階でしっかりと区民の方の意思表示というものは把握しています。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"準備組合の情報で、区が進めていくということになると、誤った判断にもなりかねないというふうに思うのですけれども、いかがでしょうか。それがやはり区民の生活を壊さない、あるいは守っていくということになると思いますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"そこにつきましては、準備組合等からの報告を基に、区としてはしっかり確認していくです。実際に都市計画の事業を進めるかどうかという判断につきましては、事業認可を取得するときに、法的な根拠を基に把握をしていくです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"確認","question":"事業を進めていくかどうかというところでは、法的な確認をしていると言いますが、その確認というのは準備組合設立の事業認可ということだと思います。区としても反省すべき部分があるのではないかなというふうに思うのですけれども、行政の責任としてはどのように考えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"繰り返しになりますが、都市計画のときには、区としては、住民の同意というところもしっかり把握しております。権利者の方々の同意が非常に重要になってくるところですので、そこにつきましても、また法の下にしっかりと対応しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"都市計画決定時にも住民の同意を把握しているということですが、区独自で把握されていることがあるのか、準備組合の情報に基づいて把握していると言っているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"権利者の方々が事業者となりますので、まずは事業者の方々からの報告ということで都市計画決定のときの同意というのは確認をしております。準備組合の設立のときには、同意書などの資料を基に行政として把握しています。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としてもそうしたところをしっかりつかんでいかなければ、区民の生活は守れないというふうに思いますので、これは強く要望しておきたいと思います。そうした中で再開発に巻き込まれていくという状況ですので、こうした再開発はやめていくべきだというふうに思いますけれども、伺います。","respondent":"中道都市開発課長","answer":"拠点の駅前を中心としまして、こういった市街地再開発事業といったところ、マスタープランにはまちづくり方針といった形で記載をしております。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に確認させていただきたいと思うのですけれども、過度に把握をするのは慎重に行うべきだということが、そうしたことによって区としても把握をある程度しかしないというところがあるのかどうか伺います。","respondent":"中道都市開発課長","answer":"地域の方々で進めていくまちづくりというところでは、都市計画決定においても、現在のまちの状況といったものは把握していきたいと考えております。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"共通するところもあるので一緒に伺いますけれども、確かに周辺地域の再開発の機運が高まっているという発言を品川区はよくいたします。私はいつもそんな機運は一体どこにあるのかというふうに謎に思うわけですけれども、機運の高まりと思う根拠は何かということを伺いたいと思います。","respondent":"中道都市開発課長","answer":"地域の方々が勉強会等を設立した際には、区のほうに、この地域でまちづくりを研究していきたい、また検討していきたいという声をいただきます。そうしたところに対して区としては、機運が高まっているというような表現を使っております。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"肩書というのか、どういう立場の方なのか伺いたいと思います。高まりとは何かをもうちょっと、あと先ほどの地域代表者というのはどういう方なのか、ご説明ほしいと求めました。","respondent":"中道都市開発課長","answer":"高まりですけれどもちろんそこで１人、２人の方が独自に来たときには、機運が高まっているということではございません。一定程度の人数と、地域自らまちづくりといったものを考えていただいているというところを、機運が高まっているというような形でお伝えしています。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"協議会を開きたいと相談に来たら、どうぞ、どうぞと言うのか伺いたい。そこも伺いたいと思います。","respondent":"高梨都市計画課長","answer":"今ご質問にありました区民の自主的なまちづくりに関する補助金を所管しています都市計画課から答弁をします。そのまちをどうしていこうかというような話合いに関する経費につきましては、区の要綱に基づいて補助金をお出ししたいというふうに思ってあります。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"賛成とか反対とかではなくて、自主的なまちづくりについての支援という位置づけですから、今の説明になるのかなと思います。質問ですけれども、何分の１以上の地権者の合意があれば、本組合に帰属することができるのか伺います。","respondent":"中道都市開発課長","answer":"都市再開発法の第１４条の中に同意について記載があります。土地所有者または借地権者の３分の２以上、宅地の面積または借地の面積の３分の以上の同意があれば、組合が設立できるです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ訂正してほしいと求めましたが、いかがでしょうか。これは法律の事実ですから、そういう表現に変えるべきではないか尋ねました。","respondent":"中道都市開発課長","answer":"都市再開発法の第２０条に組合員といった記載があります。所有権または借地権を有する者は、全てその組合の組合員とするというような法の決まりがありますので、それに倣って記載したです。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"だから再開発はやめてほしいという方々は、奪われた、立ち退きさせられたというふうにおっしゃるのです。最後に伺います。","respondent":"中道都市開発課長","answer":"今、第１４条の中の同意書で、再開発に同意しない方につきましても、第２０条の中で組合が設立できれば組合員になります。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"第２０条で全地権者を組合員とするという規定で、３分の２以上の同意で組合が設立すれば、全地権者が組合員となってしまうのです。こんな再開発はこれ以上進めるべきではないと、陳情者さんがおっしゃるのはそのとおりだと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"これまで再開発について様々な質疑がありましたけれども、法令に基づいて粛々と対応していただきたい。こうした様々なお声については、引き続きしっかりと寄り添いながらの対応を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"のだて委員","kind":"意見","question":"再開発準備組合から情報が出されずに、デベロッパーが事務局として主導権を握ってきました。こうした再開発はやめるべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"では誰が求めているのだというところですけれども、デベロッパーや大手ゼネコンが求めているのです。いずれにしても再開発に道理はないと思いますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。区としてそういったことがないように調査し、改善すべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]},{"id":"topic-04","title":"令和６年陳情第４３号、品川区東大井５丁目Ｃ地区再開発に反対する陳情","agenda":"令和６年陳情第４３号、品川区東大井５丁目Ｃ地区再開発に反対する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この陳情にあるとおり、陳情者の方は９０年以上住んでいらっしゃる。こうした方の気持ちを区はどのように受け止めているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"この地域の中では、様々な形で意見交換が行われているというところは聞いておりますが、現在そういった動きがないです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"現在動きがないということで、そうすると今は再開発はなくなっているということでよいのか、伺います。","respondent":"中道都市開発課長","answer":"そういった勉強会等は近年開かれていないです。今後のまちづくりを考えていきたいと、より多くの方が食べに、飲食に楽しみに来てほしいといったことを聞いているです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"勉強会が開催されていないということですから、機運が高まっていない、下がっているということでよいのでしょうか。これはどういうことなのか伺いたいのと、先ほど９０年以上住んできた方の気持ちをどう受け止めているのかということも伺ったので。","respondent":"中道都市開発課長","answer":"地域としましては、いろいろな方が楽しめるような雰囲気づくりというのを目指していきたいというところで、そういったことの記載です。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方、再開発によって住民に恐怖を与えてきたということは自覚していただきたいと思うのですけれども、いかがでしょうか。本来は住み続けたいという方が追い出されてしまう恐ろしい事業だということだと思うのですけれども、区の認識を伺います。","respondent":"中道都市開発課長","answer":"東小路を含むＣ地区ですけれども、様々な声があるということは認識しています。一方で、駅前で、多くの方が来られるというところで、防災上の不安という声も多く挙がっているということも、区は認識しております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方で考えていただきたいということなのですが、こうしたＣ地区での再開発はやめるべきだというふうに、これは強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"そこでまず品川区に伺いますが、大企業がもうける再開発事業を、何でみんなの税金を使って進めるのか。大企業がもうかる再開発を何で税金を使って補助して、応援するのかが疑問なのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"市街地再開発事業は、市街地の土地を合理的に活用するとともに、都市の機能更新を図るというところでの事業となっています。具体的に申しますと、老朽化した建物、またはインフラ整備、都市の魅力の向上を図るといった形で、区としては補助金という形で支援をしています。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が聞いたのは、大企業がもうける再開発になぜ補助金を使うのか、税を使うかということを伺いました。そのことにご答弁ほしいと求めました。","respondent":"中道都市開発課長","answer":"は建物を建てるときに補償に使う歳出というのは同額というところで、組合に対してお金がもうかっているというのは、区は把握していないです。民間の会社の運営の中の取組になりますので、区としては、その詳細につきまして把握していないです。","id":"exchange-082"},{"speaker":"中塚委員","kind":"質問","question":"もうけることを知っていながら、何でそんな再開発に補助金を税金として投入するのか、この点で伺いたいと思います。同時に伺いますけれども、木密地域で行われているこれらの事業は、なぜ売ることが前提だと補助金がないのか、伺いたいと思います。","respondent":"小川木密整備推進課長、中道都市開発課長","answer":"こちらは今委員がおっしゃられるとおり、民間企業の営利目的のために行われるような除却であったり、建て替えというものには援助の対象外とする。これはあくまでも営利を目的としたものは援助しないという形でやっているものです。市街地再開発事業ですけれども、行政が主体でやるというところではなくて、民間の企業活力を活かした事業というところで進めていくものになります。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問","question":"皆さんご存じのＣ地区の東小路ですけれども、東小路のよさを残したまま防災性を高めていく。こうした地区計画やまちづくり、自主的なまちづくりへの支援、何かそういうノウハウというものは持っていないのか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"東小路のまち並みというものは、区の資源の一つであるというふうに考えているとともに、非常に不安を抱えている地域だというふうに認識している。いろいろと検討するために専門家の知恵を借りたい、ご相談を承って、相談に乗りたいというふうに考えているところです。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひやめてほしいと求めましたが、いかがでしょうかということです。いかがか尋ねました。","respondent":"高梨都市計画課長","answer":"都市開発課長からの説明でもありましたとおり、地域でいろいろと検討されてきた経緯があるということで、様々色づけをしておきたい。","id":"exchange-085"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京２３区でも横丁を活かした長屋か、長屋を活かしたまちづくりというのも実践されているのです。ぜひＣ地区の再開発はやめていただきたいと重ねて主張して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"澤田委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。安心・安全なよりよいまちづくりを進めていくために、区は引き続き話し合いなどのサポートをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"つる委員","kind":"意見","question":"資料もいただきました。そうした様々な意見を、まさに地域の地権者の方々を中心にしっかりと話し合っていただいて、合意形成していくことが重要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。住民を追い出し、生活を壊す東大井５丁目Ｃ地区再開発はやめるべきと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"中塚委員","kind":"意見","question":"住民主体のまちづくりと言いますけれども、実態は異なる点も先ほど指摘させていただきました。いずれもＣ地区の再開発は進めるべきではない、やめるべきだと思いますので、採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"横山委員","kind":"意見","question":"現在まちづくりのことについて、地域の方々で話し合っていく段階であるというご説明がありました。先ほどの議論を踏まえまして、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"}]},{"id":"topic-05","title":"専決処分の報告、(1)専決処分の報告","agenda":"専決処分の報告、(1)専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"清掃事務所職員による今回の事故ということで、今回は清掃車ではないのですかね。そこを伺います。","respondent":"篠田品川区清掃事務所長","answer":"清掃車ではなくて、一般の乗用車です。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"今回は乗用車ということですけれども、この間、清掃事務所の方の事故が続いているような気がします。業務が多いのであれば、人員配置していくということも含めてやっていくということが必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"私どもも注意を徹底して、そういった事故が起きないように、さらに注意喚起してまいりたいと考えているところです。人員数等の問題というのは特段、そういったことが原因で起きているという認識はございません。","id":"exchange-093"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/463917?Template=document&Id=6817#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":74541,"voices":247}},{"id":"r06-20240924-9","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"文教委員会","time":"午前１０時００分～午後 １時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"すみません、録画もですか。録画も審議に入る前にということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"前例どおり、審議に入る前でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"せらく委員","kind":"質問・要望","question":"これまで前例どおりとしていたのですけれども、自席からであれば、いつでも構いませんということにさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"第７９号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第７９号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"令和５年２月に、令和５年のときの改正は、区の非常勤の方ではなく常勤の教員の方とか職員の方が対象だったという理解でいいのでしょうか。令和５年２月に補償内容が改定されておりますが、今回は同水準の改定につながったのかということの確認をさせてほしいと求めました。","respondent":"柏木学務課長","answer":"令和６年、今年の２月にも条例改正をしていますが、２月に区のほうの条例を一部改正として出させていただいているものです。内容といたしましては、教職員ではなくて、あくまでも学校医という形になってあります。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"私も確認不足だったのですが、学校医の方々だけではなく、教職員の方々も同様の公務災害の水準になっているという理解でいいのでしょうか。今回、手厚く学校医の方々の補償を国や都の条例によって変えたということなのか、教職員の方々も今回の改正と同じぐらいの程度のものなのか。","respondent":"柏木学務課長","answer":"当然、教職員の給与等も改正されてありますので、教職員の公務災害に関わる条例のも、東京都で改正しているものと思います。金額的には引上げされているものと考えています。","id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"現状の確認をしたいのですが、現在、介護補償を受けていらっしゃる学校医の方々というのはどれぐらいいらっしゃるのかということと、今回の改正に伴って、どれぐらい支給が増えていくのかということについて確認をしたいのですが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"事務が変更されたのは平成１４年度ですけれども、それ以降、本区において、こちらの補償の適用となる方は発生してございません。詳細な金額までは承知してございません。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"それも事前に確認しましたけれども、今、対象となっている方はいらっしゃらないと。学校医、学校歯科医、学校薬剤師という非常に大切な皆様の身分、待遇を守るという意味で、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"第８３号議案、指定管理者の指定","agenda":"第８３号議案、指定管理者の指定","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"１つ目に伺いたいのは、何階部分が児童センターになるのか、そのほかの部分が児童発達支援センターになるのかというところをご説明いただきたい。そこからまず伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"こちらの建物は３階建てで、３階が児童センターで、１・２階が児童発達支援センターとなっております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"今回、詳細な選定結果の報告書を頂いているので、その中で幾つか伺います。そのうち１事業者は欠格事由に該当し失格、３事業者になったということになっているのですけれども、どういう経緯だったのかを説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"こちらは５事業者から応募があったのですが、１事業者の欠格事由に該当したというところは、欠格事由に該当したというものです。もう１者の応募を辞退したというところは、社内調整等の結果、細かい部分というのはお伺いしていません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"４ページのところで、学研ココファン・ナーサリーの提案では、なぜほかが統括責任者の配置というのを提案されていないのかというところについて。なぜ対応しないのに、提案理由に書いてきたのかということが不可解なのですけれども、その辺りのご説明をお願いしますとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"学研ココファン・ナーサリーの上から３つ目のところ、ここで柔軟に対応していただくところで、クリアできているのかなです。直接的に利用者に対応しないという点について、そういったイメージがあったため、こういった表現になっているかと思います。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"そもそも一体的な施設の運営を求めている、相乗効果を求めているという話の中で、ほかのところは提案しなかったというのが謎です。分かりやすい資料とご説明をいただいてありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"田中委員","kind":"提案","question":"今回選ばれたココファン・ナーサリーに関するの意見の中に、１法人でセンターを運営するとの提案は効率的な運営が期待できるとありました。効率的な運営となっていますが、それはどういうところから、なぜ効率性を求めたのかというところをお聞かせほしいと求めました。","respondent":"藤村子ども育成課長","answer":"あくまで今回は指定管理者の指定ですので、もちろん、施設の設置目的に沿った事業を運営していただくというのが大事になってくるので。こども意見箱の設置ですとか、こども基本法ですとか、そういったものを踏まえた上での効率的なものと捉えていただければと思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"確認ですけれども、書きぶりとして、統括責任者を置く際の比重のつけ方というのでしょうか、そこで、どちらかを優先することは絶対あってはいけない。差について、求めていくお立場としての判断、評価をお聞かせいただけますか。","respondent":"藤村子ども育成課長","answer":"例えば今、共同で開催するとか、障害の有無によらず交流ができるプログラムというのを進めることもできるのではないかと考えています。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"矛盾するような質問になってしまうかもしれないのですけれども、逆のメリットも活かしていっていただけるところがあれば、ぜひ活かしていただきたい。区内でいうと２例目の児童発達支援センターだと思いますが、ぜひお願いしたいと思いますが、その辺はいかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"児童センターの運営の観点では、発達に特性のあるお子さんが来館してくるというケースもあるのですが、それほど多くないと。児童発達支援センターと同じ建物になりますので、交流というか、新しいものが進んでいくような形になればいいかなと思っています。","id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"選定理由に、子どもに関連する施設の運営実績が豊富とあります。評判でしたり、何か魅力があれば、改めてお聞かせほしいと求めました。","respondent":"藤村子ども育成課長","answer":"すまいるスクールでは、一貫校を２校担当している形になっております。いずれにおきましても、しっかりご対応いただいているということで、学校側からも、担当指導員からもお話を伺っているところです。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問","question":"大変様々なアクティビティーをしてくださるということで、私も評判を伺っております。まさに１法人でセンターを運営していただくことで、ぜひ両輪での取組をお願いしたいと思いますが、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"建物の動線も含めてですけれども、２階と３階になります。児童発達支援センターのほうの場所をお借りして、そういった形で、場所で区切らずに交流できるようにはしていきたいと考えています。","id":"exchange-016"},{"speaker":"山本副委員長","kind":"質問","question":"２ページの選定理由のところで、コストや効果などについて定量的に示されているようなものがあったのでしょうかというところ。例えば具体的に追加負担するとか、何か具体的なやり方についてのご提示があったのでしょうか、説明するよう求めました。","respondent":"藤村子ども育成課長","answer":"１施設分になるということで、ここで具体的な金額をお示しはできないのですけれども、コストというのは抑えられるようにしていきたいと思っています。必要な人の配置ですとか、そういったところをこれから詰めていって、少しずつ縮減できたらとは考えているところです。","id":"exchange-017"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それから、要望となりますけれども、一体運営ということで、事業者が替わるということになります。事業者の方々によく引継ぎが行われるよう、区としても支援、対応をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-04","title":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これはどういう積算になっているのか、それとも都立学校在校生の何かデータがあるのかどうか、教えてほしいと求めました。そのテーマだけを伺うと、今回は教育委員会については２園ということですけれども、ほかの園等を含めて教えてほしいと求めました。","respondent":"芝野保育入園調整課長、荒木学校施設担当課長、柏木学務課長、中谷指導課長、中島保育施設運営課長","answer":"事業者負担分、１％を超える分につきましては、スライド条項を適用するという形になります。ほかの工事案件で申出があったかですが… できた仮設校舎を区が借りるというものです。したがいまして、労務不足というのは、仮設リース事業者の技術者や技術者の下で働く作業員の方々の労務… 特別支援学校の補助教材費について、特別支援学校の補助教材費につきまして、把握ができなかったというのが事実です。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"少し私も理解不足なところがあったのですが、よく分かりました。私どもの会派としては要望しておりましたので、いろいろな事情もあると思うのですけれども、これは速やかにぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"５％未満の議決にはかからない、専決で行われるような案件があるのかどうか、これは確認だけさせてほしいと求めました。それぞれ会派の方々の要望があってつながったのかと思いますが、補正対応、これまでの経緯も含めて、その部分は確認をさせてほしいと求めました。","respondent":"芝野保育入園調整課長、荒木学校施設担当課長、柏木学務課長、中島保育施設運営課長、中谷指導課長","answer":"次に、１億８,０００万円以上の建設工事の契約変更する場合で、５％以上の契約金額の変更が生じた場合に議決案件になるということなのですが。なお… こちらはまだ顕在化しているものではございませんが、各方面へヒアリングして、注視して進めていきたいと思います。各事業者からは… この補助事業の実施方法についても検討しており、当初予算では計上できず、今回の補正予算となっています。それと… 事業の開始年度ということであり、検討期間が必要ということで、実績などは共有してまいりたいと思います。","id":"exchange-021"},{"speaker":"西村委員","kind":"質問・要望","question":"要望ではあるのですけれども、幼稚園だからこそできることと、ハード面の課題があって保育園ではできないこともあろうかと考えています。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問・要望","question":"２点、お伺いしたいと思います。今年度４月から遡って支給できるということなので、精算できなかったら大変だなと思ったので、そこの確認をさせてほしいと求めました。","respondent":"柏木学務課長、中島保育施設運営課長","answer":"その説明ですが、保護者等が自ら購入した教材と、教育課程以外で使用するものは支給対象外となっています。もしその通知をなくしてしまったとか、手元にないという場合は… 対象がゼロから６歳ということになっておりますが、園によって、幅広く対象としていただけるものと考えています。","id":"exchange-023"},{"speaker":"せらく委員","kind":"質問","question":"すみません、もう１点なのですけれども、実施する園の各１名などを対象にされるような形を想定されているのでしょうか。誰が参加するかというところを教えていただけたらと思います。","respondent":"中島保育施設運営課長","answer":"研修につきましてですが、こちらはオンラインで、ＹｏｕＴｕｂｅで動画を視聴するという形になっているところです。幅広く、参加する先生方がご覧いただいて、アンケートに答える形で研修参加という形となっています。","id":"exchange-024"}]},{"id":"topic-05","title":"令和６年請願第１３号、品川区立小中学校の社会科見学・授業等で防衛省見学・自衛隊見学・自衛隊体験などを行わないことを求める請願","agenda":"令和６年請願第１３号、品川区立小中学校の社会科見学・授業等で防衛省見学・自衛隊見学・自衛隊体験などを行わないことを求める請願","exchanges":[{"speaker":"西村委員","kind":"意見","question":"国の機能を学んでいる小学６年生のタイミングで、社会意識の高まりとともに、学んでいただく必要のある内容ではないかと私も思うのですが、小学６年生が国会議事堂に行く際に、ほかに、防衛省・自衛隊以外にどのような行き先を各学校が選んでいるのか、ほかの行き先も説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"ほかの事例といたしましては、６年生で三権分立を学習しますので、その中で、最高裁判所を選んでいる学校もあります。近隣の施設として、科学技術館等といったところに立ち寄って、社会科と理科と合わせてという形の学習も行っている学校が多くあります。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"ここにあるように、防衛省の見学を実際に行っている学校というのは、どれぐらいあるのでしょうか。結果として、子どもがどういう受け止めをされていらっしゃるのかというのはつかんでいるのかどうか、お聞かせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"今年度に入ってから１校です。その後、保護者から教育委員会に対して直接意見を寄せられるということは、特段ございませんでした。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いしたいと考えています。小中学校に特定の国の機関の見学・体験を行わないように求めることは、望ましくないのではないかと考えますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"皆さん国会議員に勧誘しているのですかという話になりますから、ほかの省庁はほかの省庁で勧誘しているのですかという話になるのです。こういった考え方というのは到底賛同ができませんので、私どもの会派としては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"山本副委員長","kind":"質問","question":"理事者の方がご説明いただきました見学の内容において、社会学習として適切に行われていると考えております。本件は会派として不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。これまで３名の委員が述べていらっしゃった内容に同意いたしまして、経験といったところを制限するものではないと思いまして、不採択としました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すで、請願項目の３つに関して、今ご説明ありましたけれども、不採択でお願いします。２番目、３番目のことは行っていないということですので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"憲法には２２条に職業選択の自由もありますので、また防衛省の見学ということは、いい授業だと考えています。以上から、今回の請願に対しては不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-06","title":"令和６年陳情第４７号、ＭＲデバイスを教育利用する設備を設置する陳情","agenda":"令和６年陳情第４７号、ＭＲデバイスを教育利用する設備を設置する陳情","exchanges":[{"speaker":"西村委員","kind":"質問","question":"この５年でのＩＣＴの活用に関する飛躍的な進歩というのは、教育ＤＸに向けたＩＣＴ環境の設備のバージョンアップを続けることは必要だと思います。改めて伺いたいのですが、今後、推進校の取組を全校にどのように広げていくのかを改めてお聞かせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"２年間の研究になりますので、１年間で考えると４校が様々な研究を推進しているということになります。２年間の研究の最後には研究発表会を行っておりまして、そういったいい取組が区内に広がるように、これからもサポートしていきたいと考えております。","id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば、ＳＴＥＡＭ教育に取り組んでいるような官民連携の取組は、今後検討してみていただきたいとは個人的に思っております。もう１点だけ、パソコンルームがあると思うのですが、現在どのように活用しているのかと、今後どのように活用していくのか伺えればと思います。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"１人１台端末が配備されたことで、あらゆる場所で１人１台端末が、活用されています。そういった形で使い分けをしているというのが現状です。 パソコン教室の今後の考え方ですけれども、継続する、今後については考えていきたいと思います。","id":"exchange-034"},{"speaker":"西村委員","kind":"意見","question":"パソコンルームがお教室のように完全に仕切られているスペースではないような学校も多いと思いますが、今、生徒・児童が増えているような学校もあったりと、これから検討していかれるということなので、どのように活用されるかいいかは、これからぜひしっかりとご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"教えていただければと思うのですが、私たちの頃にはありましたが、今もあるのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"現行の教科書には、イカの解剖が載っていることが多いです。動画で見たりということを、それこそ補助的に行っている場合もありますが、実物に触れるというのがベストなことです。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"今の学校現場においては、ＩＣＴ技術を活用する一方で、実物を大切にするということもありました。先ほどのご説明を伺うと、決して否定するものではないということで良いか、そこだけ確認をしておきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"最近だとタブレットで映像を見たり、そういった形では、補助的な形で学習を深めています。それがまさに子どもたちが３６０度見回すとか、あくまで補助的な役割を果たすということで、有効なものだという認識はあります。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"このＭＲデバイスは最新技術で、専門的な知識が必要なのかなと思って読んでいました。そういった事例があれば教えていただきたいのと、コミュニティ・スクールにご協力いただくことは可能かどうか、お話を説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"そこはぜひご協力いただいて、子どもたちの教育活動に活かしていきたい、その辺りは協力していただけるのではないかと考えております。事例としては、今把握しているものはないのですけれども、今後そういった形での連携ができると、より効果的だと考えます。","id":"exchange-038"},{"speaker":"西村委員","kind":"意見","question":"誰でも使えて操作ができること、教育の環境基盤を整えるものといった、普遍性や汎用性を持つ機器が適していると思われます。様々な議論が必要と思いましたので、直ちに採択はできないと考え、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"意見","question":"ネット等で見させていただいて、どういうものかというのを自分でもそれなりに勉強して、非常にすばらしい技術であるということを実感いたしました。品川区として現段階での導入というのは、時期的にはまだ早いのではないかというところで、現段階においては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"山本副委員長","kind":"質問・要望","question":"そのような検討や、検討の支援を要望いたします。今後の技術進歩を確認しながら、研究を進めてほしいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"せらく委員","kind":"質問・要望","question":"教育の機会でもぜひ進めていただきたいとは思うのですけれども、価格が高額ということで、個人購入が難しい。区で購入してはどうかという部分で、どうしても判断が難しかったのですけれども、この判断をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その中で、このＭＲデバイスをどうするかということも含めて、いわゆるグランドデザインを考えてほしいと求めました。これは陳情とは別で、要望になりますけれどもお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"私はもう１０周遅れぐらいの者ですが、その技術を教育に活かすべきだというご提言は、しっかり受け止めていただきたい。学校現場での体制整備も必要だと思いますので、時期尚早ではないかという判断から、今回の陳情は不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-07","title":"専決処分の報告について（報告第２５号）","agenda":"専決処分の報告について（報告第２５号）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"今後の訴訟の中で、和解であるとか、強制執行まで行くのかとかいう流れを教えていただきたいのが１点です。No.１の方については３９万円ということなのですけれども、これは簡易裁判所で、それとも普通の訴訟の方式でやられているのか説明を求めました。","respondent":"飛田子育て応援課長","answer":"ただ、その後、また納付等手続を行いまして、執行されない、返還されない場合は、強制執行または債権放棄という流れとなります。こちらは普通の奨学金の返還の求めということになります。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"普通の訴訟ということなのですか。１日で結論が出る少額訴訟という制度があると思うのですけれども、そういうのは使わないで、No.１の方についてもそれでよろしいのか尋ねました。","respondent":"飛田子育て応援課長","answer":"１番の方については、住所がまだ不明というところもありますので、まず裁判所で、そこのところをどのようにしていくかというところが決められると聞いております。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"少し教えていただきたいところがあるのですが、あと裁判にかかった費用だとか、そういったものも上乗せして請求がなされるのだろうと思うのです。裁判になるといろいろともろもろ、求める際にそういう先のことまでお伝えして、そこまで含めて返還を求めていくというのはどうなのか尋ねました。","respondent":"飛田子育て応援課長","answer":"大体、訴えを起こしまして、全ての判決が和解や分納合意ということで、継続的に支払いをしていただくというふうになっております。違約金の計算にかかる利率は、最初に延滞が発生した時点で起こる利率となりますので、そちらも今後また発生すると今後は伝えていくことになります。","id":"exchange-047"},{"speaker":"田中委員","kind":"確認","question":"もう一度確認ですが、先方が借りた金額プラス、最終的に支払わなければいけない日から換算して、その分の利子が違約金として加わってという、そこまでは伝わっていて、早くお納めくださいと、そういう流れということか尋ねました。","respondent":"飛田子育て応援課長","answer":"そのようになります。","id":"exchange-048"},{"speaker":"せらく委員","kind":"質問","question":"すみません、少し聞き取れなかった部分がありまして、No.１もNo.２も平成のときに支払いをしていて、返還されなくなってから１０年ぐらいたってしまうようなことになっているということか尋ねました。","respondent":"飛田子育て応援課長","answer":"２番の方です。令和元年５月が最終支払いで、何も連絡がないということで、令和４年１１月より弁護士にお願いをしているという流れになっております。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"ないのかということの確認もどうだったのかということと、あと、金額が妥当なのかという部分についてお願いします。これは同じく２９号も、どういうものが対象になっているのかというところを、まず確認させてほしいと求めました。","respondent":"舩木庶務課長","answer":"この写真の場所に、言えることは、明らかにフェンスを越えたボールが車両に損害を与えたと認識しております。その金額の妥当性であるとか、その辺は、相手方と丁寧に誠意を持って対応したというところによる賠償額の決定ということで認識をしております。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもたちのクラブ活動を応援していただけるように特に教育委員会の皆様や学校の先生方は、そういう視点でぜひ捉えていただきたいと考えています。特に子どもに対するフォローというのでしょうか、それは決して萎縮させないような方向で、どんな対応をされたのかお聞かせほしいと求めました。","respondent":"舩木庶務課長","answer":"４月から６月に新入生が入ってくるわけですが、一方で管理する側も、しっかりと監督していくということで対応してまいります。損害に遭われた方もその場を確認いただいた上で、練習を再開していると聞いておりますので、今後も安全管理に努めてまいりたいと思います。","id":"exchange-051"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"名のり出た方は、通報された１名だけだということです。閲覧したかどうかの調査とありましたが、それはダウンロードができるようなファイル形式だったのか、その辺りも説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"幾つかフォルダがあるのですけれども、その中で今回、全学年の児童が閲覧可能なフォルダに保存してしまったということです。当然、資料箱ということで、学習に活用する資料をそこに保存するべきところですので、データはダウンロード可能なものでございました。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"確認","question":"漏えいの事実は認められないということですけれども、もう１点だけお聞きします。ダウンロードされたかどうかというのは、いわゆるアップロード元というか、学校では確認ができるのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そのフォルダからダウンロードしたかどうかのログを確認することは、極めて困難だということです。資料箱を見た人はいるかどうかという確認をしたところ、誰もいなかったということですので、そういったところで今回は収まっているです。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童も閲覧可能なところに入れてしまったということは、どなたか、教員が入れてしまったわけですが、その方は、後からあのときにミスして入れてしまったということは、分かったのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"保護者から指摘をいただきまして、確認したところ、ファイルが置きっ放しになっていたということで、そこに保存した教員については、誤ってそこに保存してしまったという認識は、言われて初めて気づいたです。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、ご自分でいつそこに入れてしまったかは、記憶がないという認識でよろしいか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"９月３日の夕方、午後４時３０分頃に、ダウンロードして保存したということは覚えていらっしゃるのですけれども、それが、全児童が見られる保存先だったというところについては、自身の認識の甘さというか、誤ってそこに入れてしまったという自覚はあります。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/435368?Template=document&Id=6815#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":43691,"voices":201}},{"id":"r06-20240924-5","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"総務委員会","time":"午前１０時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を99件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この悪質クレーム・カスハラの状況調査というものは、今少し説明はあったのですけれども、いつからやられているものなのでしょうか。そして、これを精査して認定された場合、どういう対応がされるのか伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"この調査ですけれども、例年実施している調査ではなく、昨年８月に実施したものです。内容精査も含めた上で、今後どのような政策を検討するかというようなことですので、認定するかどうかも含めて精査をしていきたいと考えています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"昨年の８月に各課から状況調査ということで、これは今後もずっと続けていくものになるのでしょうか。各課の件数が分かれば伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"職員個人に対していろいろアンケートを実施したりですとか、そういったことも参考にしながら検討してまいる予定ですので、同じ調査を。続きまして、この調査の件数ですけれども、十数課からの回答があったということと、あとは、調査全体で３９件の回答があったです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは、悪質クレーム、そしてカスハラの状況調査をして、今後、生かすというのは、どういう形になるのでしょうか。分かれば伺いたいのと、具体的にどういう状況か、分かれば伺いたいのですが。","respondent":"石井コンプライアンス推進担当課長","answer":"個人が業務を対応するのではなく、今後、政策を検討していくというような形で本調査の内容を生かしていきたいと考えております。そういったところも含めた上で、組織的にきちんと内容を検討しながら対応していくこと、それが大切だと考えております。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"この第４０号と第４１号の陳情に上げられている請願・陳情を多数出していることから業務が増大しということで、私は区としては大問題だと思うのです。これが認定されるものではないということですけれども、少し問題なのではないかなと思うのですけれども、そこはいかがか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"本調査については、業務に支障を来す状況まで発生している状況について記載しているものです。どういう認識でいるのか、そういったことも含めて調査票の内容を今後精査していくものであると、そのように考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、このことを悪質クレームとカスハラの元凶として挙げている都市開発課、その感覚自体が問題ではないかと思っています。請願権ですから、ぜひ見ていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"そうした中で……。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"住民要望を受けた２人の議員の名前も出ていますけれども、この２人の議員から、区長からの返事はどのような内容だったのか伺いたいと思います。それで、区長室長から返答されたということですので、室長から、もし伺えればと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"内容につきましては、こちらの陳情に書かれてありますけれども、７月２９日に区長室に足を運び、区長室長を通じ面会を求めましたけれども、今回、民民の内容というふうなことですので、面会をお断りしたです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"その具体的な経過を伺いたいのです。どういう依頼をされて、区長からはどのような返事が来たか伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"こちらは陳情書にも書いてありますけれども、区長室長を通じ面会を求めたというようなところで、８月１日に区長室長から電話で、再開発事業は民民の問題なので、地権者との面談には応じられませんというようなことで回答を差し上げているものです。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこを確認させていただきたい。全ての区民と区長が会うということは難しいと思うのですけれども、区長が区民と面談するしないを決める基準は何かあるのか伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"区長室長が電話で返答するに当たりましては、もちろん区長に確認していますし、それが区長の言葉として先方に伝えられたものです。そういったことではございませんけれども、区長は総合的に区政を推進する立場において、必要に応じて面会をするしないを適切に判断しています。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"しっかり懇談されて、そういう場を前区長は、推進側の皆さんとはしている。どちらとも会わないものなのか、どういう基準なのかということがもう少し分かるといいなと思うのですけれども、いかがか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"再開発事業は民民の問題なので、地権者との面談には応じられません、そのように回答しております。これが１つの考え方を表すものではないかというふうに考えられます。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"確認","question":"そういうことだということが確認できたと思うのですけれども、再開発についてだと、公共事業だと品川区は言いますよね。区が密接に関わっている事業なので、民民だから介入しないというのは通用しないと思うのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"冒頭でご説明した繰り返しになりますけれども、権利者の同意のもと、３分の２以上の同意というところで組合が設立して事業を進めるものになります。〔傍聴席にて騒ぐ者あり〕 話し合いが行われて進んでいくものになります。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"民民という形では片づけられない問題だということで、区議会議員も２名入って面談を申し入れたのですけれども、そこはどうお考えでしょうか。伺います。","respondent":"石井コンプライアンス推進担当課長","answer":"区が様々なご要望ですとか意見を表明する場は、区長の面会だけではなく、様々な機会があってしかるべきだというふうに考えてあります。区長室長からお答え申し上げたとおり、再開発事業は民民の問題なので、地権者との面談には応じられないということでお答えをしています。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区長も、区民の皆さんと意見を交わして相互理解を深めて、そこで様々なアイデアを出していただくというふうにおっしゃっていますよね。そういう立場にある区長ですから、区議会議員が仲介に入ったわけですから、そういう場ではないわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"カスタマーハラスメントの調査ですが、改めて、目的と、その調査について公開するということを想定していたのか伺います。今回、こういうふうに具体的な文言が出ているわけですけれども、これが出てくるに至った経緯についてお願いします。","respondent":"石井コンプライアンス推進担当課長","answer":"区に対する悪質なクレームが業務に支障を来す事態まで発展しているケースが増加しているというようなところで実施したものです。当時、認識されていたというところがありまして、調査票に記載されたものです。","id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"３９件ほど上がってきているかと思いますけれども、していないかで言ったら、認定はしていないということも先ほどご答弁があったと思います。改めて、今度は、都市開発課長にお伺いしたいのですけれども、これは、こうした声が職員の声として上がったということでよろしいか尋ねました。","respondent":"中道都市開発課長","answer":"職員のほうから声が上がったものになります。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"これ、例えば、現職の議員が職員の方にいろいろと要望をしていく。あれはハラスメントではないみたいなことが議会で行われたら、この後のアンケートで、そうした職員は生の声を上げることができるか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"だから、今回も、そういう請求があったので外に出てきたということでよろしいのでしょうか。その標題として「悪質クレーム・カスハラの状況調査」という資料になっているのか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"こういった文書を作成したら、それは公文書として扱われるものですので、情報公開請求の対象となり得るものです。調査の標題ですけれども、「悪質クレーム・カスタマーハラスメントの状況調査について」ということで依頼をしていますので、それが調査の名称です。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"だから、アンケート調査をとるときに、「職員の方々、困っていることはないですか」とか、違う表現だったら、これは公文書でいくわけではないですか。「悪質」ですからね、誰がどういうふうにして、こういう標題をつけたのか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"長時間対応を要するなど業務の遂行に支障があるということ、３番の悪質な相手であるということ、ということを調査の内容としてつけているものです。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"なので、そういうことと分けてきちんと考えていかないといけないのではないでしょうかという、非常に私はそこを疑問に思います。間違った方向に解釈されるような公文書であってはいけないと私は強く思いますが、いかがか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"どういう対応をとっていくか、こういうことだから直ちにカスハラだとか、そういうふうな短絡的に決められるものではないと思います。今まさに東京都も、そういったことも含めながら、きちんと進めてまいりたいと考えております。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"やり方はどうですか、いいのですか、法律的な流れは分かります。これはまた別の問題が出てきてしまうので、こういう実例はあったのか尋ねました。","respondent":"中道都市開発課長","answer":"準備組合が、今、合意形成というところで、権利者の方に個別面談等を行っているという状況ですが、準備組合に確認したところ、こういった状況はとっていなくて、個人面談を行う際には、事前に時間調整等を行って、相手に配慮した形で対応しているというふうに聞いております。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"本当にきちんとやってくれているのですかと。やはり相手側がいることでありますので、それをきっちりと尊重しながら丁寧に対応していただきたいということを強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、もう１回、確認をさせてほしいと求めました。悪質クレーム・カスハラの状況調査からの削除を求める陳情ということだと書いてあるので、今回、お聞きしたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"本調査につきまして、この目的です。そういった悪質なものに関しては組織としてきちんと対応していくため、職員が相談しやすい環境をつくるため、調査を実施しているものです。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今再度確認させていただいたのですけれども、今、少しずつ一歩一歩進んでいると思うのです。ですけれども、どうか一人一人の職員を大切にして、長く勤めていただけるように努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"確認","question":"１個だけ確認したいのですけれども、この状況調査が、職員の相談環境をつくりやすいものにというのは分かりました。活字は難しいではないですか、見方によってはどうとでもとられてしまうので、職員も自分の文字として残すことができなくなってしまう。","respondent":"石井コンプライアンス推進担当課長","answer":"個別具体の回答内容については、こういう内容の回答が多かったとか、職員が困っているようだというようなことで精査をすることができます。は、その中で政策としてどのように進めていくかということについても議論が可能であるというふうに考えております。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"議事録を確認させていただいて、こういう調査があった、そして３９件のそういう声があったということがそこで一旦公表されています。３９件のうちのどこかの一部分が公開されたのか、全体が公開されたのか、そこら辺を確認させてほしいと求めました。","respondent":"石井コンプライアンス推進担当課長","answer":"例えば、例えば調査票の開示を求めるという情報公開請求があった場合については、調査票をまとめたものがあります。そのフィードバックした調査の集計一覧を公開するような形になってあります。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問","question":"公開されるものが、課から上がってきたものをまとめて、それに対する回答というようなイメージでしょうか。それが何かしらの検討がされてまとめられたものが課に戻って、それが公開をされているということか尋ねました。","respondent":"石井コンプライアンス推進担当課長","answer":"昨年度９月に各課にフィードバックした内容ですけれども、その中でどう対応するとかというような検討がされたものではなく、まず。併せてそのときに、そういった啓発ポスターも含めて、各課に周知依頼をしたものです。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問","question":"区としての対応の仕方について、最後、お聞きしたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"今、東京都でガイドラインの作成などが委員会でされているところです。区の実態に合わせて、どのように職員が対応したらいいかとか、そういったことについての内容の検討を進めていくです。","id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"まさしく今、東京都が議論中であります。そこは品川ナイズしたものにしっかりとしていただきたいということを要望させていただいて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"品川区の職員を守る、しっかりと対応していくということが求められている中で、ぜひしっかり進めていっていただきたいと考えています。そもそもカスタマーハラスメント調査票からの削除を求めるということで認定もしていないということでありましたし、陳情第４０号についても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は削除すべきだと思いますし、もう１つの民民だから会わないという区長面談のところ、私もそう思います。様々指摘はしてきましたけれども、今回の計画で苦しんでいる住民の声を直に区長自身が聞くべきではないかと思っていますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"これ、セクハラとかパワハラのときも同じことを言えるのですかという話なのです。これはセクハラも一緒ではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、これも再開発の問題、根底からの問題を考えないといけないときに来ているのではないですかという提起なのですよね。建設委員会に関係すると思うので、ぜひそれをやっていただきたいと思うし、区長の認識も変えてもらいたいなという希望を申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"まつざわ委員","kind":"意見","question":"結論を出すで、不採択です。先ほどおっしゃっていましたが、区がオリジナル、品川区独自の方向性をしっかりと決めていただければいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。さっき２つまとめてだと思って言ったのですが、そもそも認定していないというようなことから、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"意見","question":"本日結論を出すで、採択です。やはり憲法に認められた請願権を理由にしているというところでは、悪質クレーム・カスハラには当たらないと思いますということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"増築部分で何人分でしたか確認させていただきたいのと、特養ホームが足りないからつくってということを様々要望してきたのですけれども、ＺＥＢにすることで少し高くなるということもあったりするのか伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうもので決まりというか、基準があるのか、どうやって決めているのか伺えたらと思います。","respondent":"長尾施設整備課長","answer":"実際に設計を進めていく中で、ＺＥＢ認証を取得できるように検討を進めるというところで、基本的に検討に着手しているところです。こちらの施設については、結果的にはＺＥＢ Readyというところで認証を取得しているところです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"これは金額が低いからということなのでしょうけれども、品川区の企業共同体として入札をかけているということなのですか。どういう決まりがあって、こういう形態になっているのかなといつも不思議なのですけれども、いかがか尋ねました。","respondent":"佐藤経理課長","answer":"４億円以上の工事であれば、基本的には共同企業体を検討するという形になっておりまして、区が発注する中でもかなり大きな規模の工事になります。応札していただける事業者が見込めないということであると、結果的に、他自治体の事業者が１番をとっているという状況かと思います。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"その辺はどうなのでしょうか。大田区みたいな、そういう企業体でもいいと言えばいいですよねというふうに思うのですけれども、その考え方はいかがか尋ねました。","respondent":"佐藤経理課長","answer":"したがいまして、この共同企業体についても、例えば、１番に関しては、区外であっても施工能力に応じて参加してください。ただ、そういった区の原則として区内事業者に受注機会を確保するというところに基づいてやっているとご理解いただければと思います。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり品川区の中でも育っていただきたい、成長してほしいなという思いがあるので、そういうふうな見方もあるということです。委員会が違いますので、ここは答弁をいただきませんが、そういう見方もあるということで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"それから２番目に、入札金額の積算ですが、これ、どう見ても、ほぼ１００％に近いのではないですか。それとも、積算する会社に依頼して、このような金額を出しているのですか、これについて説明を求めました。","respondent":"長尾施設整備課長、佐藤経理課長","answer":"１つ目のご質問の体制のところですけれども、入札した事業者の企業からは、施工体制に関して報告を受けております。３つ目の積算に関しましては、予定価格につながるような積算については… 事前に予定価格を公表した上で応札いただいているという状況ですので、１つは、予定価格に近づくということはあるかなと考えます。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"共同企業体でそれぞれ仕事をやって割り振りをされているということですが、私が先ほど申し上げたのは、実態調査をしているのですかという話です。そういうことは考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのですが、落札が１者になっている契約が２件あるというところで、どのように捉えているのかを教えてください。辞退理由も、積算金額が予定価格を超過したというのは１件だけだったのですが、どういうふうに捉えているのかということを教えてほしいと思います。","respondent":"佐藤経理課長","answer":"応札するところがないという状況もあるということは把握しておりますので、事前に、年間でこういう工事を予定しています。もちろん予算に始まるところですけれども、そういったところを情報提供する中で、応札につながるような形で工夫をしていきたいと考えております。","id":"exchange-043"},{"speaker":"大倉委員","kind":"意見","question":"そうした需要が一定落ち着けば、またいろいろな入札が増えてきて、１者入札ということが減るのかなとも思いました。年間工事についても、なるべく早く反映しながら、応札が増えるようにということで工夫もされているということで分かりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そういう啓発も進めていただきたいと、人材の確保もやっていただきたいと思うのですが、３つが辞退ということになっております。これがどの段階で区のほうに申入れがされてきているのか、これは入札をして金額を出して、その後の段階なのか、教えてほしいと求めました。","respondent":"佐藤経理課長","answer":"入札しないということで意思表示をされるということですので、実際、入札してみたときに辞退だったということが分かるという形になっております。","id":"exchange-045"}]},{"id":"topic-02","title":"第８５号議案、プレハブ冷凍冷蔵庫他の買入れ","agenda":"第８５号議案、プレハブ冷凍冷蔵庫他の買入れ","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"冷凍庫と冷蔵庫が別々になっているのか、平米数で言うとどれぐらいなのかということが分かれば伺いたいのと、分かればでいいです。１５ページの５番で、今まで使っていたものを同じように買い入れるということでいいのか、その確認だけ。","respondent":"菅野高齢者福祉課長","answer":"スペースに合わせて設置することができるなど、冷凍の部分と冷蔵の部分を中で区分けできるような形になっているというふうに聞いております。もう２５年たっておりますので、新しいものに進化しているというようなことで、機械は選定させていただいているところになっております。","id":"exchange-046"}]},{"id":"topic-03","title":"第７６号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正す…","agenda":"第７６号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正す…","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"今のご説明だと、文言整理がされるだけで、区民への影響は変わらないということで確認させていただいていいか尋ねました。","respondent":"横田デジタル推進課長","answer":"委員ご指摘のとおり、区民への影響はないものであります。文言修正になります。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"ちょっと教えてほしいのですが、改正の理由の中に、区独自の個人番号の利用および情報提供ができるとなっているのです。どういうことが可能になって、仮にそういうものがあったとした場合、どういう対応をしていくのかということを説明するよう求めました。","respondent":"横田デジタル推進課長","answer":"こちらも法律の「進学準備給付金」の名称が「進学・就職準備給付金」というふうに変更されたことになりますので、こちらで変更になります。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"今までやってきたことに対して法律が変わって、だから、区民の方々には今までと同じなので変わりませんよということの理解でよろしいでしょうか。個人情報ですから、これからの進め方、適用の仕方も含めて説明を求めました。","respondent":"横田デジタル推進課長","answer":"ご指摘のとおり、法律の変更に伴う文言修正になりますので、特に区民への影響はないものです。事務の運用に関しましても、(2)の私立幼稚園につきましても、これまでもやってきたものですので、特に運用の変更はないものであります。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"この仕事は、デジタル推進課の仕事になるのですか。マイナンバーカード関連だと、デジタル推進課になるのか尋ねました。","respondent":"横田デジタル推進課長","answer":"こちらのマイナンバーの条例に関することですとか、マイナンバー制度の運用全般ですとか、マイナンバーカードの利活用につきましては、全庁に関わることですので、企画経営部のデジタル推進課で行うこととしております。","id":"exchange-050"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。施行が令和７年７月１日となっておりまして、この段階でこれを出されているというのは、何か理由があるのか教えてほしいと求めました。","respondent":"横田デジタル推進課長","answer":"「進学準備給付金」の名称を「進学・就学準備給付金」と変更する規定整備が併せてございましたので、同じような生活福祉法関連ということもありますので、「生活困窮外国人保護事務」に関しても、併せて今回のタイミングで行うことといたしました。","id":"exchange-051"},{"speaker":"新妻副委員長","kind":"質問","question":"進学に関わる、来年の４月に関わるということがあって、併せて今回のタイミングという理解でよろしいか尋ねました。","respondent":"横田デジタル推進課長","answer":"令和７年７月１日で施行されるということが分かっておりましたので、今回、改正することといたしました。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"関連なのですが、ということは、今までやってきたことなので、施行期日が来年の７月１日であったとしても、やることは、ほかの条例の中でやっているので問題ありませんと、区切りとして、この令和７年７月１日にしましたということでよろしいか尋ねました。","respondent":"横田デジタル推進課長","answer":"令和７年７月１日に生活困窮外国人保護事務の施行期日が法律によって規定されるということになりますので、条例は、それ以降、削られるというところで、このような記載としております。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成なのですけれども、マイナンバーについては、さらなる拡大推進というのは、私たちは、大本では反対をしておりますが、今回は文言整理、あと、生活保護のところでは、当事者の要望に応えたものにもなっているという国会での議論もありましたので、この件については賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２番の小規模非住宅用地に対する軽減措置は平成１４年度、最初の１番などは３６年前になっているのですけれども、ここで聞いても分からないですか。軽減措置を求め始めたときが、そういう経過が分かれば教えていただきたいのですが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"３年に１回、経済とか、そういったものの影響を受けて高くなることもあります。中小企業の支援ということも目的としておりますので、昨今の厳しい経済状況を全て勘案して、こういったところの見直しをしていると認識しております。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここにインボイスということも書かれていますけれども、これが今後の二、三年で解消するものではないと国も見通していると思うのです。こういう経済状況ですから、少なくとも１０年間ぐらいはすべきだみたいな、お答えほしいと求めました。","respondent":"吉野税務課長","answer":"これに関しましては、これまでも実際には東京都が賦課徴収しておりますので、東京都の分野になります。ですので、これにつきましては、東京都の動向を注視していきたいと考えております。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１０年間、そういう状況なので、区から求めていくということをぜひしていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"意見書ですから、こういう結果が得られたという成果、それはどういうふうにはかられていますでしょうか。今後、意見書をつくったり、議会としてやっていかなければいけない調査もあるのですが、理事者はどう受け止められていますか尋ねました。","respondent":"吉野税務課長","answer":"毎年こういった意見書という形で要望を上げていただいていますので、それなりの効果はあるので、こういった軽減措置が続いているというように考えております。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"どうなのでしょうか。これだけ長く出しているわけですから、区としての動きは何かしらあっていいのではないかと思うのですが、いかがか尋ねました。","respondent":"吉野税務課長","answer":"その中で、こういった軽減措置が必要になってくるかと思います。そちらのほうでは、こういった課題が実は出ておりませんので、少し検討させていただきたいと考えています。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、こういう措置は当然だと、それを計算に入れてのベースになるような形をぜひ品川区としてもやっていただきたいのです。だったら、少しでも全体で底上げできるような状況を品川区発信でやってもいいのではないかと思いますけれども、いかがか尋ねました。","respondent":"吉野税務課長","answer":"実際にこういった状況を分析しまして、言える場所があれば、そのように確かめていきたいとは思います。","id":"exchange-060"},{"speaker":"西本委員","kind":"意見","question":"そういう経済状況を鑑みたときに、もっと品川区内の事業者の方々が助かるようなことがあるのかどうかということがあってもいいのかなと思います。これは意見でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"須貝委員","kind":"質問・要望","question":"確認ですけれども、今日、区長はいらっしゃらないですけれども、区長会で、毎年きちんと話し合っているのですよね。どうか尋ねました。","respondent":"堀越副区長","answer":"毎月、配分割合等についても、これまでも交渉の場面に応じてご報告をさせていただいていると認識しています。この請願についての総務委員会の審議だと認識しておりますので、一定いろいろ切り離して考えて、そのように感じたところです。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問・要望","question":"企画のほうで企画経営部長も、やはりもっと発言して、私は、闘うべきところはしっかり闘ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"公明党も、結論を出す、採択で、紹介議員にもなっておりますことから、意見書も出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出す、採択で、意見書も出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"松本委員","kind":"意見","question":"１個だけ、紹介議員になられている各会派の皆様になるのかもしれませんけれども、この請願の表現で「サラリーマン」という表現があります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"}]},{"id":"topic-04","title":"令和６年陳情第４８号、事業者へのインボイス制度の影響について品川区内実態調査実施の陳情","agenda":"令和６年陳情第４８号、事業者へのインボイス制度の影響について品川区内実態調査実施の陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"地域経済を振興すべき品川区として、インボイスが中小・零細企業、個人事業主に影響を与えていると認識はされているでしょうか。調査を行う必要があると思わないかどうか、まず伺いたいと思います。","respondent":"加島財政課長","answer":"令和５年度決算では、予算額５８６億円に対して決算額５８７億円と、予算どおりの収納がなされていることは確認しております。今、数字の状況といたしましては、増加の傾向を示しています。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、調査を行う必要性がないと感じられているのでしょうか。お願いします。","respondent":"小林地域産業振興課長","answer":"本制度については、先ほど、財政課長が説明したとおり、国の制度です。そのため、実態調査ですけれども、その制度的な部分での影響は、地方自治体においては大変困難な分野であると考えております。","id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国で判断されるということですので、では、国に実態調査を求めていただくということはできるのですね。確認されている、認識されているということでよろしいですか、伺いたいと思います。","respondent":"加島財政課長","answer":"１点目にご質問いただきました、先ほど冒頭にご説明申し上げたとおり、国の責任において実態調査を行うどうかは主体的に判断すべきと考えております。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"確認","question":"中身も確認されているかということを伺ったのですけれども、国が今、区として把握する必要はあると思っていないのでしょうか。伺いたいと思います。","respondent":"加島財政課長","answer":"陳情についてきた詳細な資料を確認されたかという点では、拝見させていただきました。区として実態調査を行う考えはないのかというところですけれども……。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"区としては把握していないのかどうかも伺いたいのですけれども、区内ではないにしても、全国の声が出ているわけです。改めて伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"一方で、国、東京都、特別区、それぞれの権限なり財源、実情に応じて中小企業支援が実施されているところです。それぞれの対応能力に応じて、地域経済の下支え、あるいは消費喚起などにつながる施策をしっかり進めてまいりたいと考えております。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、この陳情文にもあるのですけれども、前回、私も実態調査を求めましたけれども、該当する課で相談も受けているというふうに答弁がありました。どれほど、何件、どのような内容で相談が寄せられているのか説明を求めました。","respondent":"小林地域産業振興課長","answer":"年間３,０００件、４,０００件といった経営相談の対応がありますけれども、認識してございません。やはりこういった相談は、国のインボイスの相談センターのほう、あるいは税務署などに相談が寄せられているのではないかという認識でございました。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いかがでしょうかということと、陳情にもありますけれども、実態調査をしないという理由にはならないというふうに書かれているのです。私も理由にならないと思うのですけれども、そこはいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"そういうお話があれば対応するですけれども、事業者のほうにも、税務署以外も業種別にいろいろ相談の案内の通知なども行っているようです。専門的知見も含めて、そういったところの国の対応ということで、我々は判断すべきものであると考えております。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ国にも求めていただきたいですし、なかなか進まないというところがあるので、ぜひやっていただきたいと思うのです。そういうところで、皆さん、ご意見をお聞かせいただけたらと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"この陳情、なぜ総務委員会にかかっているのでしょうか。なぜ総務委員会なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"なぜ総務委員会でやるのですか、総務委員会でやる意味はあるのですか。どうなのでしょうか、答えるよう求めました。","respondent":"久保田企画経営部長","answer":"この委員会の付託は議会のほうで決めて付託されていますので、それに基づきまして、私どもとしましては、審査のときに質疑に応じているといった中で、総務委員会でできることということで、所管の課長にも来ていただいて、今、質疑の応答をしていますといった状況です。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"だって、区民委員会だったら、それなりのいろいろな方がいらっしゃるのに、担当がいらっしゃるのに、そこで議論すべきではないですか。影響している人がいれば何とか助けてあげようという思いで仕事をされているのか、どちらか尋ねました。","respondent":"小林地域産業振興課長","answer":"１つは、国の制度の中でも地方自治体に一定の権限なり財源なりというところが法律である程度定められ、その中で事務を行うというものもあります。中小企業支援というところでは、品川区として独自の支援なども行いつつ、そういう考えです。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"国がやるべきではなくて、品川区民の方々が、どういう現状があるのかというのは調べるべきではないですか。調べるべきではないか尋ねました。","respondent":"小林地域産業振興課長","answer":"インボイス制度そのものについてというところで、制度自体の権限といいますか、個別の事実関係なども含め、責任ある政策判断および施策実行の権限ですとか専門的知見、そういったものを有する国において判断すべきものであると考えております。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"そうしたら、中小企業の実態調査、それから冊子、機関誌ですか、冊子を出していますよね。どういう影響が品川区民の皆様方に対してあるのかということを調べるのは、いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"インボイス制度につきまして、責任ある制度の政策判断も含めて、そういった調査の実態というところも、ある程度の情報というところで国が権限を持っているところですので、国において判断すべきものであると考えております。","id":"exchange-079"},{"speaker":"西本委員","kind":"提案","question":"実際にどうなっているかという細かい調査をしないという、やっているわけですから、品川区は。いかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"自治体に与える影響というところも含めて、そういった基本的情報を持っている国が、やはり一元的に管理しているものです。そういった権限なり専門的知見という観点から、区で実態調査を行う考えはございません。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"施策が出てくるのではないでしょうか。やはり区民の人たちがどうあるのかということを常に意識していただきたいということを強く申し上げて、意見として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"まつざわ委員","kind":"確認","question":"何点か確認させてください。そこで管理しているということなのか、まず説明を求めました。","respondent":"加島財政課長","answer":"事業を新規に始めるときの登録ですとか、それから、何らかの理由で事業を廃止するとき、こちらの届けについては、所管の税務署に届出するということです。","id":"exchange-082"},{"speaker":"まつざわ委員","kind":"質問","question":"そういうものを税務署が管理しているのですよね。それに関する情報というのですか、事業者の情報というのですか、私たち地方自治体にしっかり共有されるものなのか尋ねました。","respondent":"小林地域産業振興課長","answer":"これは自治体のどの部局も共有していないものと認識しております。","id":"exchange-083"},{"speaker":"まつざわ委員","kind":"質問","question":"今回のケースだと、国で集めたそういった情報は、どのケースでも自治体には共有していないということですよね。もっと専門的視点とか、そういったものが前提になるかと思いますが、そこについてお考えを説明するよう求めました。","respondent":"加島財政課長","answer":"は個人事業税の令和５年度、今、把握することができておりません。実態調査は国の判断で実施すべきという考えは揺らぎませんが、ただ、経営相談といったところを設けて自治体としてできることに支援を注いでいます。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問・要望","question":"年々物価が高騰しているということで、インボイスがそこに入ってきたわけですから大変だなという実態は、本当にそのとおりです。質問しようかと思ったのですけれども、話を聞いていると、なかなか質問には至らないかなと思ったので、一応意見だけ言わせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"大倉委員","kind":"質問","question":"実際の実態調査をするというところの大変さは、今お話を伺っている中で非常に感じたところであります。３年たったら、所管の課長もいるので、ぜひ説明を求めました。","respondent":"小林地域産業振興課長","answer":"ほぼ９割方、金融機関に融資あっ旋といいますか、紹介状が通るような形になっているところです。そういったときの対応として、例えば、経営をどういうふうにしていけばいいのかというところを対応していくことがよいかと考えています。","id":"exchange-086"},{"speaker":"松本委員","kind":"質問","question":"そこに関係してお伺いしたいのは、当区も運送事業者等燃料費高騰対策支援金というものを過去交付していると思います。でも、これは審査と関係するので伺いたいのですけれども、屋形船を入れたのは、当区の判断で入れたのか尋ねました。","respondent":"小林地域産業振興課長","answer":"ただいまご質問、ご指摘のありました運送事業者等燃料費高騰対策支援金については、区独自の対策ということでやっているものです。水産事業者、運輸事業者を両方やるべきだということで、対応したものです。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"これはアンケートの項目について、何か国から定めがあるのでしょうか。それとも、ある程度、区のほうで項目を追加することはできるのか尋ねました。","respondent":"小林地域産業振興課長","answer":"質問項目といいますか、景況感を聞くということを長期的に見て一番継続してやっているものですけれども、そういった状況を見ながら実施しているものです。","id":"exchange-088"},{"speaker":"松本委員","kind":"質問","question":"お伺いした、区で独自の項目を追加することができるかできないかという点はいかがか尋ねました。","respondent":"小林地域産業振興課長","answer":"この事業者を把握するということも、我々もふだん事業者にいろいろご協力をお願いしながらですので、なかなかこれも苦労しながらやっているところです。","id":"exchange-089"},{"speaker":"松本委員","kind":"質問・要望","question":"今の話をお伺いしていても、今回の調査を求められている方たちの願意に沿うというやり方が、実態調査というやり方ではありませんが。最終的には、最後、意見表明のところで述べたいと思いまして、私の質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"事業主の方等でありますので、今後とも、そういう方のお声はしっかりと把握をしていっていただきたいということは要望させてほしいと求めました。中小・零細企業の方々のお声を聞く場を引き続き広げてほしいと求めましたが、何かそういうことがありましたら、教えてほしいと求めました。","respondent":"小林地域産業振興課長","answer":"個人の方が事業を進めるに当たっては、あるいは武蔵小山といったところも、そういったフリーランスの方もたくさんいらっしゃると認識しております。相談の内容とかも踏まえて、我々として、どういう支援制度があり得るのかということはしっかり考えていきたいと考えております。","id":"exchange-091"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そもそもこのインボイス制度の影響がどう出ているかというのは、自治体で実態調査をして、本当に正確に分かるのかということに私は疑問があります。今以上にそういったご相談があった際は、積極的な支援といいますか、そういったものはどんどん拡充していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"この出された陳情に対して、様々、今回だけではなくて、皆様からお声をいただいております。具体的な支援策につなげていただきたいなという、そういう思いは要望とさせていただいて、今回の陳情には不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"大倉委員","kind":"質問・要望","question":"どういうところをどう調査するか新たに考えていくということは、また、そこはしっかり国のほうでやってほしいと求めました。今、経過措置で負担割合が変わっていくという中で、今後の対応はぜひ進めていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でも、そのために国に区としては求めていくことをしない。応援するというのだったら、そうした形をしっかりと、こういう請願・陳情に応えていただく形でもやっていただきたいと私はすごく思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"国のやるべき事業だと思いますが、区から総務省や東京都などに働きかけ、事業主の実態を調査してほしいと求めました。今、インボイス制度で困られている方の手助けになるように、区でできるだけ働きかけてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"松本委員","kind":"質問・要望","question":"必ずしもインボイスの中止を求めるものではないけれども、これは今、ほかの政党も含めて考えているところだと思います。国に何か要望を出していく、あるいは、自治体として何か対策をとることができないかということのためにとったアンケートだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"それをきちんと国交省に伝えているではないですか、区長自ら。同じ気持ちであるべきだと私は思っておりますので、ぜひ見直しを図って調査をしていただきたいという強い思いを込めて、賛成としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"}]},{"id":"topic-05","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そういう問題点について指摘しているかと思うのですけれども、そこには自由意見として、区に対しての意見として何か出ていたのですか。そういうご意見が１００件ありました、２００件ありましたでもいいですけれども、意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837879?Template=document&Id=6823#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":68184,"voices":320}},{"id":"r06-20240925-6","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"区民委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"令和６年度八潮地区まちづくり事業の進捗状況","agenda":"令和６年度八潮地区まちづくり事業の進捗状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"業者名が分かれば教えていただきたいというのが１点と、八潮みらい懇談会について伺いたいのですが、構成みたいなのが分かれば教えてください。それと、八潮地区の防災についての現状と課題というのは具体的にどういうことなのか伺いたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"例えば現状の防災訓練の実施状況ですとか、他団体と連携した防災活動の実施内容といったものについて調査をかけさせていただいておりまして。まだ検討中のところはあるのですけれども、ざっくりとした回答にはなってしまいますが、そのように考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"このアクティビティマップというのはどういうふうになったのか、ちょっと気になったので、どのような内容になったのかをお伺いしたい。今１７人でまだ続いているということですが、どういう年齢、職層の方がインタビューにお答えしたのかをお伺いしたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"今回実施しているインタビューですとか、今の時点で、例えばパブリックコメントを実施したりといったところは考えてはおりません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"別紙２について伺いたいのですが、１班のところで、駅の計画の現状についてどうなっているのかを伺いたいと思います。私はコンセプトには入れるべきではないと思いますけれども、品川区の考えはどうなのでしょうか、伺いたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"セミナーの中では、それぞれ参加者が自由に意見を出していって、この中の１つとしてカジノという意見が挙げられたというようなところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、別紙３について最後にお伺いするのですが、その解決に向けて区はどのような方策を考えているのか伺いたいと思います。割合について伺いたいのと、あとその原因は何なのか、区として考えているところがあれば伺いたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"植栽とかが伸びて１つの通路が塞がれてしまうと、しかるべき事業者等につないでいくといったところに、現状は取り組んでいるところです。で、分譲住宅については、そういった意味での動きは少ないといったような状況があります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"すみません、お店の課題についても何か書いてあったのですが、これについてはいかがでしょうか。課題の解決に向けて、区として今どのように考えているのか。","respondent":"今井八潮まちづくり担当課長","answer":"そういったところを今検討しているところでございまして、元気食堂というＮＰＯ団体が運営する食堂などもあったりしますので、こういったところの取組を少し広げていったりとかというところで対応できればと考えているところです。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"まちづくりコンセプトを検討していく中で、基本的なことですけれども、基本情報の整理で地区の概要、人口データの分析などと書いてあるのですけれども、ざっくりでいいので年齢層の人口データと、外国人比率なども併せて分かればお知らせほしいと求めました。","respondent":"今井八潮まちづくり担当課長","answer":"５２.６％、年少人口については１,２１９人ということで、１０.５％です。令和５年１０月１日時点の数字になってしまいますが、８７１人ということで、７から８％程度です。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"担当の方にお聞きすると、３８９筆つけて出てきた陳情とかを目にしていたので、よろしくお願いします。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"別紙３にノルウェーとかニュージーランドの例が参考で出されていましたが、こういった取組は検討中ということであったと思いますが、紹介された事例などを実際に具体化するにあたっての現場の声とか、改めて課題とかについて教えてほしいと求めました。","respondent":"今井八潮まちづくり担当課長","answer":"そういった課題を区としても認識しておりまして、これまで八潮の中で、新たな担い手を発掘するという目的を持って進めさせていただいているものです。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"人材同士の結びつきということで確認させていただきました。次の地域の担い手となると思われますので、より一層引き続き環境づくりを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"基本的に今の八潮のまちづくりをどうするかで、今住んでいる方たちがどうしていくかというようなことを今ここでやっているのですか。将来八潮をどうしていくかというのに向けて、今八潮のまちをどうしていくかというのを考えているのか、現状はどうなのか教えてもらってもいいか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"それを進めていくことで八潮地域内の魅力を向上していく、それによって外からの人も集まってくるといったところを将来的な目的としています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"確認","question":"要は住んでいる人たちがどうやってまちで持続可能的に生活ができるようになるか、プラス、今品川区が取り組んでいる施策ということでいいですね。もう一回確認します。","respondent":"今井八潮まちづくり担当課長","answer":"委員ご指摘のとおりです。人口の、高齢化の部分とかというところにも、少し解決策が見えてくるような取組ができればなと考えております。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"していただきたいのは、これはそれこそ４０年後はどうなるのといったときに、彼らは正直建てて終わりなわけですよ。そこにどうやって新しい要素を入れていくかというのも、例えば医療をもっとあれしてほしいとか、違うニーズが出ているわけですよ。","respondent":"今井八潮まちづくり担当課長","answer":"委員にご指摘いただきました内容については、やはり八潮まちづくり担当が設置された目的といたしましては、今マンションが多く建っているところで。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"最初に１つお伺いしたいのは、まちづくりの取組テーマが４つ挙げられていて、ここの関連性というのはどうなってくるのかなというのをまずお聞きしたい。","respondent":"今井八潮まちづくり担当課長","answer":"都市計画ということで、ハード整備部門のほうで八潮のまちづくりを考えたときに、ハードをメインに捉えた形で策定されたものと認識しています。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"ハードとソフトということで、そこは理解しました。何というのですか、あとは品川区に関わっている方たちとかに意見を聞く場というのはあるのでしょうか、説明を求めました。","respondent":"今井八潮まちづくり担当課長","answer":"基本的に八潮在住の方に限定しているものではなくて、そういった方にもインタビューを実施させていただいておりまして、外からの視点というのも。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"進めていただきたい部分はあるのですけれども、いろいろな方にご意見を伺いながら、ぜひいろいろな課題も含めて検討していってほしいなという私の要望だけお伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問","question":"だから、これが今地道に始められている八潮のまちづくりの検討を始められている方のお話に、どういうふうに結びついたのだろうか。すみません、この方をセミナーの基調講演に選ばれた理由と、これを今後のまちづくりにどのような方向で活かそうとされているか伺えればと思います。","respondent":"今井八潮まちづくり担当課長","answer":"今回、八潮まちづくりコンセプト検討を行うに当たってのコンサルティングを入れている事業者が、飯田所長のほうに基調講演をお願いしています。","id":"exchange-016"},{"speaker":"吉田副委員長","kind":"質問","question":"本当にまだお話を聞いたことのない方は、ぜひ１回聞いてみられるといいかと思うのですが、とにかく聞いた人は元気になるのですよ。その辺も、コンサルタントとして環境エネルギー政策研究所が引き受けてくださったのか、その辺を伺えますか。","respondent":"今井八潮まちづくり担当課長","answer":"結論から言いますと、ファシリテートにつきましても、こちらの環境エネルギー政策研究所の主任研究員の山下さんにやっていただきましたので、グループワークについても、こちらの基調講演の内容に引き続いて討論をしていただいたというような内容になります。","id":"exchange-017"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"本当に、基調講演のお話をいただいた方だと思いますので、ぜひこれを本当に地域の方たちが元気になるような活動に結びつけていただけたらと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"臨海部広域斎場組合施設整備基本方針","agenda":"臨海部広域斎場組合施設整備基本方針","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"将来を見越して必要な改修、増築だと思います。幾つかお伺いしたいのですが、金額が分かれば教えていただきたいのと、そこについてはどのような検討になっているのか伺いたいと思います。","respondent":"築山戸籍住民課長","answer":"これも同じく基本方針の７ページ、４の（２）をご覧ください。省エネ型空調設備やＬＥＤ照明などの脱炭素化に資する整備について検討する」というところで、今後設計において進めていくと聞いております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"よく聞くのですが、併せて手段を検討していただきたいと思うのですけれども、やっぱり区民の方から要望を受けるのですよね。そちらについてはいかがか尋ねました。","respondent":"築山戸籍住民課長","answer":"バス便を増便するといったような検討等も臨海斎場でされてはいるのですけれども、なかなか厳しい状況もあるというところを聞いているところです。現状としましては、葬儀会社のほうでマイクロバス等も出しておりますので、そちらをご利用いただいていると認識しております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"３月に斎場のほうで調査していたというのは初耳でした。もう少し私もきちんとどれだけ要望が強いかというのも聴取したいと思うのですけれども、区として独自に対策を講じるなど、こちらは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"おぎの委員","kind":"質問","question":"私のほうから１点だけ、そういった利便性のほうは、一応検討はされているのか尋ねました。","respondent":"築山戸籍住民課長","answer":"駐車場の関係のご質問です。そうしますと８５台分が新しい施設によって潰れる形になりますけれども、増築後も駐車場は足りるだろうという見込みであることを聞いております。","id":"exchange-022"},{"speaker":"おぎの委員","kind":"意見","question":"どうしてもちょっと離れたところにあるので、バスや車などの利便性などをしっかり考えていただいているということで安心いたしました。使いやすいようにとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"今、安藤委員の質疑の中でマイクロバスを活用されているというのだけれども、マイクロバスというのは大井町の駅から出ているのですか。その経路がどういう経路になっているのか説明を求めました。","respondent":"築山戸籍住民課長","answer":"マイクロバスを利用の場合、葬儀会社が直接手配しますので、葬儀会場から火葬場という形になります。もしくは、式場を臨海斎場とする場合は、ご自宅から臨海斎場というような利用をされるかと思います。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問","question":"大井町や品川区側からなかなか行きづらいという話なので、マイクロバスというのは、また別の用途ということですか。うまくそういうのも活用できないのかなというのもあるのではないかなと思うのだけれども、その辺、改めてちょっと説明を求めました。","respondent":"築山戸籍住民課長","answer":"これはまた先ほどの回答とはちょっと変わってきますけれども、そこから徒歩で歩いてくる方もいらっしゃいますし、様々な方がいらっしゃいます。いろいろな所から来ているということを考えると、費用対効果としてはどうなのかといった意見も出ているところです。","id":"exchange-025"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういうのも含めてぜひ利便性向上の検討をしていただきたいなと思うので、そこは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"品川歴史館リニューアル特別記念展「品川の海に御台場ができるまで」","agenda":"品川歴史館リニューアル特別記念展「品川の海に御台場ができるまで」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"リニューアルした品川歴史館に訪れていただきたいということで、周知ですが、「ほか」というのがあるのです。そういった工夫があるとさらに多くの方に来ていただけるのかなと思うのですけれども、そちらについて、お考えなどがあれば尋ねました。","respondent":"大森文化観光戦略課長","answer":"１０月１０日の読売新聞の朝刊と１０月１１日の東京新聞、そちらのほうに掲載されるところです。ＳＮＳとかそういったものへの掲載も随時検討してまいりたいと思います。","id":"exchange-027"}]},{"id":"topic-04","title":"しながわシティランのボランティア募集","agenda":"しながわシティランのボランティア募集","exchanges":[{"speaker":"ゆきた委員","kind":"質問","question":"一般的なマラソン大会では、多くはボランティアの証明書が発行できることが多いと思いますけれども、しながわシティランではボランティア証明書は発行できることになるのか、１点だけお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"ボランティア証明書につきましては、大会後に希望する方に対して配付することを予定しております。","id":"exchange-028"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"大学受験とかで、ぜひスムーズな、また証明書発行についてもスムーズな入手ができるような形でお願いできればと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。一緒に参加をしてもらう機会というのを創出してもらったら、いろいろな効果があるのかなと思うのだけれども、そこは何か別で考えていますかとの意見を述べました。","respondent":"三井スポーツ推進課長","answer":"まずランナーとしての参加はもちろん考えているのですが、ボランティアとかそういったことは現時点では考えていないです。は応援といった中で、まずは応援のところで参加していただきたいなというのが一番こちらとしては考えているところです。","id":"exchange-030"},{"speaker":"石田（し）委員","kind":"意見","question":"子どもたちも入れてあげられればいいなと思うので、やってもらえるといい教育の機会になるのかなと思うので、ぜひ検討していただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ、品川区民芸術祭との関係というのは何かあるのですか。その期間中ではないか尋ねました。","respondent":"大森文化観光戦略課長","answer":"品川区民芸術祭とは別建てで開催しているところです。こちらはできたのが３年前ということで、今後の検討課題というところではあるのですが、今後の検討課題とさせていただきたいと思います。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"そういったイベントがありますよというのが、そちらにも分かるような形で相互連携して周知に努めていただければと思うのですけれどもいかがか。デフリンピック自体がすごいチャンスだという思いがあるのですが、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"今日はちょっと間に合わなかったのですが、今連携しておりまして、「あつまれ！えばら」のチラシに入れていただく方向で調整をしております。","id":"exchange-033"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"高橋（伸）委員長","kind":"質問・要望","question":"どういう視点を持って調査をしていきたいか、どういうことを先方に聞いて確認したいかなどを、ご意見や質問事項を出してほしいと求めました。現時点において、視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"広島のところで、来年東京ではありますけれども、デフリンピックがあるということで、デフスポーツについて、普及などに力を入れているところについて、やっぱり伺いたいなです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=6831#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":33761,"voices":100}}]);
